export interface Transaction {
  id: string;
  amount: number;
  type: TransactionType;
  category: string;
  memberId: string;
  userId?: string;
  note: string;
  date: string;
  rawNote?: string;
  projectId?: string; // Link to a project
  linkedExpenseId?: string; // Explicit link to a mandatory expense
}

