export interface MeterReading {
  id: string;
  type: 'water_hot' | 'water_cold' | 'electricity' | 'gas';
  value: number;
  date: string;
  prevValue?: number;
}

export interface LoyaltyCard {
  id: string;
  name: string;
  number: string;
  color: string;
  icon: string;
  barcodeFormat?: 'qr' | 'aztec' | 'code128' | 'ean13' | 'other'; // Enhanced barcode support
}

export interface MandatoryExpense {
  id: string;
  name: string;
  amount: number;
  day: number; // Day of the month (1-31)
  remind: boolean;
  keywords?: string[];
  memberId?: string; // Adding memberId
}

export interface WidgetConfig {
  id: string;
  isVisible: boolean;
  mobile: { colSpan: number; rowSpan: number };
  desktop: { colSpan: number; rowSpan: number };
}

export interface AppNotification {
  id: string;
  title: string;
  message: string;
  date: string;
  type: 'info' | 'warning' | 'success' | 'error';
  isRead: boolean;
}

export interface FeedbackItem {
  id: string;
  comment: string;
  elementTag: string; // e.g. "BUTTON"
  elementClass: string;
  screenshot?: string; // Base64 screenshot
  timestamp: string;
  status: 'open' | 'fixed';
  path: string; // Current URL path
}

export interface AppSettings {
  familyName: string;
  currency: string;
  startOfMonthDay: number;
  privacyMode: boolean;
  theme: 'light' | 'dark'; // New Theme property
  savingsRate: number; // PERSISTED SAVINGS RATE

  // New: Store API Key in settings
  geminiApiKey?: string;

  widgets: WidgetConfig[]; 

  isPinEnabled: boolean;
  pinCode?: string; // Stored PIN

  enabledTabs: string[];
  enabledServices: string[];
  defaultBudgetMode: 'personal' | 'family'; 

  telegramBotToken?: string;
  telegramChatId?: string;
  telegramState?: {
    lastShoppingMessageId: number;
    lastShoppingDate: string;
  };
  autoSendEventsToTelegram: boolean;

  // Push Notifications
  pushEnabled: boolean;
  fcmToken?: string;

  eventTemplate?: string;
  shoppingTemplate?: string;

  dayStartHour: number;
  dayEndHour: number;

  initialBalance: number;
  initialBalanceDate?: string;
  salaryDates: number[];
  mandatoryExpenses: MandatoryExpense[];
  enableSmartReserve?: boolean; // Toggle for deducting mandatory expenses from budget

  // New: Manual control over reserve
  manualReservedAmount?: number; 
  // Map of "YYYY-MM" -> [expenseId1, expenseId2] (Paid manually)
  manualPaidExpenses?: Record<string, string[]>;

  // Stores IDs of transaction pairs marked as "Not a duplicate"
  // Format: "id1_id2" (sorted alphabetically)
  ignoredDuplicatePairs?: string[];

  // Debugging & Development
  showFeedbackTool?: boolean;

  alfaMapping: {
    date: string;
    time: string;
    amount: string;
    category: string;
    note: string;
  };
}

export interface Category {
  id: string;
  label: string;
  icon: string;
  color: string;
  isCustom?: boolean;
}

export enum Type {
  TYPE_UNSPECIFIED = 'TYPE_UNSPECIFIED',
  STRING = 'STRING',
  NUMBER = 'NUMBER',
  INTEGER = 'INTEGER',
  BOOLEAN = 'BOOLEAN',
  ARRAY = 'ARRAY',
  OBJECT = 'OBJECT',
  NULL = 'NULL',
}

import React, { useState } from 'react';
import { 
  Plus, X, PieChart, Bell, Calendar, CreditCard, Clock, Trash2, 
  CheckCircle2, Send, Globe, RotateCcw, Target, AlertTriangle 
} from 'lucide-react';
import { Debt, AppSettings } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { addItem, updateItem, deleteItem } from '../utils/db';

interface Props {
  debts: Debt[];
  setDebts: (d: Debt[]) => void;
  settings: AppSettings;
}

const DebtSnowball: React.FC<Props> = ({ debts, setDebts, settings }) => {
  const [showNotifySettings, setShowNotifySettings] = useState<Debt | null>(null);
  const [showDebtStats, setShowDebtStats] = useState<Debt | null>(null);
  const [editingDebt, setEditingDebt] = useState<Partial<Debt> | null>(null);
  const { familyId } = useAuth();

  const handleUpdateDebt = async (e: React.FormEvent) => {
    e.preventDefault();
    const target = e.target as typeof e.target & {
        title: { value: string };
        totalAmount: { value: string };
        paidAmount: { value: string };
        monthlyPayment: { value: string };
        dueDate: { value: string };
        finalClosingDate: { value: string };
    };

    const totalAmount = Number(target.totalAmount.value);
    const paidAmount = Number(target.paidAmount.value);
    const currentBalance = totalAmount - paidAmount;

    const updatedDebt: Partial<Debt> = {
      ...editingDebt,
      name: target.title.value,
      totalAmount: totalAmount,
      currentBalance: currentBalance,
      monthlyPayment: Number(target.monthlyPayment.value),
      dueDate: target.dueDate.value,
      finalClosingDate: target.finalClosingDate.value,
      channels: editingDebt?.channels || ['site'],
      notifyBefore: editingDebt?.notifyBefore || 3,
      notifyIfOverdue: editingDebt?.notifyIfOverdue ?? true,
      color: '#FF3B30' // Default color required by type, though not used in new UI
    };

    if (editingDebt?.id) {
      const newDebt = { ...updatedDebt, id: editingDebt.id } as Debt;
      setDebts(debts.map(d => d.id === editingDebt.id ? newDebt : d));
      if (familyId) await updateItem(familyId, 'debts', editingDebt.id, newDebt);
    } else {
      const newId = Date.now().toString();
      const newDebt = { ...updatedDebt, id: newId, paidThisMonth: false } as Debt;
      setDebts([...debts, newDebt]);
      if (familyId) await addItem(familyId, 'debts', newDebt);
    }
    setEditingDebt(null);
  };

  const togglePaidStatus = async (id: string) => {
    const debt = debts.find(d => d.id === id);
    if (!debt) return;

    const isCurrentlyPaid = debt.paidThisMonth;
    const payment = debt.monthlyPayment || 0;

    // Logic: If marking as paid, reduce balance (increase paid amount). If unmarking, revert.
    // Note: The UI calculates 'paidAmount' dynamically from total - balance usually, 
    // but here we update balance directly.

    let newBalance = debt.currentBalance;
    if (!isCurrentlyPaid) {
        // Pay
        newBalance = Math.max(0, debt.currentBalance - payment);
    } else {
        // Undo Pay
        newBalance = Math.min(debt.totalAmount, debt.currentBalance + payment);
    }

    const updates = { 
        currentBalance: newBalance,
        paidThisMonth: !isCurrentlyPaid 
    };

    setDebts(debts.map(d => d.id === id ? { ...d, ...updates } : d));
    if (familyId) await updateItem(familyId, 'debts', id, updates);
  };

  const handleDelete = async (id: string) => {
      if(confirm('Удалить этот долг?')) {
          setDebts(debts.filter(d => d.id !== id));
          if (familyId) await deleteItem(familyId, 'debts', id);
          setEditingDebt(null);
      }
  };

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return 'Не указана';
    return new Date(dateStr).toLocaleDateString('ru-RU');
  };

  const isOverdue = (dateStr?: string, isPaid?: boolean) => {
    if (!dateStr || isPaid) return false;
    // Set comparison to end of due date day
    const due = new Date(dateStr);
    due.setHours(23, 59, 59, 999);
    return due < new Date();
  };

  // Helper to calculate Paid Amount for UI (Total - Balance)
  const getPaidAmount = (d: Debt) => d.totalAmount - d.currentBalance;

  return (
    <div className="flex w-full h-full bg-[#0F1115] text-[#E2E8F0] font-sans rounded-[2.5rem] overflow-hidden border border-white/5 shadow-2xl">
      <main className="flex-1 flex flex-col h-full overflow-hidden">
        {/* Header adapted for embedded view */}
        <header className="px-6 py-5 flex items-center justify-between bg-[#16191F]/50 backdrop-blur-md border-b border-gray-800 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <CreditCard size={24} className="text-white" />
            </div>
            <div>
              <h1 className="text-lg font-bold text-white tracking-tight">Мои долги</h1>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Управление выплатами</p>
            </div>
          </div>
          <button 
            onClick={() => setEditingDebt({ id: undefined, name: '', totalAmount: 0, currentBalance: 0, monthlyPayment: 0, dueDate: '', finalClosingDate: '', channels: ['site'], notifyBefore: 3, notifyIfOverdue: true })}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-xl text-xs font-bold transition-all shadow-lg shadow-indigo-600/20"
          >
            <Plus size={16} /> <span className="hidden sm:inline">Добавить</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 no-scrollbar">
          {debts.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-500">
                  <Smile size={48} className="mb-4 opacity-20" />
                  <p className="font-bold text-xs uppercase tracking-widest">Долгов нет! 🎉</p>
              </div>
          ) : (
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 md:gap-6">
                {debts.map((debt) => {
                  const overdue = isOverdue(debt.dueDate, debt.paidThisMonth);
                  const paidAmt = getPaidAmount(debt);
                  const progress = Math.min(100, (paidAmt / debt.totalAmount) * 100);

                  return (
                    <div key={debt.id} className={`bg-[#16191F] rounded-[32px] border p-5 relative overflow-hidden group transition-all ${overdue ? 'border-rose-500/50 shadow-[0_0_20px_rgba(244,63,94,0.1)]' : 'border-gray-800 hover:border-indigo-500/40'}`}>
                      {/* Status Bar */}
                      <div className={`absolute top-0 left-0 w-1.5 h-full transition-all ${debt.paidThisMonth ? 'bg-emerald-500' : (overdue ? 'bg-rose-500 animate-pulse' : 'bg-indigo-500')}`}></div>

                      <div className="flex justify-between items-start mb-6 pl-2">
                        <div onClick={() => setEditingDebt(debt)} className="cursor-pointer flex-1 mr-2">
                          <div className="flex items-center gap-2">
                            <h4 className="text-lg font-bold text-white group-hover:text-indigo-400 transition-colors truncate">{debt.name}</h4>
                            {overdue && <AlertTriangle size={16} className="text-rose-500 shrink-0" />}
                          </div>
                          <div className="mt-2">
                            <div className="flex items-center gap-1.5 text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                              <Target size={12} className="text-indigo-400" /> 
                              <span>Финал: {formatDate(debt.finalClosingDate)}</span>
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-2 shrink-0">
                          <button onClick={() => setShowNotifySettings(debt)} className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all ${(debt.notifyBefore || 0) > 0 ? 'bg-indigo-500 text-white' : 'bg-[#1C2128] text-gray-500'}`}>
                            <Bell size={16} />
                          </button>
                          <button 
                            onClick={() => togglePaidStatus(debt.id)} 
                            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all ${debt.paidThisMonth ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-[#1C2128] text-gray-500 hover:text-white hover:bg-emerald-500'}`}
                          >
                            {debt.paidThisMonth ? <RotateCcw size={16} /> : <CheckCircle2 size={16} />}
                          </button>
                        </div>
                      </div>

                      <div className="space-y-4 pl-2">
                        <div className={`p-3 rounded-2xl border flex items-center justify-between ${overdue ? 'bg-rose-500/5 border-rose-500/20' : 'bg-[#1C2128] border-gray-800/50'}`}>
                          <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${overdue ? 'bg-rose-500/20 text-rose-500' : 'bg-indigo-500/10 text-indigo-400'}`}>
                              <Calendar size={18} />
                            </div>
                            <div>
                              <p className="text-[9px] font-bold text-gray-500 uppercase">Платёж до</p>
                              <p className={`text-sm font-bold ${overdue ? 'text-rose-400' : 'text-white'}`}>{formatDate(debt.dueDate)}</p>
                            </div>
                          </div>
                          {overdue && <span className="text-[9px] font-black bg-rose-500 text-white px-2 py-0.5 rounded-full animate-bounce">ПРОСРОЧЕНО</span>}
                        </div>

                        <div className={`flex justify-between p-4 rounded-2xl bg-indigo-600/5 border border-indigo-500/20 items-center`}>
                          <div>
                            <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">Взнос</p>
                            <p className="text-xl font-black text-white">{(debt.monthlyPayment || 0).toLocaleString()} ₽</p>
                          </div>
                          <button 
                            onClick={() => setShowDebtStats(debt)}
                            className="flex items-center gap-1.5 px-3 py-2 bg-indigo-600/20 hover:bg-indigo-600/40 text-indigo-400 rounded-xl text-[10px] font-black transition-all uppercase tracking-tighter"
                          >
                            <PieChart size={14} /> Статистика
                          </button>
                        </div>

                        <div className="space-y-2">
                          <div className="flex justify-between text-[11px] font-bold uppercase tracking-widest text-gray-500 px-1">
                            <span>Прогресс</span>
                            <span className="text-indigo-400">{progress.toFixed(1)}%</span>
                          </div>
                          <div className="h-2 w-full bg-gray-800 rounded-full overflow-hidden">
                            <div className={`h-full rounded-full transition-all duration-700 ease-out ${debt.paidThisMonth ? 'bg-emerald-500' : (overdue ? 'bg-rose-500' : 'bg-indigo-500')}`} style={{ width: `${progress}%` }} />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
          )}
        </div>
      </main>

      {/* DEBT INDIVIDUAL STATS MODAL */}
      {showDebtStats && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/95 backdrop-blur-md" onClick={() => setShowDebtStats(null)}></div>
          <div className="relative w-full max-w-lg bg-[#16191F] border border-gray-800 rounded-[32px] overflow-hidden shadow-2xl">
            <div className="p-8 space-y-8">
              <div className="flex justify-between items-center">
                <div>
                  <h3 className="text-2xl font-black text-white">{showDebtStats.name}</h3>
                  <p className="text-sm text-gray-500 font-bold uppercase mt-1">Детальный расчет</p>
                </div>
                <button onClick={() => setShowDebtStats(null)} className="w-10 h-10 bg-gray-800 rounded-full flex items-center justify-center text-gray-400 hover:text-white transition-colors">
                  <X size={20} />
                </button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-[#1C2128] p-5 rounded-2xl border border-gray-800">
                  <p className="text-[10px] font-black text-gray-500 uppercase mb-1">Выплачено</p>
                  <p className="text-lg font-black text-emerald-400">{getPaidAmount(showDebtStats).toLocaleString()} ₽</p>
                </div>
                <div className="bg-[#1C2128] p-5 rounded-2xl border border-gray-800">
                  <p className="text-[10px] font-black text-gray-500 uppercase mb-1">Остаток</p>
                  <p className="text-lg font-black text-rose-400">{showDebtStats.currentBalance.toLocaleString()} ₽</p>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-xs font-black text-gray-500 uppercase flex items-center gap-2">
                  <Clock size={14} /> Календарь платежей
                </h4>
                <div className="space-y-2">
                  {[0, 1, 2].map(i => {
                    const date = showDebtStats.dueDate ? new Date(showDebtStats.dueDate) : new Date();
                    date.setMonth(date.getMonth() + i);
                    return (
                      <div key={i} className={`flex items-center justify-between p-4 rounded-xl border ${i === 0 && !showDebtStats.paidThisMonth ? 'bg-indigo-600/10 border-indigo-500/30' : 'bg-gray-800/20 border-gray-800'}`}>
                        <div className="flex items-center gap-3">
                          <span className="text-xs font-bold text-gray-400 capitalize">{date.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' })}</span>
                        </div>
                        <div className="flex items-center gap-4">
                          <p className="text-sm font-bold text-white">{(showDebtStats.monthlyPayment || 0).toLocaleString()} ₽</p>
                          {i === 0 && showDebtStats.paidThisMonth ? (
                            <CheckCircle2 size={16} className="text-emerald-500" />
                          ) : (
                            <div className="w-4 h-4 rounded-full border-2 border-gray-700" />
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div className="pt-4 border-t border-gray-800">
                 <div className="flex justify-between items-center text-xs font-bold">
                   <span className="text-gray-500">Дата полного закрытия</span>
                   <span className="text-white bg-indigo-600/20 px-3 py-1 rounded-lg border border-indigo-500/20">{formatDate(showDebtStats.finalClosingDate)}</span>
                 </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* NOTIFY MODAL */}
      {showNotifySettings && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/90 backdrop-blur-sm" onClick={() => setShowNotifySettings(null)}></div>
          <div className="relative w-full max-w-sm bg-[#16191F] border border-gray-800 rounded-[32px] p-8">
            <h3 className="text-xl font-bold mb-6 text-white">Уведомления</h3>

            <div className="space-y-6">
              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase block mb-3">Напоминать за (дней)</label>
                <input 
                  type="number" 
                  value={showNotifySettings.notifyBefore ?? 3}
                  onChange={async (e) => {
                    const val = parseInt(e.target.value) || 0;
                    const updates = { notifyBefore: val };
                    setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                    setShowNotifySettings({...showNotifySettings, ...updates});
                    if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                  }}
                  className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3 font-bold focus:border-indigo-500 outline-none"
                />
              </div>

              <div 
                onClick={async () => {
                  const newVal = !showNotifySettings.notifyIfOverdue;
                  const updates = { notifyIfOverdue: newVal };
                  setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                  setShowNotifySettings({...showNotifySettings, ...updates});
                  if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                }}
                className={`flex items-center justify-between p-4 rounded-2xl border cursor-pointer transition-all ${showNotifySettings.notifyIfOverdue ? 'bg-rose-500/10 border-rose-500/40 text-rose-400' : 'bg-[#1C2128] border-gray-800 text-gray-500'}`}
              >
                <div className="flex items-center gap-3">
                  <AlertTriangle size={18} />
                  <span className="text-xs font-bold">О просрочке</span>
                </div>
                <div className={`w-10 h-5 rounded-full relative transition-colors ${showNotifySettings.notifyIfOverdue ? 'bg-rose-500' : 'bg-gray-700'}`}>
                  <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${showNotifySettings.notifyIfOverdue ? 'left-6' : 'left-1'}`} />
                </div>
              </div>

              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase block mb-3">Каналы</label>
                <div className="space-y-2">
                  {[
                    { id: 'site', label: 'Push-уведомления', icon: <Globe size={14}/> },
                    { id: 'telegram', label: 'Telegram Бот', icon: <Send size={14}/> }
                  ].map(ch => {
                    const currentChannels = showNotifySettings.channels || [];
                    const isSelected = currentChannels.includes(ch.id);
                    return (
                        <div 
                        key={ch.id}
                        onClick={async () => {
                            const newChannels = isSelected 
                            ? currentChannels.filter(c => c !== ch.id)
                            : [...currentChannels, ch.id];
                            const updates = { channels: newChannels };
                            setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                            setShowNotifySettings({...showNotifySettings, ...updates});
                            if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                        }}
                        className={`flex items-center justify-between p-3 rounded-xl border cursor-pointer transition-all ${isSelected ? 'bg-indigo-600/10 border-indigo-600 text-white' : 'bg-[#1C2128] border-gray-800 text-gray-500 hover:border-gray-600'}`}
                        >
                        <div className="flex items-center gap-2 text-xs font-bold">
                            {ch.icon} {ch.label}
                        </div>
                        <div className={`w-4 h-4 rounded-sm border ${isSelected ? 'bg-indigo-500 border-indigo-500' : 'border-gray-600'}`} />
                        </div>
                    );
                  })}
                </div>
              </div>
            </div>
            <button onClick={() => setShowNotifySettings(null)} className="w-full mt-8 py-4 bg-indigo-600 text-white rounded-2xl text-xs font-bold">Закрыть</button>
          </div>
        </div>
      )}

      {/* EDIT/ADD MODAL */}
      {editingDebt && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/90 backdrop-blur-sm" onClick={() => setEditingDebt(null)}></div>
          <form onSubmit={handleUpdateDebt} className="relative w-full max-w-md bg-[#16191F] border border-gray-800 rounded-[32px] p-8 animate-in zoom-in-95 max-h-[95vh] overflow-y-auto no-scrollbar shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold text-white">{editingDebt.id ? 'Редактировать' : 'Новый долг'}</h3>
              {editingDebt.id && (
                <button type="button" onClick={() => handleDelete(editingDebt.id!)} className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all">
                  <Trash2 size={20} />
                </button>
              )}
            </div>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Название</label>
                <input name="title" defaultValue={editingDebt.name} placeholder="Кредит, Ипотека..." required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase ml-1 text-indigo-400">Срок полного закрытия (финал)</label>
                <input name="finalClosingDate" type="date" defaultValue={editingDebt.finalClosingDate} required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Общая сумма</label>
                  <input name="totalAmount" type="number" defaultValue={editingDebt.totalAmount} placeholder="0" required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Выплачено</label>
                  <input 
                    name="paidAmount" 
                    type="number" 
                    // Calculate paid amount from current balance if editing
                    defaultValue={editingDebt.id ? ((editingDebt.totalAmount || 0) - (editingDebt.currentBalance || 0)) : ''} 
                    placeholder="0" 
                    required 
                    className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" 
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Месячный взнос</label>
                  <input name="monthlyPayment" type="number" defaultValue={editingDebt.monthlyPayment} placeholder="0" required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Дата взноса</label>
                  <input name="dueDate" type="date" defaultValue={editingDebt.dueDate} required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
              </div>
              <div className="flex gap-3 pt-6">
                <button type="button" onClick={() => setEditingDebt(null)} className="flex-1 py-4 bg-[#1C2128] text-gray-400 rounded-2xl text-xs font-bold">Отмена</button>
                <button type="submit" className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl text-xs font-bold">
                  {editingDebt.id ? 'Сохранить' : 'Создать'}
                </button>
              </div>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default DebtSnowball;

import React, { useState } from 'react';
import { 
  Plus, X, PieChart, Bell, Calendar, CreditCard, Clock, Trash2, 
  CheckCircle2, Send, Globe, RotateCcw, Target, AlertTriangle, Smile 
} from 'lucide-react';
import { Debt, AppSettings } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { addItem, updateItem, deleteItem } from '../utils/db';

interface Props {
  debts: Debt[];
  setDebts: (d: Debt[]) => void;
  settings: AppSettings;
}

const DebtSnowball: React.FC<Props> = ({ debts, setDebts, settings }) => {
  const [showNotifySettings, setShowNotifySettings] = useState<Debt | null>(null);
  const [showDebtStats, setShowDebtStats] = useState<Debt | null>(null);
  const [editingDebt, setEditingDebt] = useState<Partial<Debt> | null>(null);
  const { familyId } = useAuth();

  const handleUpdateDebt = async (e: React.FormEvent) => {
    e.preventDefault();
    const target = e.target as typeof e.target & {
        title: { value: string };
        totalAmount: { value: string };
        paidAmount: { value: string };
        monthlyPayment: { value: string };
        dueDate: { value: string };
        finalClosingDate: { value: string };
    };

    const totalAmount = Number(target.totalAmount.value);
    const paidAmount = Number(target.paidAmount.value);
    const currentBalance = totalAmount - paidAmount;

    const updatedDebt: Partial<Debt> = {
      ...editingDebt,
      name: target.title.value,
      totalAmount: totalAmount,
      currentBalance: currentBalance,
      monthlyPayment: Number(target.monthlyPayment.value),
      dueDate: target.dueDate.value,
      finalClosingDate: target.finalClosingDate.value,
      channels: editingDebt?.channels || ['site'],
      notifyBefore: editingDebt?.notifyBefore || 3,
      notifyIfOverdue: editingDebt?.notifyIfOverdue ?? true,
      color: '#FF3B30' // Default color required by type, though not used in new UI
    };

    if (editingDebt?.id) {
      const newDebt = { ...updatedDebt, id: editingDebt.id } as Debt;
      setDebts(debts.map(d => d.id === editingDebt.id ? newDebt : d));
      if (familyId) await updateItem(familyId, 'debts', editingDebt.id, newDebt);
    } else {
      const newId = Date.now().toString();
      const newDebt = { ...updatedDebt, id: newId, paidThisMonth: false } as Debt;
      setDebts([...debts, newDebt]);
      if (familyId) await addItem(familyId, 'debts', newDebt);
    }
    setEditingDebt(null);
  };

  const togglePaidStatus = async (id: string) => {
    const debt = debts.find(d => d.id === id);
    if (!debt) return;

    const isCurrentlyPaid = debt.paidThisMonth;
    const payment = debt.monthlyPayment || 0;

    // Logic: If marking as paid, reduce balance (increase paid amount). If unmarking, revert.
    // Note: The UI calculates 'paidAmount' dynamically from total - balance usually, 
    // but here we update balance directly.

    let newBalance = debt.currentBalance;
    if (!isCurrentlyPaid) {
        // Pay
        newBalance = Math.max(0, debt.currentBalance - payment);
    } else {
        // Undo Pay
        newBalance = Math.min(debt.totalAmount, debt.currentBalance + payment);
    }

    const updates = { 
        currentBalance: newBalance,
        paidThisMonth: !isCurrentlyPaid 
    };

    setDebts(debts.map(d => d.id === id ? { ...d, ...updates } : d));
    if (familyId) await updateItem(familyId, 'debts', id, updates);
  };

  const handleDelete = async (id: string) => {
      if(confirm('Удалить этот долг?')) {
          setDebts(debts.filter(d => d.id !== id));
          if (familyId) await deleteItem(familyId, 'debts', id);
          setEditingDebt(null);
      }
  };

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return 'Не указана';
    return new Date(dateStr).toLocaleDateString('ru-RU');
  };

  const isOverdue = (dateStr?: string, isPaid?: boolean) => {
    if (!dateStr || isPaid) return false;
    // Set comparison to end of due date day
    const due = new Date(dateStr);
    due.setHours(23, 59, 59, 999);
    return due < new Date();
  };

  // Helper to calculate Paid Amount for UI (Total - Balance)
  const getPaidAmount = (d: Debt) => d.totalAmount - d.currentBalance;

  return (
    <div className="flex w-full h-full bg-[#0F1115] text-[#E2E8F0] font-sans rounded-[2.5rem] overflow-hidden border border-white/5 shadow-2xl">
      <main className="flex-1 flex flex-col h-full overflow-hidden">
        {/* Header adapted for embedded view */}
        <header className="px-6 py-5 flex items-center justify-between bg-[#16191F]/50 backdrop-blur-md border-b border-gray-800 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <CreditCard size={24} className="text-white" />
            </div>
            <div>
              <h1 className="text-lg font-bold text-white tracking-tight">Мои долги</h1>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Управление выплатами</p>
            </div>
          </div>
          <button 
            onClick={() => setEditingDebt({ id: undefined, name: '', totalAmount: 0, currentBalance: 0, monthlyPayment: 0, dueDate: '', finalClosingDate: '', channels: ['site'], notifyBefore: 3, notifyIfOverdue: true })}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-xl text-xs font-bold transition-all shadow-lg shadow-indigo-600/20"
          >
            <Plus size={16} /> <span className="hidden sm:inline">Добавить</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 no-scrollbar">
          {debts.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-500">
                  <Smile size={48} className="mb-4 opacity-20" />
                  <p className="font-bold text-xs uppercase tracking-widest">Долгов нет! 🎉</p>
              </div>
          ) : (
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 md:gap-6">
                {debts.map((debt) => {
                  const overdue = isOverdue(debt.dueDate, debt.paidThisMonth);
                  const paidAmt = getPaidAmount(debt);
                  const progress = Math.min(100, (paidAmt / debt.totalAmount) * 100);

                  return (
                    <div key={debt.id} className={`bg-[#16191F] rounded-[32px] border p-5 relative overflow-hidden group transition-all ${overdue ? 'border-rose-500/50 shadow-[0_0_20px_rgba(244,63,94,0.1)]' : 'border-gray-800 hover:border-indigo-500/40'}`}>
                      {/* Status Bar */}
                      <div className={`absolute top-0 left-0 w-1.5 h-full transition-all ${debt.paidThisMonth ? 'bg-emerald-500' : (overdue ? 'bg-rose-500 animate-pulse' : 'bg-indigo-500')}`}></div>

                      <div className="flex justify-between items-start mb-6 pl-2">
                        <div onClick={() => setEditingDebt(debt)} className="cursor-pointer flex-1 mr-2">
                          <div className="flex items-center gap-2">
                            <h4 className="text-lg font-bold text-white group-hover:text-indigo-400 transition-colors truncate">{debt.name}</h4>
                            {overdue && <AlertTriangle size={16} className="text-rose-500 shrink-0" />}
                          </div>
                          <div className="mt-2">
                            <div className="flex items-center gap-1.5 text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                              <Target size={12} className="text-indigo-400" /> 
                              <span>Финал: {formatDate(debt.finalClosingDate)}</span>
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-2 shrink-0">
                          <button onClick={() => setShowNotifySettings(debt)} className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all ${(debt.notifyBefore || 0) > 0 ? 'bg-indigo-500 text-white' : 'bg-[#1C2128] text-gray-500'}`}>
                            <Bell size={16} />
                          </button>
                          <button 
                            onClick={() => togglePaidStatus(debt.id)} 
                            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all ${debt.paidThisMonth ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-[#1C2128] text-gray-500 hover:text-white hover:bg-emerald-500'}`}
                          >
                            {debt.paidThisMonth ? <RotateCcw size={16} /> : <CheckCircle2 size={16} />}
                          </button>
                        </div>
                      </div>

                      <div className="space-y-4 pl-2">
                        <div className={`p-3 rounded-2xl border flex items-center justify-between ${overdue ? 'bg-rose-500/5 border-rose-500/20' : 'bg-[#1C2128] border-gray-800/50'}`}>
                          <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${overdue ? 'bg-rose-500/20 text-rose-500' : 'bg-indigo-500/10 text-indigo-400'}`}>
                              <Calendar size={18} />
                            </div>
                            <div>
                              <p className="text-[9px] font-bold text-gray-500 uppercase">Платёж до</p>
                              <p className={`text-sm font-bold ${overdue ? 'text-rose-400' : 'text-white'}`}>{formatDate(debt.dueDate)}</p>
                            </div>
                          </div>
                          {overdue && <span className="text-[9px] font-black bg-rose-500 text-white px-2 py-0.5 rounded-full animate-bounce">ПРОСРОЧЕНО</span>}
                        </div>

                        <div className={`flex justify-between p-4 rounded-2xl bg-indigo-600/5 border border-indigo-500/20 items-center`}>
                          <div>
                            <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">Взнос</p>
                            <p className="text-xl font-black text-white">{(debt.monthlyPayment || 0).toLocaleString()} ₽</p>
                          </div>
                          <button 
                            onClick={() => setShowDebtStats(debt)}
                            className="flex items-center gap-1.5 px-3 py-2 bg-indigo-600/20 hover:bg-indigo-600/40 text-indigo-400 rounded-xl text-[10px] font-black transition-all uppercase tracking-tighter"
                          >
                            <PieChart size={14} /> Статистика
                          </button>
                        </div>

                        <div className="space-y-2">
                          <div className="flex justify-between text-[11px] font-bold uppercase tracking-widest text-gray-500 px-1">
                            <span>Прогресс</span>
                            <span className="text-indigo-400">{progress.toFixed(1)}%</span>
                          </div>
                          <div className="h-2 w-full bg-gray-800 rounded-full overflow-hidden">
                            <div className={`h-full rounded-full transition-all duration-700 ease-out ${debt.paidThisMonth ? 'bg-emerald-500' : (overdue ? 'bg-rose-500' : 'bg-indigo-500')}`} style={{ width: `${progress}%` }} />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
          )}
        </div>
      </main>

      {/* DEBT INDIVIDUAL STATS MODAL */}
      {showDebtStats && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/95 backdrop-blur-md" onClick={() => setShowDebtStats(null)}></div>
          <div className="relative w-full max-w-lg bg-[#16191F] border border-gray-800 rounded-[32px] overflow-hidden shadow-2xl">
            <div className="p-8 space-y-8">
              <div className="flex justify-between items-center">
                <div>
                  <h3 className="text-2xl font-black text-white">{showDebtStats.name}</h3>
                  <p className="text-sm text-gray-500 font-bold uppercase mt-1">Детальный расчет</p>
                </div>
                <button onClick={() => setShowDebtStats(null)} className="w-10 h-10 bg-gray-800 rounded-full flex items-center justify-center text-gray-400 hover:text-white transition-colors">
                  <X size={20} />
                </button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-[#1C2128] p-5 rounded-2xl border border-gray-800">
                  <p className="text-[10px] font-black text-gray-500 uppercase mb-1">Выплачено</p>
                  <p className="text-lg font-black text-emerald-400">{getPaidAmount(showDebtStats).toLocaleString()} ₽</p>
                </div>
                <div className="bg-[#1C2128] p-5 rounded-2xl border border-gray-800">
                  <p className="text-[10px] font-black text-gray-500 uppercase mb-1">Остаток</p>
                  <p className="text-lg font-black text-rose-400">{showDebtStats.currentBalance.toLocaleString()} ₽</p>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-xs font-black text-gray-500 uppercase flex items-center gap-2">
                  <Clock size={14} /> Календарь платежей
                </h4>
                <div className="space-y-2">
                  {[0, 1, 2].map(i => {
                    const date = showDebtStats.dueDate ? new Date(showDebtStats.dueDate) : new Date();
                    date.setMonth(date.getMonth() + i);
                    return (
                      <div key={i} className={`flex items-center justify-between p-4 rounded-xl border ${i === 0 && !showDebtStats.paidThisMonth ? 'bg-indigo-600/10 border-indigo-500/30' : 'bg-gray-800/20 border-gray-800'}`}>
                        <div className="flex items-center gap-3">
                          <span className="text-xs font-bold text-gray-400 capitalize">{date.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' })}</span>
                        </div>
                        <div className="flex items-center gap-4">
                          <p className="text-sm font-bold text-white">{(showDebtStats.monthlyPayment || 0).toLocaleString()} ₽</p>
                          {i === 0 && showDebtStats.paidThisMonth ? (
                            <CheckCircle2 size={16} className="text-emerald-500" />
                          ) : (
                            <div className="w-4 h-4 rounded-full border-2 border-gray-700" />
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div className="pt-4 border-t border-gray-800">
                 <div className="flex justify-between items-center text-xs font-bold">
                   <span className="text-gray-500">Дата полного закрытия</span>
                   <span className="text-white bg-indigo-600/20 px-3 py-1 rounded-lg border border-indigo-500/20">{formatDate(showDebtStats.finalClosingDate)}</span>
                 </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* NOTIFY MODAL */}
      {showNotifySettings && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/90 backdrop-blur-sm" onClick={() => setShowNotifySettings(null)}></div>
          <div className="relative w-full max-w-sm bg-[#16191F] border border-gray-800 rounded-[32px] p-8">
            <h3 className="text-xl font-bold mb-6 text-white">Уведомления</h3>

            <div className="space-y-6">
              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase block mb-3">Напоминать за (дней)</label>
                <input 
                  type="number" 
                  value={showNotifySettings.notifyBefore ?? 3}
                  onChange={async (e) => {
                    const val = parseInt(e.target.value) || 0;
                    const updates = { notifyBefore: val };
                    setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                    setShowNotifySettings({...showNotifySettings, ...updates});
                    if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                  }}
                  className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3 font-bold focus:border-indigo-500 outline-none"
                />
              </div>

              <div 
                onClick={async () => {
                  const newVal = !showNotifySettings.notifyIfOverdue;
                  const updates = { notifyIfOverdue: newVal };
                  setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                  setShowNotifySettings({...showNotifySettings, ...updates});
                  if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                }}
                className={`flex items-center justify-between p-4 rounded-2xl border cursor-pointer transition-all ${showNotifySettings.notifyIfOverdue ? 'bg-rose-500/10 border-rose-500/40 text-rose-400' : 'bg-[#1C2128] border-gray-800 text-gray-500'}`}
              >
                <div className="flex items-center gap-3">
                  <AlertTriangle size={18} />
                  <span className="text-xs font-bold">О просрочке</span>
                </div>
                <div className={`w-10 h-5 rounded-full relative transition-colors ${showNotifySettings.notifyIfOverdue ? 'bg-rose-500' : 'bg-gray-700'}`}>
                  <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${showNotifySettings.notifyIfOverdue ? 'left-6' : 'left-1'}`} />
                </div>
              </div>

              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase block mb-3">Каналы</label>
                <div className="space-y-2">
                  {[
                    { id: 'site', label: 'Push-уведомления', icon: <Globe size={14}/> },
                    { id: 'telegram', label: 'Telegram Бот', icon: <Send size={14}/> }
                  ].map(ch => {
                    const currentChannels = showNotifySettings.channels || [];
                    const isSelected = currentChannels.includes(ch.id);
                    return (
                        <div 
                        key={ch.id}
                        onClick={async () => {
                            const newChannels = isSelected 
                            ? currentChannels.filter(c => c !== ch.id)
                            : [...currentChannels, ch.id];
                            const updates = { channels: newChannels };
                            setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                            setShowNotifySettings({...showNotifySettings, ...updates});
                            if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                        }}
                        className={`flex items-center justify-between p-3 rounded-xl border cursor-pointer transition-all ${isSelected ? 'bg-indigo-600/10 border-indigo-600 text-white' : 'bg-[#1C2128] border-gray-800 text-gray-500 hover:border-gray-600'}`}
                        >
                        <div className="flex items-center gap-2 text-xs font-bold">
                            {ch.icon} {ch.label}
                        </div>
                        <div className={`w-4 h-4 rounded-sm border ${isSelected ? 'bg-indigo-500 border-indigo-500' : 'border-gray-600'}`} />
                        </div>
                    );
                  })}
                </div>
              </div>
            </div>
            <button onClick={() => setShowNotifySettings(null)} className="w-full mt-8 py-4 bg-indigo-600 text-white rounded-2xl text-xs font-bold">Закрыть</button>
          </div>
        </div>
      )}

      {/* EDIT/ADD MODAL */}
      {editingDebt && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/90 backdrop-blur-sm" onClick={() => setEditingDebt(null)}></div>
          <form onSubmit={handleUpdateDebt} className="relative w-full max-w-md bg-[#16191F] border border-gray-800 rounded-[32px] p-8 animate-in zoom-in-95 max-h-[95vh] overflow-y-auto no-scrollbar shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold text-white">{editingDebt.id ? 'Редактировать' : 'Новый долг'}</h3>
              {editingDebt.id && (
                <button type="button" onClick={() => handleDelete(editingDebt.id!)} className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all">
                  <Trash2 size={20} />
                </button>
              )}
            </div>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Название</label>
                <input name="title" defaultValue={editingDebt.name} placeholder="Кредит, Ипотека..." required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase ml-1 text-indigo-400">Срок полного закрытия (финал)</label>
                <input name="finalClosingDate" type="date" defaultValue={editingDebt.finalClosingDate} required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Общая сумма</label>
                  <input name="totalAmount" type="number" defaultValue={editingDebt.totalAmount} placeholder="0" required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Выплачено</label>
                  <input 
                    name="paidAmount" 
                    type="number" 
                    // Calculate paid amount from current balance if editing
                    defaultValue={editingDebt.id ? ((editingDebt.totalAmount || 0) - (editingDebt.currentBalance || 0)) : ''} 
                    placeholder="0" 
                    required 
                    className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" 
                  />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Месячный взнос</label>
                  <input name="monthlyPayment" type="number" defaultValue={editingDebt.monthlyPayment} placeholder="0" required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Дата взноса</label>
                  <input name="dueDate" type="date" defaultValue={editingDebt.dueDate} required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
                </div>
              </div>
              <div className="flex gap-3 pt-6">
                <button type="button" onClick={() => setEditingDebt(null)} className="flex-1 py-4 bg-[#1C2128] text-gray-400 rounded-2xl text-xs font-bold">Отмена</button>
                <button type="submit" className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl text-xs font-bold">
                  {editingDebt.id ? 'Сохранить' : 'Создать'}
                </button>
              </div>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

