// Helper to merge widgets
const mergeWidgets = (currentWidgets: any[] = []) => {
    const defaultWidgets = DEFAULT_SETTINGS.widgets || [];
    const currentIds = new Set(currentWidgets.map(w => w.id));
    const missing = defaultWidgets.filter(w => !currentIds.has(w.id));
    if (missing.length > 0) {
        return [...currentWidgets, ...missing];
    }
    return currentWidgets;
};

export const DataProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { familyId, user, loading: authLoading, isOfflineMode } = useAuth();

  // --- Data State ---
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [shoppingItems, setShoppingItems] = useState<ShoppingItem[]>([]);
  const [pantry, setPantryState] = useState<PantryItem[]>([]);
  const [events, setEvents] = useState<FamilyEvent[]>([]);
  const [goals, setGoals] = useState<SavingsGoal[]>([]);
  const [members, setMembers] = useState<FamilyMember[]>([]); 
  const [categories, setCategories] = useState<Category[]>(INITIAL_CATEGORIES);
  const [localRules, setLocalRules] = useState<LearnedRule[]>([]);
  const [globalRules, setGlobalRules] = useState<LearnedRule[]>([]);
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [dismissedNotificationIds, setDismissedNotificationIds] = useState<string[]>([]);
  const [reminders, setReminders] = useState<Reminder[]>([]);
  const [aiKnowledge, setAiKnowledge] = useState<AIKnowledgeItem[]>([]);

  const learnedRules = useMemo(() => {
      const ruleMap = new Map<string, LearnedRule>();

      // 1. Apply Default Rules (Lowest Priority)
      DEFAULT_RULES.forEach(r => ruleMap.set(r.keyword.toLowerCase(), r));

      // 2. Apply Global Database Rules (Medium Priority)
      globalRules.forEach(r => ruleMap.set(r.keyword.toLowerCase(), r));

      // 3. Apply Local Family Rules (Highest Priority - Overrides others)
      localRules.forEach(r => ruleMap.set(r.keyword.toLowerCase(), r));

      return Array.from(ruleMap.values());
  }, [localRules, globalRules]);

  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);

  const [debts, setDebts] = useState<Debt[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [loyaltyCards, setLoyaltyCards] = useState<LoyaltyCard[]>([]);
  const [wishlist, setWishlist] = useState<WishlistItem[]>([]);

  // Removed isolated savingsRate state
  const [budgetMode, setBudgetMode] = useState<'personal' | 'family'>('personal');

  const isInitialLoad = useRef(true);

  // Wrapper for savings rate to maintain API compatibility but store in settings
  const updateSavingsRate = async (rate: number) => {
      const newSettings = { ...settings, savingsRate: rate };
      setSettings(newSettings);
      if (familyId && user) await saveAppSettings(familyId, user.uid, newSettings);
  };

  // Unified update function exposed to consumers
  const updateSettings = async (newSettings: AppSettings) => {
      setSettings(newSettings);
      if (familyId && user) {
          await saveAppSettings(familyId, user.uid, newSettings);
      }
  };

  // --- Subscriptions ---
  useEffect(() => {
    const unsubGlobal = subscribeToGlobalRules((rules) => {
        setGlobalRules(rules);
    });

    if (!familyId) {
        const loadLocal = (key: string, setter: (val: any) => void, fallback?: any) => {
            const stored = localStorage.getItem(`local_${key}`);
            if (stored) {
                try {
                    const parsed = JSON.parse(stored);
                    if (isOfflineMode && Array.isArray(parsed) && parsed.length === 0 && fallback && Array.isArray(fallback) && fallback.length > 0) {
                        setter(fallback);
                        return;
                    }
                    setter(parsed);
                } catch (e) {
                    console.error(`Failed to parse local_${key}`, e);
                    if (fallback) setter(fallback);
                }
            } else if (fallback) {
                setter(fallback);
            }
        };

        const demoTransactions = isOfflineMode ? DEMO_TRANSACTIONS : [];
        const demoShopping = isOfflineMode ? DEMO_SHOPPING_ITEMS : [];
        const demoEvents = isOfflineMode ? DEMO_EVENTS : [];
        const demoGoals = isOfflineMode ? DEMO_GOALS : [];
        const demoDebts = isOfflineMode ? DEMO_DEBTS : [];
        const demoProjects = isOfflineMode ? DEMO_PROJECTS : [];
        const demoMembers = isOfflineMode ? FAMILY_MEMBERS : [];
        const demoCards = isOfflineMode ? DEMO_LOYALTY_CARDS : [];

        loadLocal('transactions', setTransactions, demoTransactions);
        loadLocal('shopping', setShoppingItems, demoShopping);
        loadLocal('events', setEvents, demoEvents);
        loadLocal('goals', setGoals, demoGoals);
        loadLocal('debts', setDebts, demoDebts);
        loadLocal('projects', setProjects, demoProjects);
        loadLocal('pantry', setPantryState, []);
        loadLocal('loyalty', setLoyaltyCards, demoCards);
        loadLocal('wishlist', setWishlist, []);
        loadLocal('reminders', setReminders, []);
        loadLocal('knowledge', setAiKnowledge, []);
        // RESTORED: Loading local rules for offline mode
        loadLocal('rules', setLocalRules, []);

        // Load settings and ensure defaults are applied and widgets merged
        loadLocal('settings', (s: AppSettings) => {
            const mergedSettings = {
                ...s, 
                savingsRate: s.savingsRate ?? 10,
                // Only merge demo expenses if offline and array is empty
                mandatoryExpenses: (isOfflineMode && (!s.mandatoryExpenses || s.mandatoryExpenses.length === 0)) ? DEMO_MANDATORY_EXPENSES : s.mandatoryExpenses || [],
                widgets: mergeWidgets(s.widgets)
            };
            setSettings(prev => ({...prev, ...mergedSettings}));
        }, DEFAULT_SETTINGS);
        loadLocal('dismissed_notifs', setDismissedNotificationIds, []);

        const storedMembers = localStorage.getItem('local_members');
        if (storedMembers) {
            const parsedMembers = JSON.parse(storedMembers);
            if (isOfflineMode && parsedMembers.length === 0 && demoMembers.length > 0) {
                setMembers(demoMembers);
            } else {
                setMembers(parsedMembers);
            }
        } else {
            setMembers(demoMembers);
        }

        isInitialLoad.current = false;
        return unsubGlobal;
    }

    const unsubs = [
      unsubGlobal,
      subscribeToCollection(familyId, 'transactions', (data) => setTransactions(data as Transaction[])),
      subscribeToCollection(familyId, 'shopping', (data) => setShoppingItems(data as ShoppingItem[])),
      subscribeToCollection(familyId, 'pantry', (data) => setPantryState(data as PantryItem[])),
      subscribeToCollection(familyId, 'events', (data) => setEvents(data as FamilyEvent[])),
      subscribeToCollection(familyId, 'goals', (data) => setGoals(data as SavingsGoal[])),
      subscribeToCollection(familyId, 'members', (data) => { 
          if (data.length > 0) setMembers(data as FamilyMember[]);
      }),
      subscribeToCollection(familyId, 'categories', (data) => { 
          if (data.length > 0) setCategories(data as Category[]);
      }),
      subscribeToCollection(familyId, 'rules', (data) => setLocalRules(data as LearnedRule[])),
      subscribeToCollection(familyId, 'knowledge', (data) => setAiKnowledge(data as AIKnowledgeItem[])),
      subscribeToCollection(familyId, 'debts', (data) => setDebts(data as Debt[])),
      subscribeToCollection(familyId, 'projects', (data) => setProjects(data as Project[])),
      subscribeToCollection(familyId, 'loyalty', (data) => setLoyaltyCards(data as LoyaltyCard[])),
      subscribeToCollection(familyId, 'wishlist', (data) => setWishlist(data as WishlistItem[])),
      // NEW: Subscribe to merged settings (Shared + User)
      subscribeToAppSettings(familyId, user?.uid || 'unknown', (data) => {
          if (data) {
              const mergedWidgets = mergeWidgets(data.widgets);
              setSettings(prev => ({ ...prev, ...data, widgets: mergedWidgets }));
              if (data.defaultBudgetMode) setBudgetMode(data.defaultBudgetMode);
          }
      })
    ];

    // Always load dismissed notifications from local storage (device specific preference)
    const storedDismissed = localStorage.getItem('local_dismissed_notifs');
    if (storedDismissed) {
        try { setDismissedNotificationIds(JSON.parse(storedDismissed)); } catch {}
    }

    isInitialLoad.current = false;
    return () => unsubs.forEach(u => u());
  }, [familyId, isOfflineMode, user?.uid]);

  // --- Local Storage Sync ---
  useEffect(() => {
      // Sync dismissed notifications to local storage immediately
      localStorage.setItem('local_dismissed_notifs', JSON.stringify(dismissedNotificationIds));

      if (!authLoading && !isInitialLoad.current && !familyId) {
          localStorage.setItem('local_transactions', JSON.stringify(transactions));
          localStorage.setItem('local_shopping', JSON.stringify(shoppingItems));
          localStorage.setItem('local_events', JSON.stringify(events));
          localStorage.setItem('local_pantry', JSON.stringify(pantry));
          localStorage.setItem('local_goals', JSON.stringify(goals));
          localStorage.setItem('local_debts', JSON.stringify(debts));
          localStorage.setItem('local_projects', JSON.stringify(projects));
          localStorage.setItem('local_loyalty', JSON.stringify(loyaltyCards));
          localStorage.setItem('local_wishlist', JSON.stringify(wishlist));
          localStorage.setItem('local_settings', JSON.stringify(settings));
          localStorage.setItem('local_members', JSON.stringify(members));
          localStorage.setItem('local_knowledge', JSON.stringify(aiKnowledge));
          localStorage.setItem('local_reminders', JSON.stringify(reminders));
          // RESTORED: Saving rules to local storage
          localStorage.setItem('local_rules', JSON.stringify(localRules));
      } else {
          localStorage.setItem('local_reminders', JSON.stringify(reminders));
      }
  }, [
      authLoading, familyId, transactions, shoppingItems, events, pantry, 
      goals, debts, projects, loyaltyCards, wishlist, settings, members, reminders, 
      aiKnowledge, dismissedNotificationIds, localRules
  ]);

  const dismissNotification = (id: string) => {
      setNotifications(prev => prev.filter(n => n.id !== id));
      setDismissedNotificationIds(prev => [...prev, id]);
  };

  // --- Reminder Logic ---
  useEffect(() => {
      const checkReminders = () => {
          const now = Date.now();
          let hasChanges = false;

          setReminders(prev => {
              const due = prev.filter(r => r.targetTime <= now);
              const upcoming = prev.filter(r => r.targetTime > now);

              if (due.length > 0) {
                  hasChanges = true;
                  const newNotifs: AppNotification[] = due.map(r => ({
                      id: `reminder_${r.id}`,
                      title: 'Напоминание ⏰',
                      message: r.text,
                      type: 'info',
                      date: new Date().toISOString(),
                      isRead: false
                  }));

                  // Filter out if they were somehow already dismissed/seen in this session
                  const filteredNew = newNotifs.filter(n => !dismissedNotificationIds.includes(n.id));

                  if (filteredNew.length > 0) {
                      setNotifications(curr => {
                          // Prevent duplicates in current list
                          const unique = filteredNew.filter(n => !curr.some(c => c.id === n.id));
                          return [...unique, ...curr];
                      });

                      if ("Notification" in window && Notification.permission === "granted") {
                          due.forEach(r => new Notification("Напоминание", { body: r.text, icon: '/favicon.ico' }));
                      }
                      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
                  }
              }

              return hasChanges ? upcoming : prev;
          });
      };

      if ("Notification" in window && Notification.permission === "default") {
          Notification.requestPermission();
      }

      const interval = setInterval(checkReminders, 5000); 
      return () => clearInterval(interval);
  }, [dismissedNotificationIds]);

  const addReminder = (text: string, delayMs: number) => {
      const newReminder: Reminder = {
          id: Date.now().toString(),
          text,
          targetTime: Date.now() + delayMs,
          createdAt: Date.now()
      };
      setReminders(prev => [...prev, newReminder]);
  };

  const addAIKnowledge = async (text: string) => {
      const newItem: AIKnowledgeItem = {
          id: Date.now().toString(),
          text,
          addedDate: new Date().toISOString()
      };
      setAiKnowledge(prev => [...prev, newItem]);
      if (familyId) await addItem(familyId, 'knowledge', newItem);
  };

  const deleteAIKnowledge = async (id: string) => {
      setAiKnowledge(prev => prev.filter(k => k.id !== id));
      if (familyId) await deleteItem(familyId, 'knowledge', id);
  };

  useEffect(() => {
      if (categories.length === 0) {
          setCategories(INITIAL_CATEGORIES);
          if (familyId) {
              addItemsBatch(familyId, 'categories', INITIAL_CATEGORIES)
                .catch(err => console.error("Failed to restore categories to DB", err));
          }
      }
  }, [categories, familyId]);

  const handlePantryUpdate = async (dataOrFn: PantryItem[] | ((prev: PantryItem[]) => PantryItem[])) => {
      const newData = typeof dataOrFn === 'function' ? dataOrFn(pantry) : dataOrFn;

      if (familyId) {
          const addedItems = newData.filter(newItem => !pantry.some(oldItem => oldItem.id === newItem.id));
          if (addedItems.length > 0) await addItemsBatch(familyId, 'pantry', addedItems);

          const removedIds = pantry.filter(oldItem => !newData.some(newItem => newItem.id === oldItem.id)).map(i => i.id);
          if (removedIds.length > 0) await deleteItemsBatch(familyId, 'pantry', removedIds);
      }
      setPantryState(newData);
  };

  const filteredTransactions = useMemo(() => {
      if (budgetMode === 'family') return transactions;
      const currentUserId = user?.uid;
      const myMemberId = members.find(m => m.userId === currentUserId)?.id;
      if (!myMemberId) return transactions;
      return transactions.filter(t => t.memberId === myMemberId);
  }, [transactions, budgetMode, members, user]);

  const totalBalance = useMemo(() => {
    let relevantTransactions = filteredTransactions;
    if (settings.initialBalanceDate) {
        const startDate = new Date(settings.initialBalanceDate);
        startDate.setHours(0, 0, 0, 0);
        relevantTransactions = filteredTransactions.filter(t => new Date(t.date).getTime() >= startDate.getTime());
    }
    const income = relevantTransactions.filter(t => t.type === 'income').reduce((acc, t) => acc + t.amount, 0);
    const expense = relevantTransactions.filter(t => t.type === 'expense').reduce((acc, t) => acc + t.amount, 0);
    return (settings.initialBalance || 0) + income - expense;
  }, [filteredTransactions, settings.initialBalance, settings.initialBalanceDate]);

  const currentMonthSpent = useMemo(() => {
    const now = new Date();
    return filteredTransactions
      .filter(t => t.type === 'expense' && new Date(t.date).getMonth() === now.getMonth() && new Date(t.date).getFullYear() === now.getFullYear())
      .reduce((acc, t) => acc + t.amount, 0);
  }, [filteredTransactions]);

  const value = {
    transactions, setTransactions,
    shoppingItems, setShoppingItems,
    pantry, setPantry: handlePantryUpdate,
    events, setEvents,
    goals, setGoals,
    members, setMembers,
    categories, setCategories,
    learnedRules, setLearnedRules: setLocalRules,
    aiKnowledge, addAIKnowledge, deleteAIKnowledge,
    settings, setSettings, updateSettings, // Expose unified updater
    debts, setDebts,
    projects, setProjects,
    loyaltyCards, setLoyaltyCards,
    wishlist, setWishlist,
    notifications, setNotifications,
    addReminder,
    dismissedNotificationIds,
    dismissNotification,

    filteredTransactions,
    totalBalance,
    currentMonthSpent,
    savingsRate: settings.savingsRate ?? 10,
    setSavingsRate: updateSavingsRate,
    budgetMode, setBudgetMode
  };

  return (
    <DataContext.Provider value={value}>
      {children}
    </DataContext.Provider>
  );
};

import React, { useState } from 'react';
import { 
  Plus, X, PieChart, Bell, Calendar, CreditCard, Clock, Trash2, 
  CheckCircle2, Send, Globe, RotateCcw, Target, AlertTriangle, Smile 
} from 'lucide-react';
import { Debt, AppSettings } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { addItem, updateItem, deleteItem } from '../utils/db';

interface Props {
  debts: Debt[];
  setDebts: (d: Debt[]) => void;
  settings: AppSettings;
}

const DebtSnowball: React.FC<Props> = ({ debts, setDebts, settings }) => {
  const [showNotifySettings, setShowNotifySettings] = useState<Debt | null>(null);
  const [showDebtStats, setShowDebtStats] = useState<Debt | null>(null);
  const [editingDebt, setEditingDebt] = useState<Partial<Debt> | null>(null);
  const { familyId } = useAuth();

  const handleUpdateDebt = async (e: React.FormEvent) => {
    e.preventDefault();
    const target = e.target as typeof e.target & {
        title: { value: string };
        totalAmount: { value: string };
        paidAmount: { value: string };
        monthlyPayment: { value: string };
        dueDate: { value: string };
        finalClosingDate: { value: string };
    };

    const totalAmount = Number(target.totalAmount.value);
    const paidAmount = Number(target.paidAmount.value);
    const currentBalance = totalAmount - paidAmount;

    const updatedDebt: Partial<Debt> = {
      ...editingDebt,
      name: target.title.value,
      totalAmount: totalAmount,
      currentBalance: currentBalance,
      monthlyPayment: Number(target.monthlyPayment.value),
      dueDate: target.dueDate.value,
      finalClosingDate: target.finalClosingDate.value,
      channels: editingDebt?.channels || ['site'],
      notifyBefore: editingDebt?.notifyBefore || 3,
      notifyIfOverdue: editingDebt?.notifyIfOverdue ?? true,
      color: '#FF3B30' // Default color required by type, though not used in new UI
    };

    if (editingDebt?.id) {
      const newDebt = { ...updatedDebt, id: editingDebt.id } as Debt;
      setDebts(debts.map(d => d.id === editingDebt.id ? newDebt : d));
      if (familyId) await updateItem(familyId, 'debts', editingDebt.id, newDebt);
    } else {
      const newId = Date.now().toString();
      const newDebt = { ...updatedDebt, id: newId, paidThisMonth: false } as Debt;
      setDebts([...debts, newDebt]);
      if (familyId) await addItem(familyId, 'debts', newDebt);
    }
    setEditingDebt(null);
  };

  const togglePaidStatus = async (id: string) => {
    const debt = debts.find(d => d.id === id);
    if (!debt) return;

    const isCurrentlyPaid = debt.paidThisMonth;
    const payment = debt.monthlyPayment || 0;

    // Logic: If marking as paid, reduce balance (increase paid amount). If unmarking, revert.
    // Note: The UI calculates 'paidAmount' dynamically from total - balance usually, 
    // but here we update balance directly.

    let newBalance = debt.currentBalance;
    if (!isCurrentlyPaid) {
        // Pay
        newBalance = Math.max(0, debt.currentBalance - payment);
    } else {
        // Undo Pay
        newBalance = Math.min(debt.totalAmount, debt.currentBalance + payment);
    }

    const updates = { 
        currentBalance: newBalance,
        paidThisMonth: !isCurrentlyPaid 
    };

    setDebts(debts.map(d => d.id === id ? { ...d, ...updates } : d));
    if (familyId) await updateItem(familyId, 'debts', id, updates);
  };

  const handleDelete = async (id: string) => {
      if(confirm('Удалить этот долг?')) {
          setDebts(debts.filter(d => d.id !== id));
          if (familyId) await deleteItem(familyId, 'debts', id);
          setEditingDebt(null);
      }
  };

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return 'Не указана';
    return new Date(dateStr).toLocaleDateString('ru-RU');
  };

  const isOverdue = (dateStr?: string, isPaid?: boolean) => {
    if (!dateStr || isPaid) return false;
    // Set comparison to end of due date day
    const due = new Date(dateStr);
    due.setHours(23, 59, 59, 999);
    return due < new Date();
  };

  // Helper to calculate Paid Amount for UI (Total - Balance)
  const getPaidAmount = (d: Debt) => d.totalAmount - d.currentBalance;

  return (
    <div className="flex w-full h-full bg-[#0F1115] text-[#E2E8F0] font-sans rounded-[2.5rem] overflow-hidden border border-white/5 shadow-2xl">
      <main className="flex-1 flex flex-col h-full overflow-hidden">
        {/* Header adapted for embedded view */}
        <header className="px-6 py-5 flex items-center justify-between bg-[#16191F]/50 backdrop-blur-md border-b border-gray-800 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-indigo-600 rounded-xl flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <CreditCard size={24} className="text-white" />
            </div>
            <div>
              <h1 className="text-lg font-bold text-white tracking-tight">Мои долги</h1>
              <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">Управление выплатами</p>
            </div>
          </div>
          <button 
            onClick={() => setEditingDebt({ id: undefined, name: '', totalAmount: 0, currentBalance: 0, monthlyPayment: 0, dueDate: '', finalClosingDate: '', channels: ['site'], notifyBefore: 3, notifyIfOverdue: true })}
            className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-xl text-xs font-bold transition-all shadow-lg shadow-indigo-600/20"
          >
            <Plus size={16} /> <span className="hidden sm:inline">Добавить</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 no-scrollbar">
          {debts.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-gray-500">
                  <Smile size={48} className="mb-4 opacity-20" />
                  <p className="font-bold text-xs uppercase tracking-widest">Долгов нет! 🎉</p>
              </div>
          ) : (
              <div className="grid grid-cols-1 xl:grid-cols-2 gap-4 md:gap-6">
                {debts.map((debt) => {
                  const overdue = isOverdue(debt.dueDate, debt.paidThisMonth);
                  const paidAmt = getPaidAmount(debt);
                  const progress = Math.min(100, (paidAmt / debt.totalAmount) * 100);

                  return (
                    <div key={debt.id} className={`bg-[#16191F] rounded-[32px] border p-5 relative overflow-hidden group transition-all ${overdue ? 'border-rose-500/50 shadow-[0_0_20px_rgba(244,63,94,0.1)]' : 'border-gray-800 hover:border-indigo-500/40'}`}>
                      {/* Status Bar */}
                      <div className={`absolute top-0 left-0 w-1.5 h-full transition-all ${debt.paidThisMonth ? 'bg-emerald-500' : (overdue ? 'bg-rose-500 animate-pulse' : 'bg-indigo-500')}`}></div>

                      <div className="flex justify-between items-start mb-6 pl-2">
                        <div onClick={() => setEditingDebt(debt)} className="cursor-pointer flex-1 mr-2">
                          <div className="flex items-center gap-2">
                            <h4 className="text-lg font-bold text-white group-hover:text-indigo-400 transition-colors truncate">{debt.name}</h4>
                            {overdue && <AlertTriangle size={16} className="text-rose-500 shrink-0" />}
                          </div>
                          <div className="mt-2">
                            <div className="flex items-center gap-1.5 text-[10px] text-gray-500 font-bold uppercase tracking-wider">
                              <Target size={12} className="text-indigo-400" /> 
                              <span>Финал: {formatDate(debt.finalClosingDate)}</span>
                            </div>
                          </div>
                        </div>
                        <div className="flex gap-2 shrink-0">
                          <button onClick={() => setShowNotifySettings(debt)} className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all ${(debt.notifyBefore || 0) > 0 ? 'bg-indigo-500 text-white' : 'bg-[#1C2128] text-gray-500'}`}>
                            <Bell size={16} />
                          </button>
                          <button 
                            onClick={() => togglePaidStatus(debt.id)} 
                            className={`w-9 h-9 rounded-xl flex items-center justify-center transition-all ${debt.paidThisMonth ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-500/20' : 'bg-[#1C2128] text-gray-500 hover:text-white hover:bg-emerald-500'}`}
                          >
                            {debt.paidThisMonth ? <RotateCcw size={16} /> : <CheckCircle2 size={16} />}
                          </button>
                        </div>
                      </div>

                      <div className="space-y-4 pl-2">
                        <div className={`p-3 rounded-2xl border flex items-center justify-between ${overdue ? 'bg-rose-500/5 border-rose-500/20' : 'bg-[#1C2128] border-gray-800/50'}`}>
                          <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${overdue ? 'bg-rose-500/20 text-rose-500' : 'bg-indigo-500/10 text-indigo-400'}`}>
                              <Calendar size={18} />
                            </div>
                            <div>
                              <p className="text-[9px] font-bold text-gray-500 uppercase">Платёж до</p>
                              <p className={`text-sm font-bold ${overdue ? 'text-rose-400' : 'text-white'}`}>{formatDate(debt.dueDate)}</p>
                            </div>
                          </div>
                          {overdue && <span className="text-[9px] font-black bg-rose-500 text-white px-2 py-0.5 rounded-full animate-bounce">ПРОСРОЧЕНО</span>}
                        </div>

                        <div className={`flex justify-between p-4 rounded-2xl bg-indigo-600/5 border border-indigo-500/20 items-center`}>
                          <div>
                            <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-widest">Взнос</p>
                            <p className="text-xl font-black text-white">{(debt.monthlyPayment || 0).toLocaleString()} ₽</p>
                          </div>
                          <button 
                            onClick={() => setShowDebtStats(debt)}
                            className="flex items-center gap-1.5 px-3 py-2 bg-indigo-600/20 hover:bg-indigo-600/40 text-indigo-400 rounded-xl text-[10px] font-black transition-all uppercase tracking-tighter"
                          >
                            <PieChart size={14} /> Статистика
                          </button>
                        </div>

                        <div className="space-y-2">
                          <div className="flex justify-between text-[11px] font-bold uppercase tracking-widest text-gray-500 px-1">
                            <span>Прогресс</span>
                            <span className="text-indigo-400">{progress.toFixed(1)}%</span>
                          </div>
                          <div className="h-2 w-full bg-gray-800 rounded-full overflow-hidden">
                            <div className={`h-full rounded-full transition-all duration-700 ease-out ${debt.paidThisMonth ? 'bg-emerald-500' : (overdue ? 'bg-rose-500' : 'bg-indigo-500')}`} style={{ width: `${progress}%` }} />
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
          )}
        </div>
      </main>

      {/* DEBT INDIVIDUAL STATS MODAL */}
      {showDebtStats && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/95 backdrop-blur-md" onClick={() => setShowDebtStats(null)}></div>
          <div className="relative w-full max-w-lg bg-[#16191F] border border-gray-800 rounded-[32px] overflow-hidden shadow-2xl">
            <div className="p-8 space-y-8">
              <div className="flex justify-between items-center">
                <div>
                  <h3 className="text-2xl font-black text-white">{showDebtStats.name}</h3>
                  <p className="text-sm text-gray-500 font-bold uppercase mt-1">Детальный расчет</p>
                </div>
                <button onClick={() => setShowDebtStats(null)} className="w-10 h-10 bg-gray-800 rounded-full flex items-center justify-center text-gray-400 hover:text-white transition-colors">
                  <X size={20} />
                </button>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="bg-[#1C2128] p-5 rounded-2xl border border-gray-800">
                  <p className="text-[10px] font-black text-gray-500 uppercase mb-1">Выплачено</p>
                  <p className="text-lg font-black text-emerald-400">{getPaidAmount(showDebtStats).toLocaleString()} ₽</p>
                </div>
                <div className="bg-[#1C2128] p-5 rounded-2xl border border-gray-800">
                  <p className="text-[10px] font-black text-gray-500 uppercase mb-1">Остаток</p>
                  <p className="text-lg font-black text-rose-400">{showDebtStats.currentBalance.toLocaleString()} ₽</p>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-xs font-black text-gray-500 uppercase flex items-center gap-2">
                  <Clock size={14} /> Календарь платежей
                </h4>
                <div className="space-y-2">
                  {[0, 1, 2].map(i => {
                    const date = showDebtStats.dueDate ? new Date(showDebtStats.dueDate) : new Date();
                    date.setMonth(date.getMonth() + i);
                    return (
                      <div key={i} className={`flex items-center justify-between p-4 rounded-xl border ${i === 0 && !showDebtStats.paidThisMonth ? 'bg-indigo-600/10 border-indigo-500/30' : 'bg-gray-800/20 border-gray-800'}`}>
                        <div className="flex items-center gap-3">
                          <span className="text-xs font-bold text-gray-400 capitalize">{date.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' })}</span>
                        </div>
                        <div className="flex items-center gap-4">
                          <p className="text-sm font-bold text-white">{(showDebtStats.monthlyPayment || 0).toLocaleString()} ₽</p>
                          {i === 0 && showDebtStats.paidThisMonth ? (
                            <CheckCircle2 size={16} className="text-emerald-500" />
                          ) : (
                            <div className="w-4 h-4 rounded-full border-2 border-gray-700" />
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>

              <div className="pt-4 border-t border-gray-800">
                 <div className="flex justify-between items-center text-xs font-bold">
                   <span className="text-gray-500">Дата полного закрытия</span>
                   <span className="text-white bg-indigo-600/20 px-3 py-1 rounded-lg border border-indigo-500/20">{formatDate(showDebtStats.finalClosingDate)}</span>
                 </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* NOTIFY MODAL */}
      {showNotifySettings && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/90 backdrop-blur-sm" onClick={() => setShowNotifySettings(null)}></div>
          <div className="relative w-full max-w-sm bg-[#16191F] border border-gray-800 rounded-[32px] p-8">
            <h3 className="text-xl font-bold mb-6 text-white">Уведомления</h3>

            <div className="space-y-6">
              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase block mb-3">Напоминать за (дней)</label>
                <input 
                  type="number" 
                  value={showNotifySettings.notifyBefore ?? 3}
                  onChange={async (e) => {
                    const val = parseInt(e.target.value) || 0;
                    const updates = { notifyBefore: val };
                    setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                    setShowNotifySettings({...showNotifySettings, ...updates});
                    if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                  }}
                  className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3 font-bold focus:border-indigo-500 outline-none"
                />
              </div>

              <div 
                onClick={async () => {
                  const newVal = !showNotifySettings.notifyIfOverdue;
                  const updates = { notifyIfOverdue: newVal };
                  setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                  setShowNotifySettings({...showNotifySettings, ...updates});
                  if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                }}
                className={`flex items-center justify-between p-4 rounded-2xl border cursor-pointer transition-all ${showNotifySettings.notifyIfOverdue ? 'bg-rose-500/10 border-rose-500/40 text-rose-400' : 'bg-[#1C2128] border-gray-800 text-gray-500'}`}
              >
                <div className="flex items-center gap-3">
                  <AlertTriangle size={18} />
                  <span className="text-xs font-bold">О просрочке</span>
                </div>
                <div className={`w-10 h-5 rounded-full relative transition-colors ${showNotifySettings.notifyIfOverdue ? 'bg-rose-500' : 'bg-gray-700'}`}>
                  <div className={`absolute top-1 w-3 h-3 bg-white rounded-full transition-all ${showNotifySettings.notifyIfOverdue ? 'left-6' : 'left-1'}`} />
                </div>
              </div>

              <div>
                <label className="text-[10px] font-black text-gray-500 uppercase block mb-3">Каналы</label>
                <div className="space-y-2">
                  {[
                    { id: 'site', label: 'Push-уведомления', icon: <Globe size={14}/> },
                    { id: 'telegram', label: 'Telegram Бот', icon: <Send size={14}/> }
                  ].map(ch => {
                    const currentChannels = showNotifySettings.channels || [];
                    const isSelected = currentChannels.includes(ch.id);
                    return (
                        <div 
                        key={ch.id}
                        onClick={async () => {
                            const newChannels = isSelected 
                            ? currentChannels.filter(c => c !== ch.id)
                            : [...currentChannels, ch.id];
                            const updates = { channels: newChannels };
                            setDebts(debts.map(d => d.id === showNotifySettings.id ? {...d, ...updates} : d));
                            setShowNotifySettings({...showNotifySettings, ...updates});
                            if(familyId) await updateItem(familyId, 'debts', showNotifySettings.id, updates);
                        }}
                        className={`flex items-center justify-between p-3 rounded-xl border cursor-pointer transition-all ${isSelected ? 'bg-indigo-600/10 border-indigo-600 text-white' : 'bg-[#1C2128] border-gray-800 text-gray-500 hover:border-gray-600'}`}
                        >
                        <div className="flex items-center gap-2 text-xs font-bold">
                            {ch.icon} {ch.label}
                        </div>
                        <div className={`w-4 h-4 rounded-sm border ${isSelected ? 'bg-indigo-500 border-indigo-500' : 'border-gray-600'}`} />
                        </div>
                    );
                  })}
                </div>
              </div>
            </div>
            <button onClick={() => setShowNotifySettings(null)} className="w-full mt-8 py-4 bg-indigo-600 text-white rounded-2xl text-xs font-bold">Закрыть</button>
          </div>
        </div>
      )}

      {/* EDIT/ADD MODAL */}
      {editingDebt && (
        <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-[#0F1115]/90 backdrop-blur-sm" onClick={() => setEditingDebt(null)}></div>
          <form onSubmit={handleUpdateDebt} className="relative w-full max-w-md bg-[#16191F] border border-gray-800 rounded-[32px] p-8 animate-in zoom-in-95 max-h-[95vh] overflow-y-auto no-scrollbar shadow-2xl">
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-bold text-white">{editingDebt.id ? 'Редактировать' : 'Новый долг'}</h3>
              {editingDebt.id && (
                <button type="button" onClick={() => handleDelete(editingDebt.id!)} className="p-2 text-rose-500 hover:bg-rose-500/10 rounded-xl transition-all">
                  <Trash2 size={20} />
                </button>
              )}
            </div>
            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase ml-1">Название</label>
                <input name="title" defaultValue={editingDebt.name} placeholder="Кредит, Ипотека..." required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black text-gray-500 uppercase ml-1 text-indigo-400">Срок полного закрытия (финал)</label>
                <input name="finalClosingDate" type="date" defaultValue={editingDebt.finalClosingDate} required className="w-full bg-[#1C2128] border border-gray-800 text-white rounded-xl px-4 py-3.5 text-sm font-bold outline-none focus:border-indigo-500" />
              </div>

