                      </div>

                      {/* Info Text about floating payment */}
                      <div className="mb-4 bg-indigo-50/50 dark:bg-indigo-900/10 p-3 rounded-xl border border-indigo-100 dark:border-indigo-900/20 flex gap-2 items-start">
                          <div className="p-1 bg-white dark:bg-white/10 rounded-full text-indigo-500 mt-0.5 shrink-0">
                              <TrendingDown size={10} />
                          </div>
                          <p className="text-[10px] text-indigo-700 dark:text-indigo-300 leading-relaxed font-medium">
                              Это обязательный плавающий платеж. Он будет автоматически пересчитываться каждый месяц, чтобы вы успели закрыть долг к <b>{formatDate(editingDebt.finalClosingDate)}</b>.
                          </p>
                      </div>

                      {/* Area Chart Visualization */}
                      <div className="h-32 w-full -ml-2">
                          <ResponsiveContainer width="100%" height="100%">
                              <AreaChart data={scheduleData}>
                                  <defs>
                                      <linearGradient id="colorBal" x1="0" y1="0" x2="0" y2="1">
                                          <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                                          <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                      </linearGradient>
                                  </defs>
                                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#E5E7EB" opacity={0.5} />
                                  <XAxis 
                                      dataKey="month" 
                                      axisLine={false} 
                                      tickLine={false} 
                                      tick={{ fontSize: 9, fill: '#9CA3AF' }} 
                                      interval="preserveStartEnd"
                                  />
                                  <YAxis hide />
                                  <Tooltip 
                                      contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }}
                                      labelStyle={{ fontSize: '10px', fontWeight: 'bold', color: '#9CA3AF', textTransform: 'uppercase' }}
                                      itemStyle={{ fontSize: '12px', fontWeight: 'bold', color: '#1C1C1E' }}
                                      formatter={(value: number) => [`${value.toLocaleString()} ₽`, 'Остаток']}
                                  />
                                  <Area 
                                      type="monotone" 
                                      dataKey="balance" 
                                      stroke="#6366f1" 
                                      strokeWidth={2}
                                      fillOpacity={1} 
                                      fill="url(#colorBal)" 
                                  />
                              </AreaChart>
                          </ResponsiveContainer>
                      </div>
                  </div>
              )}

              <div className="flex gap-3 pt-6">
                <button type="button" onClick={() => setEditingDebt(null)} className="flex-1 py-4 bg-gray-100 dark:bg-[#2C2C2E] text-gray-500 hover:text-gray-700 dark:hover:text-gray-300 rounded-2xl text-xs font-bold transition-colors">Отмена</button>
                <button type="submit" className="flex-[2] py-4 bg-indigo-600 text-white rounded-2xl text-xs font-bold shadow-lg shadow-indigo-500/30 active:scale-95 transition-all">
                  {editingDebt.id ? 'Сохранить' : 'Создать'}
                </button>
              </div>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default DebtSnowball;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  TrendingUp, Calendar, AlertTriangle, ShieldCheck, 
  DollarSign, ArrowRight, Wallet, CheckCircle2, XCircle,
  HelpCircle, Settings2, RefreshCw
} from 'lucide-react';
import { Transaction, Debt, AppSettings } from '../types';
import { motion, AnimatePresence } from 'framer-motion';

interface Props {
  transactions: Transaction[];
  debts: Debt[];
  settings: AppSettings;
}

type DebtType = 'fixed' | 'flexible';

interface SmartDebt extends Debt {
  type: DebtType;
  priorityScore: number;
}

interface IncomePattern {
  amount: number;
  dayOfMonth: number;
  confidence: 'low' | 'high';
  isManual: boolean;
}

interface PaymentEvent {
  date: Date;
  debtId: string;
  debtName: string;
  amountToPay: number;
  sourceIncomeDate: Date;
  status: 'covered' | 'partial' | 'missed';
  coveredAmount: number;
  message?: string;
}

const SmartDebtPlanner: React.FC<Props> = ({ transactions, debts, settings }) => {
  // Settings for the simulation
  const [safetyBufferPercent, setSafetyBufferPercent] = useState(10); // 10% buffer
  const [manualSalary, setManualSalary] = useState<{amount: string, day: string}>({ amount: '', day: '' });
  const [useManual, setUseManual] = useState(false);

  // 1. Analyze Income History
  const incomePattern = useMemo((): IncomePattern | null => {
    if (useManual && manualSalary.amount && manualSalary.day) {
        return {
            amount: parseFloat(manualSalary.amount),
            dayOfMonth: parseInt(manualSalary.day),
            confidence: 'high',
            isManual: true
        };
    }

    const salaryTxs = transactions.filter(t => 
        t.type === 'income' && 
        (t.category === 'salary' || t.note.toLowerCase().includes('зарплата') || t.note.toLowerCase().includes('salary'))
    );

    if (salaryTxs.length < 2) return null;

    // Simple analysis: Average amount and average day
    // In a real app, this would use standard deviation to filter outliers
    const last6Months = salaryTxs.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 6);

    const totalAmount = last6Months.reduce((sum, t) => sum + t.amount, 0);
    const avgAmount = totalAmount / last6Months.length;

    // Detect day cluster
    const days = last6Months.map(t => new Date(t.date).getDate());
    const avgDay = Math.round(days.reduce((a, b) => a + b, 0) / days.length);

    return {
        amount: Math.floor(avgAmount),
        dayOfMonth: avgDay,
        confidence: last6Months.length > 3 ? 'high' : 'low',
        isManual: false
    };
  }, [transactions, useManual, manualSalary]);

  // 2. Classify & Prioritize Debts
  const processedDebts = useMemo(() => {
    return debts.map(d => {
        // Classification
        const isFixed = (d.monthlyPayment || 0) > 0 && !!d.dueDate;
        const type: DebtType = isFixed ? 'fixed' : 'flexible';

        // Prioritization Score (Higher is more urgent)
        let score = 0;
        const now = new Date();

        // Urgency by deadline
        if (d.dueDate) {
            const dueDay = new Date(d.dueDate).getDate();
            const daysUntil = dueDay - now.getDate();
            score += (31 - daysUntil) * 10; // Closer due date = higher score
        }

        // Final deadline urgency
        if (d.finalClosingDate) {
            const final = new Date(d.finalClosingDate).getTime();
            const diff = final - now.getTime();
            const monthsLeft = diff / (1000 * 60 * 60 * 24 * 30);
            if (monthsLeft < 6) score += (6 - monthsLeft) * 5;
        }

        // Amount weight
        if ((d.monthlyPayment || 0) > 10000) score += 5;

        return { ...d, type, priorityScore: score } as SmartDebt;
    }).sort((a, b) => b.priorityScore - a.priorityScore);
  }, [debts]);

  // 3. Simulation Engine
  const simulation = useMemo(() => {
      if (!incomePattern) return null;

      const schedule: PaymentEvent[] = [];
      const warnings: string[] = [];
      let totalRequired = 0;
      let totalCovered = 0;
      let criticalFailureDate: Date | null = null;

      const now = new Date();
      const horizonMonths = 6;

      // Simulate month by month
      for (let i = 0; i < horizonMonths; i++) {
          const simYear = now.getFullYear();
          const simMonth = now.getMonth() + i;

          // 1. Calculate Income Date
          const incomeDate = new Date(simYear, simMonth, incomePattern.dayOfMonth);
          if (incomeDate < now) incomeDate.setMonth(incomeDate.getMonth() + 1); // If day passed this month

          // 2. Calculate Available Cash (Safety Rule)
          const buffer = incomePattern.amount * (safetyBufferPercent / 100);
          let availableCash = incomePattern.amount - buffer;

          // 3. Find debts due in this "Income Cycle" (From this income date until next income date)
          // Simplified: Look at debts due in this calendar month relative to income

          processedDebts.forEach(debt => {
              // Determine Due Date for this month
              let paymentDate: Date;

              if (debt.type === 'fixed' && debt.dueDate) {
                  // Fixed: Use explicit day from string (YYYY-MM-DD) -> extract Day
                  const dueDay = new Date(debt.dueDate).getDate();
                  paymentDate = new Date(incomeDate.getFullYear(), incomeDate.getMonth(), dueDay);

                  // Safety Rule: Don't plan payment before salary
                  // If due day < income day, we must pay it from PREVIOUS month's salary (or reserves).
                  // For this simulation, we assume we align payment right after salary if due date is close.
                  if (paymentDate < incomeDate) {
                      // It's technically due before salary. Warning!
                      // In simulation, we try to pay it immediately when money comes (late) or prepay.
                      // Let's assume we pay it on Income Date.
                      paymentDate = new Date(incomeDate); 
                  }
              } else {
                  // Flexible: Pay 3 days after income
                  paymentDate = new Date(incomeDate);
                  paymentDate.setDate(paymentDate.getDate() + 3);
              }

              // Determine Amount to Pay
              let amountNeeded = 0;
              if (debt.type === 'fixed') {
                  amountNeeded = debt.monthlyPayment || 0;
              } else {
                  // Flexible Logic: Max(10% of balance, Balance / Months left)
                  const bal = debt.currentBalance;
                  const tenPercent = bal * 0.1;

                  let monthsLeft = 12; // Default fallback
                  if (debt.finalClosingDate) {
                      const final = new Date(debt.finalClosingDate);
                      monthsLeft = Math.max(1, (final.getFullYear() - paymentDate.getFullYear()) * 12 + (final.getMonth() - paymentDate.getMonth()));
                  }
                  const amortized = bal / monthsLeft;

                  amountNeeded = Math.max(tenPercent, amortized);
                  // Don't pay more than balance
                  amountNeeded = Math.min(amountNeeded, bal);
              }

              // 4. Try to Pay
              let status: PaymentEvent['status'] = 'missed';
              let covered = 0;

              if (availableCash >= amountNeeded) {
                  status = 'covered';
                  covered = amountNeeded;
                  availableCash -= amountNeeded;
              } else if (availableCash > 0) {
                  status = 'partial';
                  covered = availableCash;
                  availableCash = 0;
                  if (!criticalFailureDate) criticalFailureDate = paymentDate;
                  warnings.push(`Нехватка ${Math.round(amountNeeded - covered)} ₽ для "${debt.name}" в ${paymentDate.toLocaleString('ru', {month: 'long'})}`);
              } else {
                  status = 'missed';
                  covered = 0;
                  if (!criticalFailureDate) criticalFailureDate = paymentDate;
              }

              if (amountNeeded > 0) {
                  schedule.push({
                      date: paymentDate,
                      debtId: debt.id,
                      debtName: debt.name,
                      amountToPay: Math.round(amountNeeded),
                      sourceIncomeDate: incomeDate,
                      status,
                      coveredAmount: Math.round(covered)
                  });
                  totalRequired += amountNeeded;
                  totalCovered += covered;
              }
          });
      }

      return { schedule, totalRequired, totalCovered, warnings, criticalFailureDate };

  }, [incomePattern, processedDebts, safetyBufferPercent]);

  return (
    <div className="space-y-6 pb-24">
        {/* Header Block */}
        <div className="bg-white dark:bg-[#1C1C1E] p-6 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5">
            <div className="flex items-center gap-3 mb-4">
                <div className="w-12 h-12 bg-indigo-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/30">
                    <ShieldCheck size={24} />
                </div>
                <div>
                    <h2 className="text-xl font-black text-[#1C1C1E] dark:text-white leading-none">Smart Debt</h2>
                    <p className="text-xs font-medium text-gray-400 mt-1">Анализ безопасности долгов</p>
                </div>
            </div>

            {/* Income Analysis State */}
            {!incomePattern ? (
                <div className="bg-orange-50 dark:bg-orange-900/10 p-4 rounded-2xl border border-orange-100 dark:border-orange-900/20">
                    <div className="flex items-start gap-3">
                        <AlertTriangle className="text-orange-500 shrink-0 mt-0.5" size={20} />
                        <div>
                            <h4 className="font-bold text-sm text-[#1C1C1E] dark:text-white">Нет данных о доходе</h4>
                            <p className="text-xs text-gray-500 mt-1">Система не нашла регулярных поступлений "Зарплата" за последние 6 месяцев.</p>

                            <button 
                                onClick={() => setUseManual(true)}
                                className="mt-3 bg-white dark:bg-[#2C2C2E] px-4 py-2 rounded-xl text-xs font-bold shadow-sm border border-gray-100 dark:border-white/5"
                            >
                                Указать вручную
                            </button>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="bg-indigo-50/50 dark:bg-indigo-900/10 p-4 rounded-2xl border border-indigo-100 dark:border-indigo-900/20 flex justify-between items-center">
                    <div>
                        <div className="text-[10px] font-black uppercase text-indigo-400 tracking-wider">Ваш паттерн дохода</div>
                        <div className="text-lg font-black text-[#1C1C1E] dark:text-white mt-0.5">
                            ~{incomePattern.amount.toLocaleString()} ₽ <span className="text-sm text-gray-400 font-medium">/ {incomePattern.dayOfMonth}-го</span>
                        </div>
                    </div>
                    <button onClick={() => setUseManual(true)} className="p-2 bg-white dark:bg-[#2C2C2E] rounded-xl text-gray-400 hover:text-indigo-500 transition-colors">
                        <Settings2 size={18} />
                    </button>
                </div>
            )}

            {/* Manual Override Form */}
            <AnimatePresence>
                {useManual && (
                    <motion.div 
                        initial={{ height: 0, opacity: 0 }} 
                        animate={{ height: 'auto', opacity: 1 }} 
                        exit={{ height: 0, opacity: 0 }}
                        className="overflow-hidden"
                    >
                        <div className="mt-4 pt-4 border-t border-gray-100 dark:border-white/5 grid grid-cols-2 gap-3">
                            <div>
                                <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Сумма</label>
                                <input 
                                    type="number" 
                                    value={manualSalary.amount}
                                    onChange={e => setManualSalary(prev => ({...prev, amount: e.target.value}))}
                                    placeholder="0"
                                    className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-3 rounded-xl text-sm font-bold outline-none"
                                />
                            </div>
                            <div>
                                <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Число</label>
                                <input 
                                    type="number" 
                                    min="1" max="31"
                                    value={manualSalary.day}
                                    onChange={e => setManualSalary(prev => ({...prev, day: e.target.value}))}
                                    placeholder="10"
                                    className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-3 rounded-xl text-sm font-bold outline-none"
                                />
                            </div>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>
        </div>

        {simulation && (
            <>
                {/* Summary Stats */}
                <div className="grid grid-cols-2 gap-3">
                    <div className="bg-white dark:bg-[#1C1C1E] p-5 rounded-[2rem] border border-white dark:border-white/5 shadow-sm">
                        <div className="flex items-center gap-2 mb-2 text-gray-400">
                            <TrendingUp size={16} />
                            <span className="text-[10px] font-black uppercase tracking-widest">Покрытие</span>
                        </div>
                        <div className={`text-2xl font-black ${simulation.totalCovered < simulation.totalRequired ? 'text-red-500' : 'text-green-500'}`}>
                            {Math.round((simulation.totalCovered / (simulation.totalRequired || 1)) * 100)}%
                        </div>
                        <div className="text-[10px] font-bold text-gray-400 mt-1">
                            на 6 месяцев
                        </div>
                    </div>

                    <div className="bg-white dark:bg-[#1C1C1E] p-5 rounded-[2rem] border border-white dark:border-white/5 shadow-sm">
                        <div className="flex items-center gap-2 mb-2 text-gray-400">
                            <ShieldCheck size={16} />
                            <span className="text-[10px] font-black uppercase tracking-widest">Подушка</span>
                        </div>
                        <div className="text-2xl font-black text-[#1C1C1E] dark:text-white">
                            {safetyBufferPercent}%
                        </div>
                        <input 
                            type="range" 
                            min="0" max="30" step="5"
                            value={safetyBufferPercent}
                            onChange={(e) => setSafetyBufferPercent(Number(e.target.value))}
                            className="w-full h-1.5 bg-gray-100 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-indigo-500 mt-2"
                        />
                    </div>
                </div>

                {/* Critical Warning */}
                {simulation.criticalFailureDate && (
                    <div className="bg-red-500 text-white p-5 rounded-[2rem] shadow-lg shadow-red-500/30 flex items-start gap-4">
                        <div className="p-2 bg-white/20 rounded-xl">
                            <AlertTriangle size={24} />
                        </div>
                        <div>
                            <h4 className="font-bold text-lg leading-tight mb-1">Риск просрочки!</h4>
                            <p className="text-xs font-medium opacity-90 leading-relaxed">
                                Прогноз показывает нехватку средств к {simulation.criticalFailureDate.toLocaleDateString()}.
                                Рекомендуем пополнить резерв или пересмотреть график гибких долгов.
                            </p>
                        </div>
                    </div>
                )}

                {/* Payment Schedule */}
                <div className="space-y-4">
                    <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest ml-2 flex items-center gap-2">
                        <Calendar size={14} /> График платежей
                    </h3>

                    {simulation.schedule.slice(0, 8).map((event, idx) => (
                        <div 
                            key={idx}
                            className={`relative p-4 rounded-3xl border-2 flex items-center gap-4 transition-all ${
                                event.status === 'covered' 
                                    ? 'bg-white dark:bg-[#1C1C1E] border-transparent shadow-sm' 
                                    : event.status === 'partial' 
                                        ? 'bg-yellow-50 dark:bg-yellow-900/10 border-yellow-200 dark:border-yellow-900/30'
                                        : 'bg-red-50 dark:bg-red-900/10 border-red-200 dark:border-red-900/30'
                            }`}
                        >
                            <div className={`w-12 h-12 rounded-2xl flex flex-col items-center justify-center shrink-0 font-bold ${
                                event.status === 'covered' ? 'bg-gray-100 dark:bg-[#2C2C2E] text-gray-500' :
                                event.status === 'partial' ? 'bg-yellow-100 text-yellow-600' :
                                'bg-red-100 text-red-600'
                            }`}>
                                <span className="text-sm">{event.date.getDate()}</span>
                                <span className="text-[9px] uppercase">{event.date.toLocaleString('ru', { month: 'short' })}</span>
                            </div>

                            <div className="flex-1 min-w-0">
                                <div className="flex justify-between items-start mb-1">
                                    <h4 className="font-bold text-sm text-[#1C1C1E] dark:text-white truncate">{event.debtName}</h4>
                                    <div className="text-[10px] font-black bg-gray-100 dark:bg-white/10 px-2 py-0.5 rounded text-gray-500">
                                        {event.sourceIncomeDate.getDate()}-го
                                    </div>
                                </div>
                                <div className="flex justify-between items-end">
                                    <div className="text-xs text-gray-500 dark:text-gray-400 font-medium">
                                        Нужно: {event.amountToPay.toLocaleString()}
                                    </div>
                                    <div className={`text-sm font-black ${
                                        event.status === 'covered' ? 'text-green-500' :
                                        event.status === 'partial' ? 'text-yellow-600' : 'text-red-500'
                                    }`}>
                                        {event.status === 'covered' ? 'Ок' : event.coveredAmount.toLocaleString()}
                                    </div>
                                </div>
                                {event.status !== 'covered' && (
                                    <div className="mt-2 text-[9px] font-bold text-red-500 bg-red-100/50 px-2 py-1 rounded-lg inline-block">
                                        Нехватка: {(event.amountToPay - event.coveredAmount).toLocaleString()} ₽
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>
            </>
        )}
    </div>
  );
};

