                        {/* Type Selector */}
                        <div className="grid grid-cols-2 gap-3 mb-6">
                            <button 
                                onClick={() => setNewDebtType('fixed')}
                                className={`p-4 rounded-2xl border-2 text-left transition-all ${newDebtType === 'fixed' ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20' : 'border-transparent bg-gray-50 dark:bg-[#2C2C2E]'}`}
                            >
                                <div className="mb-2 text-indigo-500"><CalendarClock size={24}/></div>
                                <div className="font-bold text-sm text-[#1C1C1E] dark:text-white">Фиксированный</div>
                                <div className="text-[10px] text-gray-400 mt-1">Регулярный платеж в дату (Кредит, Ипотека)</div>
                            </button>
                            <button 
                                onClick={() => setNewDebtType('flexible')}
                                className={`p-4 rounded-2xl border-2 text-left transition-all ${newDebtType === 'flexible' ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/20' : 'border-transparent bg-gray-50 dark:bg-[#2C2C2E]'}`}
                            >
                                <div className="mb-2 text-purple-500"><CreditCard size={24}/></div>
                                <div className="font-bold text-sm text-[#1C1C1E] dark:text-white">Гибкий</div>
                                <div className="text-[10px] text-gray-400 mt-1">Закрыть к дате (Кредитка, Займ)</div>
                            </button>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Название</label>
                                <input type="text" value={newDebt.name} onChange={e => setNewDebt({...newDebt, name: e.target.value})} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="Напр: Ипотека Сбер" />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Остаток долга</label>
                                    <input type="number" value={newDebt.currentBalance || ''} onChange={e => setNewDebt({...newDebt, currentBalance: Number(e.target.value), totalAmount: newDebt.totalAmount || Number(e.target.value)})} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="0" />
                                </div>
                                <div>
                                    <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Всего (для справки)</label>
                                    <input type="number" value={newDebt.totalAmount || ''} onChange={e => setNewDebt({...newDebt, totalAmount: Number(e.target.value)})} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="0" />
                                </div>
                            </div>

                            {/* Conditional Fields based on Type */}
                            {newDebtType === 'fixed' ? (
                                <div className="bg-indigo-50/50 dark:bg-indigo-900/10 p-4 rounded-2xl border border-indigo-100 dark:border-indigo-900/20 space-y-4">
                                    <div>
                                        <label className="text-[10px] font-black text-indigo-500 uppercase ml-2">Ежемесячный платеж</label>
                                        <input type="number" value={newDebt.monthlyPayment || ''} onChange={e => setNewDebt({...newDebt, monthlyPayment: Number(e.target.value)})} className="w-full bg-white dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="0" />
                                    </div>
                                    <div>
                                        <label className="text-[10px] font-black text-indigo-500 uppercase ml-2">День платежа (1-31)</label>
                                        <input type="number" min="1" max="31" value={newDebt.paymentDay || ''} onChange={e => setNewDebt({...newDebt, paymentDay: Number(e.target.value)})} className="w-full bg-white dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="10" />
                                    </div>
                                </div>
                            ) : (
                                <div className="bg-purple-50/50 dark:bg-purple-900/10 p-4 rounded-2xl border border-purple-100 dark:border-purple-900/20 space-y-4">
                                    <div>
                                        <label className="text-[10px] font-black text-purple-500 uppercase ml-2">Закрыть до</label>
                                        <input type="date" value={newDebt.finalClosingDate || ''} onChange={e => setNewDebt({...newDebt, finalClosingDate: e.target.value})} className="w-full bg-white dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" />
                                    </div>

                                    {flexibleSuggestion && (
                                        <div className="text-xs text-purple-700 dark:text-purple-300 bg-white dark:bg-purple-900/30 p-3 rounded-xl">
                                            💡 Рекомендуемый минимум: <b>{flexibleSuggestion.recommended.toLocaleString()} ₽</b>
                                            <div className="opacity-70 text-[10px] mt-1">
                                                (Чтобы закрыть за {flexibleSuggestion.months} мес.)
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>

                        {/* Preview */}
                        <div className="mt-6 p-4 bg-gray-50 dark:bg-[#2C2C2E] rounded-2xl text-xs text-gray-500 font-medium leading-relaxed">
                            {newDebt.name && (
                                <>
                                    <span className="block font-bold text-[#1C1C1E] dark:text-white mb-1">Предпросмотр:</span>
                                    {newDebtType === 'fixed' ? (
                                        `Следующий платеж ${newDebt.monthlyPayment?.toLocaleString()} ₽ до ${newDebt.paymentDay}-го числа.`
                                    ) : (
                                        `Цель: закрыть ${newDebt.currentBalance?.toLocaleString()} ₽ до ${newDebt.finalClosingDate ? new Date(newDebt.finalClosingDate).toLocaleDateString() : '...'}`
                                    )}
                                </>
                            )}
                        </div>

                        <button 
                            onClick={handleSaveDebt}
                            disabled={!newDebt.name || !newDebt.currentBalance}
                            className="w-full mt-6 bg-[#1C1C1E] dark:bg-white text-white dark:text-black py-4 rounded-2xl font-black uppercase text-xs tracking-widest shadow-lg active:scale-95 transition-transform disabled:opacity-50"
                        >
                            Сохранить долг
                        </button>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    </div>
  );
};

export default SmartDebtPlanner;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  TrendingUp, Calendar, AlertTriangle, ShieldCheck, 
  DollarSign, ArrowRight, Wallet, CheckCircle2, XCircle,
  HelpCircle, Settings2, RefreshCw, Plus, X, Lock, Calculator, CalendarClock, CreditCard, Trash2, Edit2
} from 'lucide-react';
import { Transaction, Debt, AppSettings } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import { addItem, updateItem, deleteItem } from '../utils/db';
import { useAuth } from '../contexts/AuthContext';
import { useData } from '../contexts/DataContext';
import { toast } from 'sonner';

interface Props {
  transactions: Transaction[];
  debts: Debt[];
  settings: AppSettings;
}

// Internal Types for Simulation
interface PaymentPlan {
  date: Date;
  debtId: string;
  debtName: string;
  amount: number;
  isCovered: boolean;
  isPartial: boolean;
  sourceIncomeDate: Date | null;
  warnings: string[];
  isPaid: boolean; // Add state for manual completion in this view
}

interface IncomePattern {
  amount: number;
  dayOfMonth: number;
  confidence: 'low' | 'high';
  isManual: boolean;
}

const SmartDebtPlanner: React.FC<Props> = ({ transactions, debts, settings }) => {
  const { familyId } = useAuth();
  const { setDebts } = useData(); // Access global state setter

  // -- Settings & State --
  const [safetyBufferPercent, setSafetyBufferPercent] = useState(10);
  const [manualSalary, setManualSalary] = useState<{amount: string, day: string}>({ amount: '', day: '' });
  const [useManualIncome, setUseManualIncome] = useState(false);

  // -- Modal State --
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);
  const [newDebtType, setNewDebtType] = useState<'fixed' | 'flexible'>('fixed');
  const [newDebt, setNewDebt] = useState<Partial<Debt>>({
      name: '',
      currentBalance: 0,
      totalAmount: 0,
      strategy: 'fixed',
      paymentDay: 10,
      monthlyPayment: 0,
      finalClosingDate: '',
  });

  // 1. Analyze Income History
  const incomePattern = useMemo((): IncomePattern | null => {
    if (useManualIncome && manualSalary.amount && manualSalary.day) {
        return {
            amount: parseFloat(manualSalary.amount),
            dayOfMonth: parseInt(manualSalary.day),
            confidence: 'high',
            isManual: true
        };
    }

    const salaryTxs = transactions.filter(t => 
        t.type === 'income' && 
        (t.category === 'salary' || t.note.toLowerCase().includes('зарплата') || t.note.toLowerCase().includes('salary'))
    );

    if (salaryTxs.length < 2) return null;

    const last6Months = salaryTxs.sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime()).slice(0, 6);
    const totalAmount = last6Months.reduce((sum, t) => sum + t.amount, 0);
    const avgAmount = totalAmount / last6Months.length;
    const days = last6Months.map(t => new Date(t.date).getDate());
    const avgDay = Math.round(days.reduce((a, b) => a + b, 0) / days.length);

    return {
        amount: Math.floor(avgAmount),
        dayOfMonth: avgDay,
        confidence: last6Months.length > 3 ? 'high' : 'low',
        isManual: false
    };
  }, [transactions, useManualIncome, manualSalary]);

  // 2. Simulation Engine
  const simulation = useMemo(() => {
      if (!incomePattern) return null;

      const activeDebts = debts.filter(d => d.currentBalance > 0);
      const schedule: PaymentPlan[] = [];
      let totalRequired = 0;
      let totalCovered = 0;
      let criticalDate: Date | null = null;

      // Clone debts to track declining balance during simulation
      const simDebts = activeDebts.map(d => ({...d}));

      const now = new Date();
      // Simulate for 6 months
      for (let m = 0; m < 6; m++) {
          const simYear = now.getFullYear();
          const simMonth = now.getMonth() + m;

          // 1. Determine Income Date
          let incomeDate = new Date(simYear, simMonth, incomePattern.dayOfMonth);
          if (m === 0 && incomeDate < now) {
             incomeDate.setMonth(incomeDate.getMonth() + 1);
          }

          // 2. Calculate Available Cash
          let availableCash = incomePattern.amount * (1 - safetyBufferPercent / 100);

          // 3. Process Debts Priority: Fixed -> Flexible
          const monthDebts = simDebts.filter(d => d.currentBalance > 0).sort((a, b) => {
              if (a.strategy === 'fixed' && b.strategy !== 'fixed') return -1;
              if (a.strategy !== 'fixed' && b.strategy === 'fixed') return 1;

              if (a.strategy === 'fixed' && b.strategy === 'fixed') {
                  return (a.paymentDay || 31) - (b.paymentDay || 31);
              }
              // Both flexible
              const dateA = a.finalClosingDate ? new Date(a.finalClosingDate).getTime() : Infinity;
              const dateB = b.finalClosingDate ? new Date(b.finalClosingDate).getTime() : Infinity;
              return dateA - dateB;
          });

          monthDebts.forEach(debt => {
              let amountNeeded = 0;
              let paymentDate: Date;
              const payWarnings: string[] = [];

              if (debt.strategy === 'fixed') {
                  amountNeeded = debt.monthlyPayment || 0;
                  const day = debt.paymentDay || 1;
                  paymentDate = new Date(incomeDate.getFullYear(), incomeDate.getMonth(), day);

                  if (paymentDate < incomeDate && m === 0) {
                      paymentDate = new Date();
                  } else if (paymentDate < incomeDate) {
                      payWarnings.push(`Срок ${day}-го, а з/п ${incomePattern.dayOfMonth}-го`);
                  }
              } else {
                  // Flexible logic
                  const targetDate = debt.finalClosingDate ? new Date(debt.finalClosingDate) : null;
                  let monthsLeft = 1;
                  if (targetDate) {
                      const diffMonths = (targetDate.getFullYear() - incomeDate.getFullYear()) * 12 + (targetDate.getMonth() - incomeDate.getMonth());
                      monthsLeft = Math.max(1, diffMonths);
                  }

                  const min10 = debt.currentBalance * 0.1;
                  const amortized = debt.currentBalance / monthsLeft;
                  amountNeeded = Math.max(min10, amortized);

                  paymentDate = new Date(incomeDate);
                  paymentDate.setDate(paymentDate.getDate() + 1);
              }

              amountNeeded = Math.min(amountNeeded, debt.currentBalance);

              // Pay Logic
              let paid = 0;
              let status: 'covered' | 'partial' | 'missed' = 'missed';

              if (availableCash >= amountNeeded) {
                  paid = amountNeeded;
                  availableCash -= paid;
                  status = 'covered';
              } else if (availableCash > 0) {
                  paid = availableCash;
                  availableCash = 0;
                  status = 'partial';
                  payWarnings.push('Нехватка средств');
                  if (!criticalDate) criticalDate = paymentDate;
              } else {
                  paid = 0;
                  status = 'missed';
                  payWarnings.push('Нет денег');
                  if (!criticalDate) criticalDate = paymentDate;
              }

              debt.currentBalance -= paid;
              totalRequired += amountNeeded;
              totalCovered += paid;

              if (amountNeeded > 0) {
                  schedule.push({
                      date: paymentDate,
                      debtId: debt.id,
                      debtName: debt.name,
                      amount: Math.round(amountNeeded),
                      isCovered: status === 'covered',
                      isPartial: status === 'partial',
                      sourceIncomeDate: incomeDate,
                      warnings: payWarnings,
                      isPaid: false
                  });
              }
          });
      }

      schedule.sort((a, b) => a.date.getTime() - b.date.getTime());

      return { schedule, totalRequired, totalCovered, criticalDate };
  }, [incomePattern, debts, safetyBufferPercent]);

  // -- Handlers --
  const handleSaveDebt = async () => {
      // Final Validation
      if (!newDebt.name || (newDebt.currentBalance || 0) <= 0) return;

      const debtId = newDebt.id || Date.now().toString();

      const debtToSave: Debt = {
          id: debtId,
          name: newDebt.name!,
          currentBalance: Number(newDebt.currentBalance),
          totalAmount: Number(newDebt.totalAmount || newDebt.currentBalance),
          color: '#FF3B30',
          strategy: newDebtType,
          paymentDay: newDebtType === 'fixed' ? Number(newDebt.paymentDay) : undefined,
          monthlyPayment: newDebtType === 'fixed' ? Number(newDebt.monthlyPayment) : undefined,
          finalClosingDate: newDebtType === 'flexible' ? newDebt.finalClosingDate : undefined,
          paidThisMonth: false,
          notifyBefore: 3,
          notifyIfOverdue: true
      };

      // 1. Update Local State (Optimistic)
      if (newDebt.id) {
          setDebts(prev => prev.map(d => d.id === newDebt.id ? debtToSave : d));
          toast.success('Долг обновлен');
      } else {
          setDebts(prev => [...prev, debtToSave]);
          toast.success('Долг добавлен');
      }

      // 2. Persist to DB
      if (familyId) {
          if (newDebt.id) {
              await updateItem(familyId, 'debts', newDebt.id, debtToSave);
          } else {
              await addItem(familyId, 'debts', debtToSave);
          }
      }

      setIsAddModalOpen(false);
      setNewDebt({ name: '', currentBalance: 0, totalAmount: 0, strategy: 'fixed', paymentDay: 10, monthlyPayment: 0, finalClosingDate: '' });
  };

  const handleEditDebt = (debt: Debt) => {
      setNewDebtType(debt.strategy === 'flexible' ? 'flexible' : 'fixed');
      setNewDebt({ ...debt });
      setIsAddModalOpen(true);
  };

  const handleDeleteDebt = async (id: string) => {
      if (confirm('Удалить этот долг? История выплат не сохранится.')) {
          // 1. Local Update
          setDebts(prev => prev.filter(d => d.id !== id));

          // 2. DB Update
          if (familyId) await deleteItem(familyId, 'debts', id);

          toast.success('Долг удален');
          setIsAddModalOpen(false);
      }
  };

  const handleMarkPaid = async (item: PaymentPlan) => {
      if (confirm(`Отметить платеж ${item.amount} ₽ как выполненный? Это уменьшит остаток долга.`)) {
          const debt = debts.find(d => d.id === item.debtId);
          if (!debt) return;

          const newBalance = Math.max(0, debt.currentBalance - item.amount);

          // 1. Local Update
          setDebts(prev => prev.map(d => d.id === debt.id ? { ...d, currentBalance: newBalance } : d));

          // 2. DB Update
          if (familyId) {
              await updateItem(familyId, 'debts', debt.id, { currentBalance: newBalance });
          }
          toast.success(`Остаток обновлен: ${newBalance.toLocaleString()} ₽`);
      }
  };

  const getFlexibleSuggestion = () => {
      if (!newDebt.currentBalance || !newDebt.finalClosingDate) return null;
      const bal = Number(newDebt.currentBalance);
      const target = new Date(newDebt.finalClosingDate);
      const now = new Date();
      const months = Math.max(1, (target.getFullYear() - now.getFullYear()) * 12 + (target.getMonth() - now.getMonth()));

      const min10 = Math.round(bal * 0.1);
      const amortized = Math.round(bal / months);
      const recommended = Math.max(min10, amortized);

      return { recommended, months };
  };

  const flexibleSuggestion = getFlexibleSuggestion();

  return (
    <div className="space-y-6 pb-24">
        {/* Header Block */}
        <div className="bg-white dark:bg-[#1C1C1E] p-6 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5">
            <div className="flex justify-between items-start mb-4">
                <div className="flex items-center gap-3">
                    <div className="w-12 h-12 bg-indigo-500 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-indigo-500/30">
                        <ShieldCheck size={24} />
                    </div>
                    <div>
                        <h2 className="text-xl font-black text-[#1C1C1E] dark:text-white leading-none">Smart Debt</h2>
                        <p className="text-xs font-medium text-gray-400 mt-1">Планирование выплат</p>
                    </div>
                </div>
                <button 
                    onClick={() => {
                        setNewDebt({ name: '', currentBalance: 0, totalAmount: 0, strategy: 'fixed', paymentDay: 10, monthlyPayment: 0, finalClosingDate: '' });
                        setIsAddModalOpen(true);
                    }}
                    className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-xl text-xs font-bold shadow-lg shadow-indigo-500/30 active:scale-95 transition-transform flex items-center gap-2"
                >
                    <Plus size={16} /> Добавить
                </button>
            </div>

            {/* Income Config */}
            {!incomePattern ? (
                <div className="bg-orange-50 dark:bg-orange-900/10 p-4 rounded-2xl border border-orange-100 dark:border-orange-900/20">
                    <div className="flex items-start gap-3">
                        <AlertTriangle className="text-orange-500 shrink-0 mt-0.5" size={20} />
                        <div>
                            <h4 className="font-bold text-sm text-[#1C1C1E] dark:text-white">Нет данных о доходе</h4>
                            <p className="text-xs text-gray-500 mt-1">Для точного прогноза нужна история зарплат или ручной ввод.</p>
                            <button onClick={() => setUseManualIncome(true)} className="mt-2 text-indigo-600 font-bold text-xs underline">Указать вручную</button>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="bg-indigo-50/50 dark:bg-indigo-900/10 p-4 rounded-2xl border border-indigo-100 dark:border-indigo-900/20 flex justify-between items-center">
                    <div>
                        <div className="text-[10px] font-black uppercase text-indigo-400 tracking-wider">Ваш доход (расчетный)</div>
                        <div className="text-lg font-black text-[#1C1C1E] dark:text-white mt-0.5">
                            ~{incomePattern.amount.toLocaleString()} ₽ <span className="text-sm text-gray-400 font-medium">/ {incomePattern.dayOfMonth}-го числа</span>
                        </div>
                    </div>
                    <button onClick={() => setUseManualIncome(true)} className="p-2 bg-white dark:bg-[#2C2C2E] rounded-xl text-gray-400 hover:text-indigo-500 transition-colors">
                        <Settings2 size={18} />
                    </button>
                </div>
            )}

            {/* Manual Salary Input */}
            {useManualIncome && (
                <div className="mt-4 pt-4 border-t border-gray-100 dark:border-white/5 grid grid-cols-2 gap-3 animate-in fade-in">
                    <div>
                        <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Сумма</label>
                        <input type="number" value={manualSalary.amount} onChange={e => setManualSalary(prev => ({...prev, amount: e.target.value}))} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-3 rounded-xl text-sm font-bold outline-none" placeholder="0" />
                    </div>
                    <div>
                        <label className="text-[10px] font-bold text-gray-400 uppercase ml-2">Число</label>
                        <input type="number" min="1" max="31" value={manualSalary.day} onChange={e => setManualSalary(prev => ({...prev, day: e.target.value}))} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-3 rounded-xl text-sm font-bold outline-none" placeholder="10" />
                    </div>
                </div>
            )}
        </div>

        {/* ACTIVE DEBTS LIST */}
        {debts.length > 0 && (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {debts.map(debt => (
                    <div key={debt.id} className="bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] border border-gray-100 dark:border-white/5 shadow-sm relative group">
                        <div className="flex justify-between items-start mb-2">
                            <div>
                                <h4 className="font-bold text-sm text-[#1C1C1E] dark:text-white truncate max-w-[150px]">{debt.name}</h4>
                                <p className="text-[10px] font-medium text-gray-400">
                                    {debt.strategy === 'fixed' ? 'Фиксированный' : 'Гибкий'}
                                </p>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => handleEditDebt(debt)} className="p-2 text-gray-300 hover:text-blue-500 bg-gray-50 dark:bg-[#2C2C2E] rounded-xl transition-colors"><Edit2 size={14}/></button>
                            </div>
                        </div>
                        <div className="flex items-baseline gap-1 mt-2">
                            <span className="text-xl font-black text-[#1C1C1E] dark:text-white">{debt.currentBalance.toLocaleString()}</span>
                            <span className="text-xs font-bold text-gray-400">₽</span>
                        </div>

                        <div className="mt-3 pt-3 border-t border-gray-50 dark:border-white/5 flex justify-between text-[10px] font-bold text-gray-500">
                            {debt.strategy === 'fixed' ? (
                                <span>Платёж: {debt.monthlyPayment} ₽</span>
                            ) : (
                                <span>Финал: {new Date(debt.finalClosingDate || '').toLocaleDateString()}</span>
                            )}
                        </div>
                    </div>
                ))}
            </div>
        )}

        {/* SIMULATION RESULTS */}
        {simulation && simulation.schedule.length > 0 && (
            <div className="space-y-4">
                {/* Summary */}
                <div className="grid grid-cols-2 gap-3">
                    <div className="bg-white dark:bg-[#1C1C1E] p-5 rounded-[2rem] border border-white dark:border-white/5 shadow-sm">
                        <div className="flex items-center gap-2 mb-2 text-gray-400"><TrendingUp size={16} /><span className="text-[10px] font-black uppercase tracking-widest">Покрытие</span></div>
                        <div className={`text-2xl font-black ${simulation.totalCovered < simulation.totalRequired ? 'text-red-500' : 'text-green-500'}`}>
                            {Math.round((simulation.totalCovered / (simulation.totalRequired || 1)) * 100)}%
                        </div>
                    </div>
                    <div className="bg-white dark:bg-[#1C1C1E] p-5 rounded-[2rem] border border-white dark:border-white/5 shadow-sm">
                        <div className="flex items-center gap-2 mb-2 text-gray-400"><ShieldCheck size={16} /><span className="text-[10px] font-black uppercase tracking-widest">Подушка</span></div>
                        <div className="text-2xl font-black text-[#1C1C1E] dark:text-white">{safetyBufferPercent}%</div>
                        <input type="range" min="0" max="30" step="5" value={safetyBufferPercent} onChange={(e) => setSafetyBufferPercent(Number(e.target.value))} className="w-full h-1.5 bg-gray-100 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-indigo-500 mt-2" />
                    </div>
                </div>

                {/* Critical Warning */}
                {simulation.criticalDate && (
                    <div className="bg-red-500 text-white p-5 rounded-[2rem] shadow-lg shadow-red-500/30 flex items-start gap-4">
                        <div className="p-2 bg-white/20 rounded-xl"><AlertTriangle size={24} /></div>
                        <div>
                            <h4 className="font-bold text-lg leading-tight mb-1">Риск просрочки!</h4>
                            <p className="text-xs font-medium opacity-90 leading-relaxed">
                                Нехватка средств к {simulation.criticalDate.toLocaleDateString()}. Прогноз показывает дефицит.
                            </p>
                        </div>
                    </div>
                )}

                {/* Schedule List */}
                <div className="space-y-3">
                    <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest ml-2 flex items-center gap-2">
                        <Calendar size={14} /> График платежей
                    </h3>
                    {simulation.schedule.slice(0, 10).map((event, idx) => (
                        <div key={idx} className={`relative p-4 rounded-3xl border-2 flex items-center gap-4 transition-all ${event.isCovered ? 'bg-white dark:bg-[#1C1C1E] border-transparent shadow-sm' : event.isPartial ? 'bg-yellow-50 dark:bg-yellow-900/10 border-yellow-200 dark:border-yellow-900/30' : 'bg-red-50 dark:bg-red-900/10 border-red-200 dark:border-red-900/30'}`}>
                            <div className={`w-12 h-12 rounded-2xl flex flex-col items-center justify-center shrink-0 font-bold ${event.isCovered ? 'bg-gray-100 dark:bg-[#2C2C2E] text-gray-500' : event.isPartial ? 'bg-yellow-100 text-yellow-600' : 'bg-red-100 text-red-600'}`}>
                                <span className="text-sm">{event.date.getDate()}</span>
                                <span className="text-[9px] uppercase">{event.date.toLocaleString('ru', { month: 'short' })}</span>
                            </div>
                            <div className="flex-1 min-w-0">
                                <div className="flex justify-between items-start mb-1">
                                    <h4 className="font-bold text-sm text-[#1C1C1E] dark:text-white truncate">{event.debtName}</h4>
                                    <div className="text-[10px] font-black bg-gray-100 dark:bg-white/10 px-2 py-0.5 rounded text-gray-500">из з/п {event.sourceIncomeDate?.getDate()}</div>
                                </div>
                                <div className="flex justify-between items-end">
                                    <div className="text-xs text-gray-500 dark:text-gray-400 font-medium">Нужно: {event.amount.toLocaleString()}</div>
                                    <div className={`text-sm font-black ${event.isCovered ? 'text-green-500' : event.isPartial ? 'text-yellow-600' : 'text-red-500'}`}>
                                        {event.isCovered ? 'Ок' : 'Не хватает'}
                                    </div>
                                </div>
                                {event.warnings.length > 0 && (
                                    <div className="mt-2 flex flex-wrap gap-1">
                                        {event.warnings.map((w, i) => (
                                            <span key={i} className="text-[9px] font-bold text-red-500 bg-red-100/50 px-2 py-1 rounded-lg">{w}</span>
                                        ))}
                                    </div>
                                )}
                            </div>
                            {/* Pay Button (Visible if date is near or past) */}
                            { (new Date().getTime() >= event.date.getTime() - 86400000 * 3) && (
                                <button 
                                    onClick={() => handleMarkPaid(event)}
                                    className="absolute -top-2 -right-2 bg-green-500 text-white p-2 rounded-full shadow-lg hover:bg-green-600 transition-colors"
                                    title="Отметить оплаченным"
                                >
                                    <CheckCircle2 size={16} />
                                </button>
                            )}
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* ADD DEBT MODAL */}
        <AnimatePresence>
            {isAddModalOpen && (
                <div className="fixed inset-0 z-[2200] flex items-center justify-center p-4">
                    <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setIsAddModalOpen(false)} />
                    <motion.div initial={{scale:0.95, opacity:0}} animate={{scale:1, opacity:1}} exit={{scale:0.95, opacity:0}} className="relative w-full max-w-lg bg-white dark:bg-[#1C1C1E] border border-white/10 rounded-[32px] p-6 shadow-2xl max-h-[90vh] overflow-y-auto no-scrollbar">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold text-[#1C1C1E] dark:text-white">
                                {newDebt.id ? 'Редактировать долг' : 'Добавить долг'}
                            </h3>
                            {newDebt.id && (
                                <button onClick={() => handleDeleteDebt(newDebt.id!)} className="p-2 text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-full transition-colors">
                                    <Trash2 size={20}/>
                                </button>
                            )}
                            <button onClick={() => setIsAddModalOpen(false)} className="p-2 bg-gray-100 dark:bg-[#2C2C2E] rounded-full"><X size={20}/></button>
                        </div>

                        {/* Type Selector */}
                        <div className="grid grid-cols-2 gap-3 mb-6">
                            <button 
                                onClick={() => setNewDebtType('fixed')}
                                className={`p-4 rounded-2xl border-2 text-left transition-all ${newDebtType === 'fixed' ? 'border-indigo-500 bg-indigo-50 dark:bg-indigo-900/20' : 'border-transparent bg-gray-50 dark:bg-[#2C2C2E]'}`}
                            >
                                <div className="mb-2 text-indigo-500"><CalendarClock size={24}/></div>
                                <div className="font-bold text-sm text-[#1C1C1E] dark:text-white">Фиксированный</div>
                                <div className="text-[10px] text-gray-400 mt-1">Регулярный платеж в дату (Кредит, Ипотека)</div>
                            </button>
                            <button 
                                onClick={() => setNewDebtType('flexible')}
                                className={`p-4 rounded-2xl border-2 text-left transition-all ${newDebtType === 'flexible' ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/20' : 'border-transparent bg-gray-50 dark:bg-[#2C2C2E]'}`}
                            >
                                <div className="mb-2 text-purple-500"><CreditCard size={24}/></div>
                                <div className="font-bold text-sm text-[#1C1C1E] dark:text-white">Гибкий</div>
                                <div className="text-[10px] text-gray-400 mt-1">Закрыть к дате (Кредитка, Займ)</div>
                            </button>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Название</label>
                                <input type="text" value={newDebt.name} onChange={e => setNewDebt({...newDebt, name: e.target.value})} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="Напр: Ипотека Сбер" />
                            </div>

                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Остаток долга</label>
                                    <input type="number" value={newDebt.currentBalance || ''} onChange={e => setNewDebt({...newDebt, currentBalance: Number(e.target.value), totalAmount: newDebt.totalAmount || Number(e.target.value)})} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="0" />
                                </div>
                                <div>
                                    <label className="text-[10px] font-black text-gray-500 uppercase ml-2">Всего (для справки)</label>
                                    <input type="number" value={newDebt.totalAmount || ''} onChange={e => setNewDebt({...newDebt, totalAmount: Number(e.target.value)})} className="w-full bg-gray-50 dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="0" />
                                </div>
                            </div>

                            {/* Conditional Fields based on Type */}
                            {newDebtType === 'fixed' ? (
                                <div className="bg-indigo-50/50 dark:bg-indigo-900/10 p-4 rounded-2xl border border-indigo-100 dark:border-indigo-900/20 space-y-4">
                                    <div>
                                        <label className="text-[10px] font-black text-indigo-500 uppercase ml-2">Ежемесячный платеж</label>
                                        <input type="number" value={newDebt.monthlyPayment || ''} onChange={e => setNewDebt({...newDebt, monthlyPayment: Number(e.target.value)})} className="w-full bg-white dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="0" />
                                    </div>
                                    <div>
                                        <label className="text-[10px] font-black text-indigo-500 uppercase ml-2">День платежа (1-31)</label>
                                        <input type="number" min="1" max="31" value={newDebt.paymentDay || ''} onChange={e => setNewDebt({...newDebt, paymentDay: Number(e.target.value)})} className="w-full bg-white dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" placeholder="10" />
                                    </div>
                                </div>
                            ) : (
                                <div className="bg-purple-50/50 dark:bg-purple-900/10 p-4 rounded-2xl border border-purple-100 dark:border-purple-900/20 space-y-4">
                                    <div>
                                        <label className="text-[10px] font-black text-purple-500 uppercase ml-2">Закрыть до</label>
                                        <input type="date" value={newDebt.finalClosingDate || ''} onChange={e => setNewDebt({...newDebt, finalClosingDate: e.target.value})} className="w-full bg-white dark:bg-[#2C2C2E] p-4 rounded-2xl font-bold text-sm outline-none" />
                                    </div>

                                    {flexibleSuggestion && (
                                        <div className="text-xs text-purple-700 dark:text-purple-300 bg-white dark:bg-purple-900/30 p-3 rounded-xl">
                                            💡 Рекомендуемый минимум: <b>{flexibleSuggestion.recommended.toLocaleString()} ₽</b>
                                            <div className="opacity-70 text-[10px] mt-1">
                                                (Чтобы закрыть за {flexibleSuggestion.months} мес.)
                                            </div>
                                        </div>
                                    )}
                                </div>
                            )}
                        </div>

                        {/* Preview */}
                        <div className="mt-6 p-4 bg-gray-50 dark:bg-[#2C2C2E] rounded-2xl text-xs text-gray-500 font-medium leading-relaxed">
                            {newDebt.name && (
                                <>
                                    <span className="block font-bold text-[#1C1C1E] dark:text-white mb-1">Предпросмотр:</span>
                                    {newDebtType === 'fixed' ? (
                                        `Следующий платеж ${newDebt.monthlyPayment?.toLocaleString()} ₽ до ${newDebt.paymentDay}-го числа.`
                                    ) : (
                                        `Цель: закрыть ${newDebt.currentBalance?.toLocaleString()} ₽ до ${newDebt.finalClosingDate ? new Date(newDebt.finalClosingDate).toLocaleDateString() : '...'}`
                                    )}
                                </>
                            )}
                        </div>

                        <button 
                            onClick={handleSaveDebt}
                            disabled={!newDebt.name || !newDebt.currentBalance}
                            className="w-full mt-6 bg-[#1C1C1E] dark:bg-white text-white dark:text-black py-4 rounded-2xl font-black uppercase text-xs tracking-widest shadow-lg active:scale-95 transition-transform disabled:opacity-50"
                        >
                            Сохранить долг
                        </button>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    </div>
  );
};

export default SmartDebtPlanner;

import React, { useState, useMemo, useEffect } from 'react';
import {
  Plus,
  Trash2,
  ShoppingBag,
  CheckCircle2,
  Circle,
  Search,
  ShoppingCart,
  Check,
  Send,
  X
} from 'lucide-react';
import { ShoppingItem, AppSettings, FamilyMember } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { addItem, updateItem, deleteItem, deleteItemsBatch } from '../utils/db';
import { detectProductCategory } from '../utils/categorizer';
import { toast } from 'sonner';

interface ShoppingListProps {
  items: ShoppingItem[];
  setItems: React.Dispatch<React.SetStateAction<ShoppingItem[]>>;
  settings: AppSettings;
  members: FamilyMember[];
  onMoveToPantry: (item: ShoppingItem) => Promise<void>;
  onSendToTelegram: (items: ShoppingItem[]) => Promise<boolean>;
}

const AISLES = [
    { id: 'produce', label: 'Фрукты и овощи', icon: '🥦' },
    { id: 'dairy', label: 'Молочные продукты', icon: '🥛' },
    { id: 'meat', label: 'Мясо', icon: '🥩' },
    { id: 'bakery', label: 'Выпечка', icon: '🍞' },
    { id: 'grocery', label: 'Бакалея', icon: '🍝' },
    { id: 'drinks', label: 'Напитки', icon: '🧃' },
    { id: 'sweets', label: 'Сладости', icon: '🍫' },
    { id: 'frozen', label: 'Заморозка', icon: '🧊' },
    { id: 'household', label: 'Бытовая химия', icon: '🧼' },
    { id: 'beauty', label: 'Красота', icon: '💄' },
    { id: 'pets', label: 'Животные', icon: '🐱' },
    { id: 'pharmacy', label: 'Аптека', icon: '💊' },
    { id: 'electronics', label: 'Электроника', icon: '🔌' },
    { id: 'clothes', label: 'Одежда', icon: '👕' },
    { id: 'other', label: 'Разное', icon: '📦' },
];

const UNITS = ['шт', 'кг', 'г', 'л', 'мл', 'упак.'];

const ShoppingListDesktop: React.FC<ShoppingListProps> = ({
    items, setItems, settings, members, onMoveToPantry, onSendToTelegram
}) => {
  const [inputValue, setInputValue] = useState('');
  const [amountValue, setAmountValue] = useState(1);
  const [unitValue, setUnitValue] = useState('шт');
  const [selectedCategoryId, setSelectedCategoryId] = useState('other');
  const [searchQuery, setSearchQuery] = useState('');

  // Editing State
  const [editingItem, setEditingItem] = useState<ShoppingItem | null>(null);

  const { familyId, user } = useAuth();
  const isDarkMode = settings.theme === 'dark';

  // Smart Category Detection
  useEffect(() => {
      if (inputValue.trim() && !editingItem) {
          const detected = detectProductCategory(inputValue);
          if (detected !== 'other') {
              setSelectedCategoryId(detected);
          }
      }
  }, [inputValue, editingItem]);

  const handleSaveItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim()) return;

    const cleanTitle = inputValue.trim();

    if (editingItem) {
        // Update existing item explicitly
        const updatedItem = {
            ...editingItem,
            title: cleanTitle,
            amount: String(amountValue),
            unit: unitValue as any,
            category: selectedCategoryId
        };
        setItems(prev => prev.map(i => i.id === editingItem.id ? updatedItem : i));
        if (familyId) await updateItem(familyId, 'shopping', editingItem.id, updatedItem);
        setEditingItem(null);
    } else {
        // Check for duplicates (active or completed)
        const existingItem = items.find(i => i.title.toLowerCase() === cleanTitle.toLowerCase());

        if (existingItem) {
            // Merge logic
            // Parse existing amount. Handle simple numbers. If complex string, default to 0 and just append.
            const currentAmount = parseFloat(existingItem.amount || '0') || 0;
            const newAmount = currentAmount + amountValue;

            const updatedItem: ShoppingItem = {
                ...existingItem,
                amount: String(newAmount), // Update amount
                unit: unitValue as any, // Update unit to latest choice
                completed: false, // Bring back to active
                category: selectedCategoryId !== 'other' ? selectedCategoryId : existingItem.category // Update category if new one is better
            };

            setItems(prev => prev.map(i => i.id === existingItem.id ? updatedItem : i));
            if (familyId) await updateItem(familyId, 'shopping', existingItem.id, updatedItem);

            toast.success(`Количество обновлено: ${cleanTitle}`);
        } else {
            // Create new
            const newItem: ShoppingItem = {
              id: Date.now().toString(),
              title: cleanTitle,
              category: selectedCategoryId,
              amount: String(amountValue),
              unit: unitValue as any,
              completed: false,
              memberId: user?.uid || 'user',
              priority: 'medium'
            };
            setItems(prev => [newItem, ...prev]);
            if (familyId) await addItem(familyId, 'shopping', newItem);
        }
    }

    setInputValue('');
    setAmountValue(1);
    setUnitValue('шт');
    setSelectedCategoryId('other');
  };

  const handleEditClick = (item: ShoppingItem) => {
      setEditingItem(item);
      setInputValue(item.title);
      setAmountValue(parseFloat(item.amount || '1'));
      setUnitValue(item.unit);
      setSelectedCategoryId(item.category);
  };

  const cancelEdit = () => {
      setEditingItem(null);
      setInputValue('');
      setAmountValue(1);
      setUnitValue('шт');
      setSelectedCategoryId('other');
  };

  const toggleComplete = async (item: ShoppingItem) => {
    const updated = { ...item, completed: !item.completed };
    setItems(prev => prev.map(i => i.id === item.id ? updated : i));
    if (familyId) await updateItem(familyId, 'shopping', item.id, { completed: updated.completed });
  };

  const handleDeleteItem = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // Prevent edit click
    setItems(prev => prev.filter(item => item.id !== id));
    if (familyId) await deleteItem(familyId, 'shopping', id);
    if (editingItem?.id === id) cancelEdit();
  };

  const clearCompleted = async () => {
    const completedIds = items.filter(i => i.completed).map(i => i.id);

    if (completedIds.length === 0) {
        toast.info("Нет купленных товаров для удаления");
        return;
    }

    if (window.confirm(`Вы точно хотите удалить ${completedIds.length} купленных товаров?`)) {
        // Optimistic update
        setItems(prev => prev.filter(item => !item.completed));

        if (familyId) {
            try {
                await deleteItemsBatch(familyId, 'shopping', completedIds);
                toast.success("Список очищен");
            } catch (e) {
                console.error(e);
                toast.error("Ошибка при удалении из базы");
            }
        } else {
            toast.success("Список очищен");
        }
    }
  };

  const handleTelegramClick = () => {
      if (!settings.telegramBotToken || !settings.telegramChatId) {
          toast.error("Пожалуйста, настройте Telegram-бота в настройках", {
              description: "Нужен токен бота и ID чата"
          });
          return;
      }
      // Send active items (not completed)
      onSendToTelegram(items.filter(i => !i.completed));
  };

  const filteredItems: ShoppingItem[] = items.filter(item => 
    item.title.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const activeItems: ShoppingItem[] = filteredItems.filter(i => !i.completed);
  const completedItems: ShoppingItem[] = filteredItems.filter(i => i.completed);

  const groupedActiveItems = useMemo(() => {
    return activeItems.reduce<Record<string, ShoppingItem[]>>((groups, item) => {
      // Map ID to Label for grouping display
      const cat = AISLES.find(a => a.id === item.category);
      const catLabel = cat ? cat.label : 'Разное';

      if (!groups[catLabel]) groups[catLabel] = [];
      groups[catLabel].push(item);
      return groups;
    }, {});
  }, [activeItems]);

  const progress = items.length ? Math.round((completedItems.length / items.length) * 100) : 0;

  return (
    <div className={`flex h-full w-full transition-colors duration-500 font-sans ${isDarkMode ? 'bg-[#0A0A0C] text-white' : 'bg-[#F4F7FB] text-[#1C1C1E]'} overflow-hidden`}>

      {/* Sidebar */}
      <aside className="hidden lg:flex flex-col w-80 bg-[#FFFFFF] dark:bg-[#161618] border-r border-black/5 dark:border-white/5 p-8 h-full overflow-y-auto custom-scrollbar shrink-0">

        <div className="space-y-8 mt-4">
          <div className="space-y-3">
            <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-widest ml-1">Поиск</p>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
              <input 
                type="text"
                placeholder="Найти продукт..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-[#F8F9FB] dark:bg-white/5 border-none rounded-2xl py-3 pl-11 pr-4 text-sm font-bold focus:ring-2 focus:ring-blue-500/50 outline-none transition-all dark:text-white"
              />
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center">
                <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-widest ml-1">
                    {editingItem ? 'Редактирование' : 'Новый товар'}
                </p>
                {editingItem && (
                    <button onClick={cancelEdit} className="text-gray-400 hover:text-blue-500"><X size={14}/></button>
                )}
            </div>

            <form onSubmit={handleSaveItem} className="space-y-4">
              <input 
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Название продукта..."
                className="w-full bg-[#F8F9FB] dark:bg-white/5 border border-transparent focus:border-blue-500/20 rounded-2xl py-3.5 px-4 text-sm font-bold outline-none transition-all dark:text-white"
              />

              <div className="grid grid-cols-2 gap-2">
                <input 
                  type="number"
                  min="0.1"
                  step="0.1"
                  value={amountValue}
                  onChange={(e) => setAmountValue(parseFloat(e.target.value) || 0)}
                  placeholder="Кол-во"
                  className="w-full bg-[#F8F9FB] dark:bg-white/5 border border-transparent focus:border-blue-500/20 rounded-xl py-3 px-4 text-sm font-bold outline-none transition-all dark:text-white"
                />
                <select 
                  value={unitValue}
                  onChange={(e) => setUnitValue(e.target.value)}
                  className="bg-[#F8F9FB] dark:bg-white/5 border-none rounded-xl py-3 px-3 text-xs font-black uppercase outline-none cursor-pointer dark:text-white"
                >
                  {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>

              <select 
                value={selectedCategoryId}
                onChange={(e) => setSelectedCategoryId(e.target.value)}
                className="w-full bg-[#F8F9FB] dark:bg-white/5 border-none rounded-2xl py-3.5 px-4 text-xs font-black uppercase tracking-wider outline-none cursor-pointer dark:text-white"
              >
                {AISLES.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
              </select>

              <button 
                type="submit"
                disabled={!inputValue.trim()}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-2xl font-black text-xs shadow-lg shadow-blue-600/20 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
              >
                <Plus size={18} strokeWidth={3} />
                {editingItem ? 'СОХРАНИТЬ' : 'ДОБАВИТЬ'}
              </button>
            </form>
          </div>

          <div className="space-y-2 pt-4 border-t border-black/5 dark:border-white/5">
            <button 
              onClick={clearCompleted}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-all font-bold text-sm"
            >
              <Trash2 size={18} />
              Очистить купленное
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-8 lg:p-16 overflow-y-auto no-scrollbar">
        <div className="max-w-6xl mx-auto space-y-12">

          {/* Header Stats & Share */}
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div className="animate-in fade-in slide-in-from-left-4 duration-500">
              <div className="flex items-center gap-4 mb-2">
                <h2 className="text-4xl font-black tracking-tight leading-none">Прогресс {progress}%</h2>
                <button 
                  onClick={handleTelegramClick}
                  disabled={items.length === 0}
                  className="flex items-center gap-2 bg-[#229ED9] hover:bg-[#229ED9]/90 text-white px-4 py-2 rounded-xl text-xs font-black shadow-lg shadow-[#229ED9]/20 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none"
                >
                  <Send size={14} fill="currentColor" />
                  В TELEGRAM
                </button>
              </div>
              <p className="text-gray-500 dark:text-gray-400 font-bold flex items-center gap-2">
                <Check size={18} className="text-green-500" />
                Осталось купить: {activeItems.length}
              </p>
            </div>

            <div className="flex bg-white dark:bg-[#161618] p-2 rounded-2xl shadow-sm border border-black/5 dark:border-white/5">
              <div className="px-6 py-2 border-r border-black/5 dark:border-white/5 text-center">
                <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Всего</p>
                <p className="text-xl font-black">{items.length}</p>
              </div>
              <div className="px-6 py-2 text-center">
                <p className="text-[10px] font-black text-blue-500 uppercase mb-1">Куплено</p>
                <p className="text-xl font-black text-blue-500">{completedItems.length}</p>
              </div>
            </div>
          </div>

          {/* Grid Layout - Active Items */}
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-x-12 gap-y-10 items-start">
            {Object.keys(groupedActiveItems).length > 0 ? (
              Object.entries(groupedActiveItems).map(([category, catItems]) => (
                <div key={category} className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500 break-inside-avoid">
                  <div className="flex items-center justify-between px-2">
                    <div className="flex items-center gap-3">
                      <div className="w-1.5 h-6 bg-blue-500 rounded-full"></div>
                      <h3 className="text-xs font-black text-gray-400 dark:text-gray-400 uppercase tracking-widest">
                        {category}
                      </h3>
                    </div>
                    <span className="text-[10px] font-black bg-white dark:bg-white/5 px-2 py-0.5 rounded-lg border border-black/5 dark:border-white/5">{catItems.length} поз.</span>
                  </div>

                  <div className="bg-white dark:bg-[#161618] rounded-[36px] shadow-[0_10px_50px_-15px_rgba(0,0,0,0.04)] dark:shadow-none border border-black/5 dark:border-white/5 overflow-hidden">
                    {catItems.map((item, idx) => (
                        <div 
                        key={item.id}
                        onClick={() => handleEditClick(item)}
                        className={`flex items-center gap-5 p-6 transition-all group hover:bg-gray-50/50 dark:hover:bg-white/[0.02] cursor-pointer ${idx !== catItems.length - 1 ? 'border-b border-black/[0.03] dark:border-white/[0.03]' : ''}`}
                        >
                        <button 
                            onClick={(e) => { e.stopPropagation(); toggleComplete(item); }}
                            className={`transition-all active:scale-75 text-gray-200 dark:text-gray-700 hover:text-blue-500`}
                        >
                            <Circle size={36} strokeWidth={1} />
                        </button>

                        <div className="flex-1 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                            <div className="flex items-center gap-2">
                                <span className={`text-lg font-bold transition-all text-gray-800 dark:text-gray-200`}>
                                    {item.title}
                                </span>
                            </div>

                            <div className={`flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-black self-start sm:self-auto transition-colors bg-blue-50 dark:bg-blue-500/10 text-blue-600 dark:text-blue-400`}>
                                <span>{item.amount}</span>
                                <span>{item.unit}</span>
                            </div>
                        </div>

                        <button 
                            onClick={(e) => handleDeleteItem(e, item.id)}
                            className="opacity-0 group-hover:opacity-100 p-2.5 text-gray-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-xl transition-all"
                        >
                            <Trash2 size={20} />
                        </button>
                        </div>
                    ))}
                  </div>
                </div>
              ))
            ) : (
                items.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-32 text-center">
                        <div className="w-24 h-24 bg-white dark:bg-[#161618] rounded-[40px] flex items-center justify-center shadow-2xl mb-8 border border-black/5 dark:border-white/5">
                        <ShoppingBag size={48} strokeWidth={1} className="text-blue-500 opacity-50" />
                        </div>
                        <p className="text-2xl font-black italic opacity-20">Список покупок пуст</p>
                        <p className="text-sm font-bold text-gray-400 mt-2">Добавьте нужные продукты слева</p>
                    </div>
                )
            )}
          </div>

          {/* Completed Items Section */}
          {completedItems.length > 0 && (
              <div className="pt-10 border-t border-black/5 dark:border-white/5">
                  <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-6 px-2">Куплено ({completedItems.length})</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 opacity-60">
                      {completedItems.map(item => (
                          <div key={item.id} className="bg-white dark:bg-[#161618] p-4 rounded-2xl flex items-center gap-3 border border-black/5 dark:border-white/5">
                              <button onClick={() => toggleComplete(item)} className="text-green-500">
                                  <CheckCircle2 size={24} />
                              </button>
                              <span className="text-sm font-bold text-gray-400 line-through flex-1">{item.title}</span>
                              <button onClick={(e) => handleDeleteItem(e, item.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                          </div>
                      ))}
                  </div>
              </div>
          )}

        </div>
      </main>
    </div>
  );
};

export default ShoppingListDesktop;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Trash2, Check, Share, X, ScanLine, ShoppingBag, Loader2, Play, Edit2, ChevronLeft, Mic, BrainCircuit, ArrowRight } from 'lucide-react';
import { ShoppingItem, AppSettings, FamilyMember } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { addItem, updateItem, deleteItem, addItemsBatch } from '../utils/db';
import { searchOnlineDatabase } from '../utils/barcodeLookup';
import { detectProductCategory } from '../utils/categorizer';
import { GoogleGenAI } from "@google/genai";
import ShoppingListDesktop from './ShoppingListDesktop';
import { toast } from 'sonner';

interface ShoppingListProps {
  items: ShoppingItem[];
  setItems: React.Dispatch<React.SetStateAction<ShoppingItem[]>>;
  settings: AppSettings;
  members: FamilyMember[];
  onCompletePurchase?: () => void;
  onMoveToPantry: (item: ShoppingItem) => Promise<void>;
  onSendToTelegram: (items: ShoppingItem[]) => Promise<boolean>;
}

const AISLES = [
    { id: 'produce', label: 'Овощи/Фрукты', icon: '🥦' },
    { id: 'dairy', label: 'Молочка', icon: '🥛' },
    { id: 'meat', label: 'Мясо/Рыба', icon: '🥩' },
    { id: 'bakery', label: 'Хлеб', icon: '🍞' },
    { id: 'grocery', label: 'Бакалея', icon: '🍝' },
    { id: 'drinks', label: 'Напитки', icon: '🧃' },
    { id: 'sweets', label: 'Сладости', icon: '🍫' },
    { id: 'frozen', label: 'Заморозка', icon: '🧊' },
    { id: 'household', label: 'Быт. химия', icon: '🧼' },
    { id: 'beauty', label: 'Красота', icon: '💄' },
    { id: 'pets', label: 'Животные', icon: '🐱' },
    { id: 'pharmacy', label: 'Аптека', icon: '💊' },
    { id: 'electronics', label: 'Электроника', icon: '🔌' },
    { id: 'clothes', label: 'Одежда', icon: '👕' },
    { id: 'other', label: 'Разное', icon: '📦' },
];

const UNITS = ['шт', 'кг', 'уп', 'л'] as const;

const ShoppingListMobile: React.FC<ShoppingListProps> = ({ 
  items, setItems, settings, members, onMoveToPantry, onSendToTelegram 
}) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Form State
  const [editingItem, setEditingItem] = useState<ShoppingItem | null>(null);
  const [newItemTitle, setNewItemTitle] = useState('');
  const [newItemAmount, setNewItemAmount] = useState('');
  const [newItemUnit, setNewItemUnit] = useState<typeof UNITS[number]>('шт');
  const [selectedAisle, setSelectedAisle] = useState('other');

  const [isScanning, setIsScanning] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [showAllCategories, setShowAllCategories] = useState(false);
  const [shopMode, setShopMode] = useState(false);

  const { familyId, user } = useAuth();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const titleInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const apiKey = settings.geminiApiKey || process.env.API_KEY;

  // Computed properties for categories in modal
  const sortedAisles = AISLES;
  const visibleAisles = showAllCategories ? sortedAisles : sortedAisles.slice(0, 12);

  // Wake Lock for Shop Mode
  useEffect(() => {
    let wakeLock: any = null;
    const requestWakeLock = async () => {
      if ('wakeLock' in navigator && shopMode) {
        try { 
            wakeLock = await (navigator as any).wakeLock.request('screen'); 
        } catch (err) {
            console.warn('Wake Lock error:', err);
        }
      }
    };

    if (shopMode) requestWakeLock();
    return () => { if (wakeLock) wakeLock.release(); };
  }, [shopMode]);

  // Auto-categorization effect for manual input
  useEffect(() => {
      if (newItemTitle.trim() && !editingItem) {
          const detected = detectProductCategory(newItemTitle);
          if (detected !== 'other') {
              setSelectedAisle(detected);
          }
      }
  }, [newItemTitle, editingItem]);

  // Group items by category (Aisle)
  const groupedItems = useMemo(() => {
      const groups: Record<string, ShoppingItem[]> = {};
      AISLES.forEach(a => groups[a.id] = []);

      items.forEach(item => {
          const cat = item.category || 'other';
          if (!groups[cat]) groups[cat] = [];
          groups[cat].push(item);
      });

      return groups;
  }, [items]);

  const activeCount = items.filter(i => !i.completed).length;

  const handleOpenAdd = () => {
      setEditingItem(null);
      setNewItemTitle('');
      setNewItemAmount('');
      setNewItemUnit('шт');
      setSelectedAisle('other');
      setIsAddModalOpen(true);
      setTimeout(() => titleInputRef.current?.focus(), 100);
  };

  const handleOpenEdit = (item: ShoppingItem) => {
      setEditingItem(item);
      setNewItemTitle(item.title);
      setNewItemAmount(item.amount || '');
      setNewItemUnit(item.unit as any || 'шт');
      setSelectedAisle(item.category || 'other');
      setIsAddModalOpen(true);
  };

  const handleSaveItem = async () => {
      if (!newItemTitle.trim()) return;
      const cleanTitle = newItemTitle.trim();

      if (editingItem) {
          // Update Existing
          const updatedItem: ShoppingItem = {
              ...editingItem,
              title: cleanTitle,
              amount: newItemAmount,
              unit: newItemUnit,
              category: selectedAisle,
          };

          setItems(prev => prev.map(i => i.id === editingItem.id ? updatedItem : i));
          if (familyId) await updateItem(familyId, 'shopping', editingItem.id, updatedItem);

          setIsAddModalOpen(false);
          setEditingItem(null);
      } else {
          // Check for duplicate (active or completed)
          const existingItem = items.find(i => i.title.toLowerCase() === cleanTitle.toLowerCase());

          if (existingItem) {
              // Merge
              const currentAmount = parseFloat(existingItem.amount || '0') || 0;
              const addedAmount = parseFloat(newItemAmount) || 1; // Default to 1 if user didn't specify amount but re-added item
              const newAmount = currentAmount + addedAmount;

              const updatedItem: ShoppingItem = {
                  ...existingItem,
                  amount: String(newAmount),
                  unit: newItemUnit, // Use new unit if different
                  completed: false, // Reactivate
                  category: selectedAisle !== 'other' ? selectedAisle : existingItem.category
              };

              setItems(prev => prev.map(i => i.id === existingItem.id ? updatedItem : i));
              if (familyId) await updateItem(familyId, 'shopping', existingItem.id, updatedItem);

              toast.success(`Количество увеличено: ${cleanTitle}`);
          } else {
              // Create New
              const newItem: ShoppingItem = {
                  id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
                  title: cleanTitle,
                  amount: newItemAmount,
                  unit: newItemUnit,
                  category: selectedAisle,
                  completed: false,
                  memberId: user?.uid || 'user',
                  priority: 'medium'
              };

              setItems(prev => [...prev, newItem]);
              if (familyId) await addItem(familyId, 'shopping', newItem);
          }

          setNewItemTitle('');
          setNewItemAmount('');
          setNewItemUnit('шт');
          setSelectedAisle('other');

          // Keep modal open or focus for next item if creating multiple
          titleInputRef.current?.focus();
      }
  };

  const handleToggle = async (item: ShoppingItem) => {
      const updated = { ...item, completed: !item.completed };
      setItems(items.map(i => i.id === item.id ? updated : i));
      if (familyId) await updateItem(familyId, 'shopping', item.id, { completed: updated.completed });
  };

  const handleDelete = async (id: string) => {
      setItems(items.filter(i => i.id !== id));
      if (familyId) await deleteItem(familyId, 'shopping', id);
      if (editingItem?.id === id) setIsAddModalOpen(false);
  };

  const handleBarcodeScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setIsScanning(true);
      try {
          if ('BarcodeDetector' in window) {
              const BarcodeDetector = (window as any).BarcodeDetector;
              const detector = new BarcodeDetector({ formats: ['ean_13', 'ean_8'] });
              const bitmap = await createImageBitmap(file);
              const barcodes = await detector.detect(bitmap);

              if (barcodes.length > 0) {
                  const code = barcodes[0].rawValue;
                  const product = await searchOnlineDatabase(code);
                  if (product) {
                      setNewItemTitle(product.title);
                      setNewItemAmount(product.amount);
                      setNewItemUnit(product.unit);
                      setSelectedAisle(product.category);
                  } else {
                      alert('Товар не найден в базе, введите название вручную');
                  }
              } else {
                  alert('Штрихкод не распознан');
              }
          } else {
              alert('Ваш браузер не поддерживает сканирование штрихкодов');
          }
      } catch (err) {
          console.error(err);
          alert('Ошибка сканирования');
      } finally {
          setIsScanning(false);
          if (fileInputRef.current) fileInputRef.current.value = '';
      }
  };

  // AI Voice Processing
  const processVoiceInputWithGemini = async (text: string) => {
      if (!apiKey) {
          alert('API Key не настроен в настройках приложения');
          return;
      }

      setIsProcessingAI(true);
      try {
          const ai = new GoogleGenAI({ apiKey });
          const prompt = `
            Analyze the following shopping list request in Russian: "${text}".
            Return a pure JSON array of objects. 
            Each object must have:
            - "title": string (product name in Russian, capitalized)
            - "amount": string (quantity number, default "1" if not specified)
            - "unit": string (one of: "шт", "кг", "уп", "л". Detect based on context, e.g., milk -> л, potatoes -> кг, eggs -> шт. Default to "шт")
            - "category": string (one of: "produce", "dairy", "meat", "bakery", "grocery", "drinks", "sweets", "frozen", "household", "beauty", "pets", "pharmacy", "electronics", "clothes", "other")

            Example input: "купи два молока хлеб и десяток яиц"
            Example output: [{"title": "Молоко", "amount": "2", "unit": "л", "category": "dairy"}, {"title": "Хлеб", "amount": "1", "unit": "шт", "category": "bakery"}, {"title": "Яйца", "amount": "10", "unit": "шт", "category": "dairy"}]
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: { responseMimeType: "application/json" }
          });

          const jsonString = response.text || "[]";
          const parsedItems = JSON.parse(jsonString);

          if (Array.isArray(parsedItems) && parsedItems.length > 0) {
              const newItems: ShoppingItem[] = parsedItems.map((p: any) => ({
                  id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
                  title: p.title,
                  amount: p.amount,
                  unit: p.unit,
                  category: p.category,
                  completed: false,
                  memberId: user?.uid || 'user',
                  priority: 'medium'
              }));

              // Batch add (Note: currently doesn't check duplicates for voice batch, simple append)
              // Ideally, this should also loop through handleSaveItem logic for merge, but batch is more efficient.
              setItems(prev => [...prev, ...newItems]);
              if (familyId) {
                  await addItemsBatch(familyId, 'shopping', newItems);
              }
          }

      } catch (err) {
          console.error("Gemini Error:", err);
          alert("Не удалось распознать товары. Попробуйте еще раз.");
      } finally {
          setIsProcessingAI(false);
      }
  };

  const startListening = () => {
      const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (!SR) { alert("Голосовой ввод не поддерживается"); return; }

      if (isListening) {
          recognitionRef.current?.stop();
          setIsListening(false);
          return;
      }

      const r = new SR();
      recognitionRef.current = r;
      r.lang = 'ru-RU';
      r.interimResults = false;

      r.onstart = () => setIsListening(true);
      r.onend = () => { if(!isProcessingAI) setIsListening(false); };

      r.onresult = (e: any) => {
          const text = e.results[0][0].transcript;
          if (text) {
              setIsListening(false);
              processVoiceInputWithGemini(text);
          }
      };

      r.onerror = (e: any) => {
          console.error(e);
          setIsListening(false);
      };

      r.start();
  };

  // Shop Mode Overlay
  if (shopMode) {
      return (
        <div className="fixed inset-0 z-[2000] bg-[#F2F2F7] dark:bg-black flex flex-col overflow-hidden">
            {/* Shop Mode Header */}
            <div className="px-6 py-4 bg-white dark:bg-[#1C1C1E] border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                <button 
                    onClick={() => setShopMode(false)}
                    className="flex items-center gap-2 text-blue-500 font-bold text-sm active:opacity-70"
                >
                    <ChevronLeft size={20} />
                    Назад
                </button>
                <h3 className="font-black text-lg text-[#1C1C1E] dark:text-white uppercase tracking-widest">В магазине</h3>
                <div className="w-8" />
            </div>

            {/* Shop Mode Content */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {activeCount === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-center opacity-40">
                        <Check size={64} className="text-green-500 mb-4" />
                        <p className="text-lg font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest">Все куплено!</p>
                    </div>
                ) : (
                    AISLES.map(aisle => {
                        const aisleItems = groupedItems[aisle.id] || [];
                        const activeItems = aisleItems.filter(i => !i.completed);
                        if (activeItems.length === 0) return null;

                        return (
                            <div key={aisle.id} className="bg-white dark:bg-[#1C1C1E] p-5 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5">
                                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 pl-2 flex items-center gap-2">
                                    <span>{aisle.icon}</span> {aisle.label}
                                </h3>
                                <div className="space-y-3">
                                    <AnimatePresence>
                                        {activeItems.map(item => (
                                            <motion.div 
                                                key={item.id}
                                                layout
                                                initial={{ opacity: 0, scale: 0.95 }}
                                                animate={{ opacity: 1, scale: 1 }}
                                                exit={{ opacity: 0, scale: 0.95 }}
                                                transition={{ duration: 0.2 }}
                                                className="flex items-center justify-between p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl active:scale-[0.98] transition-transform cursor-pointer border border-blue-100 dark:border-white/5"
                                                onClick={() => handleToggle(item)}
                                            >
                                                <div className="flex items-center gap-4 overflow-hidden flex-1">
                                                    <div className="w-8 h-8 rounded-full border-2 border-blue-500 flex items-center justify-center shrink-0">
                                                    </div>
                                                    <div className="min-w-0">
                                                        <span className="text-lg font-bold text-[#1C1C1E] dark:text-white truncate block leading-tight">{item.title}</span>
                                                        {(item.amount || item.unit) && (
                                                            <span className="text-sm font-bold text-gray-500 dark:text-gray-400">
                                                                {item.amount} {item.unit}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>
                                            </motion.div>
                                        ))}
                                    </AnimatePresence>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
        </div>
      );
  }

  // Standard Mobile Mode
  return (
    <div className="space-y-4 h-full flex flex-col relative">
        {/* Loading Overlay for AI */}
        <AnimatePresence>
            {(isListening || isProcessingAI) && (
                <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="absolute inset-0 z-50 bg-white/80 dark:bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center rounded-[2.5rem]">
                    <div className="bg-white dark:bg-[#2C2C2E] p-8 rounded-[3rem] shadow-2xl flex flex-col items-center gap-4 border dark:border-white/10">
                        {isListening ? (
                            <div className="relative">
                                <div className="absolute inset-0 bg-red-500/30 rounded-full animate-ping blur-md" />
                                <Mic size={48} className="text-red-500 relative z-10" />
                            </div>
                        ) : (
                            <BrainCircuit size={48} className="text-purple-500 animate-pulse" />
                        )}
                        <span className="font-black text-lg text-[#1C1C1E] dark:text-white">
                            {isListening ? 'Слушаю...' : 'Анализирую список...'}
                        </span>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>

        {/* Header Actions */}
        <div className="flex gap-2 shrink-0 items-stretch">
            <button 
                onClick={handleOpenAdd}
                className="flex-[2] bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] shadow-sm flex items-center justify-center gap-2 text-[#1C1C1E] dark:text-white font-black uppercase text-xs tracking-widest active:scale-95 transition-transform border border-transparent dark:border-white/5"
            >
                <Plus size={18} strokeWidth={3} /> Добавить
            </button>

            <button 
                onClick={startListening}
                className={`flex-1 p-4 rounded-[2rem] shadow-sm flex items-center justify-center transition-all bg-white dark:bg-[#1C1C1E] border dark:border-white/5 active:scale-95 ${isListening ? 'text-red-500 bg-red-50 dark:bg-red-900/20' : 'text-blue-500'}`}
            >
                <Mic size={20} />
            </button>

            <button 
                onClick={() => setShopMode(true)}
                className="p-4 rounded-[2rem] shadow-sm flex items-center justify-center gap-2 font-black uppercase text-xs tracking-widest transition-all bg-blue-500 text-white shadow-blue-500/20 active:scale-95"
            >
                <Play size={18} fill="currentColor" />
            </button>

            <button 
                onClick={() => onSendToTelegram(items.filter(i => !i.completed))}
                disabled={activeCount === 0}
                className="bg-[#1C1C1E] dark:bg-white text-white dark:text-black p-4 rounded-[2rem] shadow-lg active:scale-95 transition-transform disabled:opacity-50 disabled:shadow-none"
            >
                <Share size={20} />
            </button>
        </div>

        {/* Lists Container */}
        <div className="flex-1 overflow-y-auto no-scrollbar space-y-4 pb-20">
            {activeCount === 0 && items.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center opacity-40">
                    <ShoppingBag size={48} className="mb-4 text-gray-300 dark:text-gray-600" />
                    <p className="text-sm font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest">Список пуст</p>
                </div>
            )}

            {AISLES.map(aisle => {
                const aisleItems = groupedItems[aisle.id] || [];
                const activeItems = aisleItems.filter(i => !i.completed);
                if (activeItems.length === 0) return null;

                return (
                    <div key={aisle.id} className="bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] shadow-sm border border-gray-100 dark:border-white/5">
                        <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 pl-2 flex items-center gap-2">
                            <span>{aisle.icon}</span> {aisle.label}
                        </h3>
                        <div className="space-y-2">
                            <AnimatePresence>
                                {activeItems.map(item => (
                                    <motion.div 
                                        key={item.id}
                                        layout
                                        initial={{ opacity: 0, scale: 0.95 }}
                                        animate={{ opacity: 1, scale: 1 }}
                                        exit={{ opacity: 0, scale: 0.95 }}
                                        transition={{ duration: 0.2 }}
                                        onClick={() => handleOpenEdit(item)}
                                        className="flex items-center justify-between p-3 bg-gray-50 dark:bg-[#2C2C2E] rounded-2xl group cursor-pointer active:scale-[0.99] transition-transform"
                                    >
                                        <div className="flex items-center gap-3 overflow-hidden flex-1">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); handleToggle(item); }}
                                                className="w-6 h-6 rounded-full border-2 border-gray-300 dark:border-gray-600 flex items-center justify-center shrink-0 hover:border-green-500 hover:text-green-500 transition-colors"
                                            >
                                                {item.completed && <Check size={14} />}
                                            </button>
                                            <div className="min-w-0">
                                                <span className="text-sm font-bold text-[#1C1C1E] dark:text-white truncate block">{item.title}</span>
                                                {(item.amount || item.unit) && (
                                                    <span className="text-[10px] font-bold text-gray-400">
                                                        {item.amount} {item.unit}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="p-2 text-gray-300"><Edit2 size={14}/></div>
                                        </div>
                                    </motion.div>
                                ))}
                            </AnimatePresence>
                        </div>
                    </div>
                );
            })}

            {/* Completed Items Section */}
            {items.some(i => i.completed) && (
                <div className="pt-4 border-t border-gray-200 dark:border-white/10 mt-4">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 pl-2">Куплено</h3>
                    <div className="space-y-2 opacity-60">
                        {items.filter(i => i.completed).map(item => (
                            <div key={item.id} className="flex items-center justify-between p-3 bg-gray-100 dark:bg-[#2C2C2E] rounded-2xl">
                                <div className="flex items-center gap-3 overflow-hidden flex-1">
                                    <button onClick={() => handleToggle(item)} className="w-6 h-6 rounded-full bg-green-500 text-white flex items-center justify-center shrink-0">
                                        <Check size={14} />
                                    </button>
                                    <span className="text-sm font-bold text-gray-500 dark:text-gray-400 line-through decoration-gray-400">{item.title}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button onClick={() => onMoveToPantry(item)} className="p-1.5 bg-blue-100 dark:bg-blue-900/30 text-blue-500 rounded-lg" title="В кладовку"><ArrowRight size={14}/></button>
                                    <button onClick={() => handleDelete(item.id)} className="p-1.5 text-gray-400 hover:text-red-500"><Trash2 size={14}/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>

        {/* Add/Edit Item Modal */}
        <AnimatePresence>
            {isAddModalOpen && (
                <div className="fixed inset-0 z-[1200] flex items-end md:items-center justify-center p-0 md:p-4">
                    <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={() => setIsAddModalOpen(false)} className="absolute inset-0 bg-black/40 backdrop-blur-md" />
                    <motion.div 
                        initial={{y:'100%'}} animate={{y:0}} exit={{y:'100%'}}
                        className="relative bg-[#F2F2F7] dark:bg-black w-full max-w-lg md:rounded-[3rem] rounded-t-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
                        onClick={e => e.stopPropagation()}
                    >
                        <div className="bg-white dark:bg-[#1C1C1E] p-6 flex justify-between items-center border-b border-gray-100 dark:border-white/5">
                            <h3 className="text-xl font-black text-[#1C1C1E] dark:text-white">
                                {editingItem ? 'Редактировать' : 'Добавить покупку'}
                            </h3>
                            <button onClick={() => setIsAddModalOpen(false)} className="w-10 h-10 bg-gray-100 dark:bg-[#2C2C2E] rounded-full flex items-center justify-center text-gray-500 dark:text-gray-300"><X size={20}/></button>
                        </div>

                        <div className="p-6 space-y-6 overflow-y-auto no-scrollbar">
                            <div className="flex flex-col gap-4">
                                <div className="relative">
                                    <input 
                                        ref={titleInputRef}
                                        type="text" 
                                        placeholder="Что купить?" 
                                        value={newItemTitle} 
                                        onChange={e => setNewItemTitle(e.target.value)} 
                                        onKeyDown={e => e.key === 'Enter' && handleSaveItem()}
                                        className="w-full bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] font-bold text-lg outline-none text-[#1C1C1E] dark:text-white pr-14 shadow-sm"
                                    />
                                    <div className="absolute right-2 top-2 bottom-2 flex gap-2">
                                        <button 
                                            onClick={() => fileInputRef.current?.click()}
                                            className="aspect-square h-full flex items-center justify-center bg-gray-100 dark:bg-[#2C2C2E] rounded-full text-gray-500 hover:text-blue-500 transition-colors"
                                        >
                                            {isScanning ? <Loader2 size={20} className="animate-spin"/> : <ScanLine size={20}/>}
                                        </button>
                                    </div>
                                    <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleBarcodeScan} />
                                </div>

                                {/* Width 25% for Amount, rest for Units */}
                                <div className="flex gap-3 h-16">
                                    <input 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="К-во" 
                                        value={newItemAmount} 
                                        onChange={e => setNewItemAmount(e.target.value)} 
                                        onKeyDown={e => e.key === 'Enter' && handleSaveItem()}
                                        className="w-28 bg-white dark:bg-[#1C1C1E] rounded-[2rem] font-bold text-2xl outline-none text-center text-[#1C1C1E] dark:text-white shadow-sm h-full"
                                    />
                                    {/* Units Block - Flex Row */}
                                    <div className="flex-1 bg-white dark:bg-[#1C1C1E] p-1.5 rounded-[2rem] shadow-sm flex items-center justify-between gap-1 h-full">
                                        {UNITS.map(u => (
                                            <button 
                                                key={u}
                                                onClick={() => setNewItemUnit(u)}
                                                className={`flex-1 h-full rounded-[1.5rem] text-[10px] font-black uppercase transition-all flex items-center justify-center ${newItemUnit === u ? 'bg-[#F2F2F7] dark:bg-[#2C2C2E] text-black dark:text-white shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                                            >
                                                {u}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] shadow-sm">
                                <div className="flex justify-between items-center mb-2 px-1">
                                    <span className="text-[10px] font-black text-gray-400 uppercase block">Категория</span>
                                    {sortedAisles.length > 12 && !showAllCategories && (
                                        <button 
                                            onClick={() => setShowAllCategories(true)} 
                                            className="text-[10px] font-bold text-blue-500 uppercase tracking-widest bg-blue-50 dark:bg-blue-900/30 px-2 py-1 rounded-lg hover:bg-blue-100 transition-colors"
                                        >
                                            Показать все
                                        </button>
                                    )}
                                </div>
                                <div className="grid grid-cols-4 gap-2">
                                    {visibleAisles.map(aisle => (
                                        <button 
                                            key={aisle.id} 
                                            onClick={() => setSelectedAisle(aisle.id)} 
                                            className={`flex flex-col items-center justify-center p-2 rounded-2xl transition-all border ${selectedAisle === aisle.id ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-800 shadow-sm' : 'border-transparent hover:bg-gray-50 dark:hover:bg-[#2C2C2E]'}`}
                                        >
                                            <span className="text-xl mb-1">{aisle.icon}</span>
                                            <span className={`text-[9px] font-bold text-center leading-none w-full truncate ${selectedAisle === aisle.id ? 'text-blue-700 dark:text-blue-300' : 'text-gray-500 dark:text-gray-400'}`}>{aisle.label}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="p-6 bg-white dark:bg-[#1C1C1E] border-t border-gray-100 dark:border-white/5 flex flex-col gap-3">
                            <button 
                                onClick={handleSaveItem}
                                disabled={!newItemTitle.trim()}
                                className="w-full bg-blue-500 text-white font-black py-5 rounded-[2rem] uppercase text-xs flex items-center justify-center gap-2 active:scale-95 shadow-xl transition-all disabled:opacity-50 disabled:shadow-none"
                            >
                                <Plus size={18} strokeWidth={3}/> 
                                {editingItem ? 'Сохранить изменения' : 'Добавить'}
                            </button>

                            {editingItem && (
                                <button 
                                    onClick={() => handleDelete(editingItem.id)}
                                    className="w-full bg-red-50 dark:bg-red-900/20 text-red-500 font-black py-4 rounded-[2rem] uppercase text-xs flex items-center justify-center gap-2 active:scale-95 transition-all"
                                >
                                    <Trash2 size={16} /> Удалить
                                </button>
                            )}
                        </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    </div>
  );
};

const ShoppingList: React.FC<ShoppingListProps> = (props) => {
  const [isDesktop, setIsDesktop] = useState(false);

  useEffect(() => {
    const checkDesktop = () => setIsDesktop(window.innerWidth >= 768);
    checkDesktop();
    window.addEventListener('resize', checkDesktop);
    return () => window.removeEventListener('resize', checkDesktop);
  }, []);

  if (isDesktop) {
      return <ShoppingListDesktop {...props} />;
  }

  return <ShoppingListMobile {...props} />;
};

export default ShoppingList;

import React, { useState, useMemo, useEffect } from 'react';
import {
  Plus,
  Trash2,
  ShoppingBag,
  CheckCircle2,
  Circle,
  Search,
  ShoppingCart,
  Check,
  Send,
  X
} from 'lucide-react';
import { ShoppingItem, AppSettings, FamilyMember } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { addItem, updateItem, deleteItem, deleteItemsBatch } from '../utils/db';
import { detectProductCategory } from '../utils/categorizer';
import { toast } from 'sonner';

interface ShoppingListProps {
  items: ShoppingItem[];
  setItems: React.Dispatch<React.SetStateAction<ShoppingItem[]>>;
  settings: AppSettings;
  members: FamilyMember[];
  onMoveToPantry: (item: ShoppingItem) => Promise<void>;
  onSendToTelegram: (items: ShoppingItem[]) => Promise<boolean>;
}

const AISLES = [
    { id: 'produce', label: 'Фрукты и овощи', icon: '🥦' },
    { id: 'dairy', label: 'Молочные продукты', icon: '🥛' },
    { id: 'meat', label: 'Мясо', icon: '🥩' },
    { id: 'bakery', label: 'Выпечка', icon: '🍞' },
    { id: 'grocery', label: 'Бакалея', icon: '🍝' },
    { id: 'drinks', label: 'Напитки', icon: '🧃' },
    { id: 'sweets', label: 'Сладости', icon: '🍫' },
    { id: 'frozen', label: 'Заморозка', icon: '🧊' },
    { id: 'household', label: 'Бытовая химия', icon: '🧼' },
    { id: 'beauty', label: 'Красота', icon: '💄' },
    { id: 'pets', label: 'Животные', icon: '🐱' },
    { id: 'pharmacy', label: 'Аптека', icon: '💊' },
    { id: 'electronics', label: 'Электроника', icon: '🔌' },
    { id: 'clothes', label: 'Одежда', icon: '👕' },
    { id: 'other', label: 'Разное', icon: '📦' },
];

const UNITS = ['шт', 'кг', 'г', 'л', 'мл', 'упак.'];

const ShoppingListDesktop: React.FC<ShoppingListProps> = ({
    items, setItems, settings, members, onMoveToPantry, onSendToTelegram
}) => {
  const [inputValue, setInputValue] = useState('');
  const [amountValue, setAmountValue] = useState(1);
  const [unitValue, setUnitValue] = useState('шт');
  const [selectedCategoryId, setSelectedCategoryId] = useState('other');
  const [searchQuery, setSearchQuery] = useState('');

  // Editing State
  const [editingItem, setEditingItem] = useState<ShoppingItem | null>(null);

  const { familyId, user } = useAuth();
  const isDarkMode = settings.theme === 'dark';

  // Smart Category Detection
  useEffect(() => {
      if (inputValue.trim() && !editingItem) {
          const detected = detectProductCategory(inputValue);
          if (detected !== 'other') {
              setSelectedCategoryId(detected);
          }
      }
  }, [inputValue, editingItem]);

  const handleSaveItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim()) return;

    const cleanTitle = inputValue.trim();

    if (editingItem) {
        // Update existing item explicitly
        const updatedItem = {
            ...editingItem,
            title: cleanTitle,
            amount: String(amountValue),
            unit: unitValue as any,
            category: selectedCategoryId
        };
        setItems(prev => prev.map(i => i.id === editingItem.id ? updatedItem : i));
        if (familyId) await updateItem(familyId, 'shopping', editingItem.id, updatedItem);
        setEditingItem(null);
    } else {
        // Check for duplicates (active or completed)
        const existingItem = items.find(i => i.title.toLowerCase() === cleanTitle.toLowerCase());

        if (existingItem) {
            // Merge logic
            // Parse existing amount. Handle simple numbers. If complex string, default to 0 and just append.
            const currentAmount = parseFloat(existingItem.amount || '0') || 0;
            const newAmount = currentAmount + amountValue;

            const updatedItem: ShoppingItem = {
                ...existingItem,
                amount: String(newAmount), // Update amount
                unit: unitValue as any, // Update unit to latest choice
                completed: false, // Bring back to active
                category: selectedCategoryId !== 'other' ? selectedCategoryId : existingItem.category // Update category if new one is better
            };

            setItems(prev => prev.map(i => i.id === existingItem.id ? updatedItem : i));
            if (familyId) await updateItem(familyId, 'shopping', existingItem.id, updatedItem);

            toast.success(`Количество обновлено: ${cleanTitle}`);
        } else {
            // Create new
            const newItem: ShoppingItem = {
              id: Date.now().toString(),
              title: cleanTitle,
              category: selectedCategoryId,
              amount: String(amountValue),
              unit: unitValue as any,
              completed: false,
              memberId: user?.uid || 'user',
              priority: 'medium'
            };
            setItems(prev => [newItem, ...prev]);
            if (familyId) await addItem(familyId, 'shopping', newItem);
        }
    }

    setInputValue('');
    setAmountValue(1);
    setUnitValue('шт');
    setSelectedCategoryId('other');
  };

  const handleEditClick = (item: ShoppingItem) => {
      setEditingItem(item);
      setInputValue(item.title);
      setAmountValue(parseFloat(item.amount || '1'));
      setUnitValue(item.unit);
      setSelectedCategoryId(item.category);
  };

  const cancelEdit = () => {
      setEditingItem(null);
      setInputValue('');
      setAmountValue(1);
      setUnitValue('шт');
      setSelectedCategoryId('other');
  };

  const toggleComplete = async (item: ShoppingItem) => {
    const updated = { ...item, completed: !item.completed };
    setItems(prev => prev.map(i => i.id === item.id ? updated : i));
    if (familyId) await updateItem(familyId, 'shopping', item.id, { completed: updated.completed });
  };

  const handleDeleteItem = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation(); // Prevent edit click
    setItems(prev => prev.filter(item => item.id !== id));
    if (familyId) await deleteItem(familyId, 'shopping', id);
    if (editingItem?.id === id) cancelEdit();
  };

  const clearCompleted = async () => {
    const completedIds = items.filter(i => i.completed).map(i => i.id);

    if (completedIds.length === 0) {
        toast.info("Нет купленных товаров для удаления");
        return;
    }

    if (window.confirm(`Вы точно хотите удалить ${completedIds.length} купленных товаров?`)) {
        // Optimistic update
        setItems(prev => prev.filter(item => !item.completed));

        if (familyId) {
            try {
                await deleteItemsBatch(familyId, 'shopping', completedIds);
                toast.success("Список очищен");
            } catch (e) {
                console.error(e);
                toast.error("Ошибка при удалении из базы");
            }
        } else {
            toast.success("Список очищен");
        }
    }
  };

  const handleTelegramClick = () => {
      if (!settings.telegramBotToken || !settings.telegramChatId) {
          toast.error("Пожалуйста, настройте Telegram-бота в настройках", {
              description: "Нужен токен бота и ID чата"
          });
          return;
      }
      // Send active items (not completed)
      onSendToTelegram(items.filter(i => !i.completed));
  };

  const filteredItems: ShoppingItem[] = items.filter(item => 
    item.title.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const activeItems: ShoppingItem[] = filteredItems.filter(i => !i.completed);
  const completedItems: ShoppingItem[] = filteredItems.filter(i => i.completed);

  const groupedActiveItems = useMemo(() => {
    return activeItems.reduce<Record<string, ShoppingItem[]>>((groups, item) => {
      // Map ID to Label for grouping display
      const cat = AISLES.find(a => a.id === item.category);
      const catLabel = cat ? cat.label : 'Разное';

      if (!groups[catLabel]) groups[catLabel] = [];
      groups[catLabel].push(item);
      return groups;
    }, {});
  }, [activeItems]);

  const progress = items.length ? Math.round((completedItems.length / items.length) * 100) : 0;

  return (
    <div className={`flex h-full w-full transition-colors duration-500 font-sans ${isDarkMode ? 'bg-[#0A0A0C] text-white' : 'bg-[#F4F7FB] text-[#1C1C1E]'} overflow-hidden`}>

      {/* Sidebar */}
      <aside className="hidden lg:flex flex-col w-80 bg-[#FFFFFF] dark:bg-[#161618] border-r border-black/5 dark:border-white/5 p-8 h-full overflow-y-auto custom-scrollbar shrink-0">

        <div className="space-y-8 mt-4">
          <div className="space-y-3">
            <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-widest ml-1">Поиск</p>
            <div className="relative">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
              <input 
                type="text"
                placeholder="Найти продукт..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full bg-[#F8F9FB] dark:bg-white/5 border-none rounded-2xl py-3 pl-11 pr-4 text-sm font-bold focus:ring-2 focus:ring-blue-500/50 outline-none transition-all dark:text-white"
              />
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center">
                <p className="text-[10px] font-black text-gray-400 dark:text-gray-500 uppercase tracking-widest ml-1">
                    {editingItem ? 'Редактирование' : 'Новый товар'}
                </p>
                {editingItem && (
                    <button onClick={cancelEdit} className="text-gray-400 hover:text-blue-500"><X size={14}/></button>
                )}
            </div>

            <form onSubmit={handleSaveItem} className="space-y-4">
              <input 
                type="text"
                value={inputValue}
                onChange={(e) => setInputValue(e.target.value)}
                placeholder="Название продукта..."
                className="w-full bg-[#F8F9FB] dark:bg-white/5 border border-transparent focus:border-blue-500/20 rounded-2xl py-3.5 px-4 text-sm font-bold outline-none transition-all dark:text-white"
              />

              <div className="grid grid-cols-2 gap-2">
                <input 
                  type="number"
                  min="0.1"
                  step="0.1"
                  value={amountValue}
                  onChange={(e) => setAmountValue(parseFloat(e.target.value) || 0)}
                  placeholder="Кол-во"
                  className="w-full bg-[#F8F9FB] dark:bg-white/5 border border-transparent focus:border-blue-500/20 rounded-xl py-3 px-4 text-sm font-bold outline-none transition-all dark:text-white"
                />
                <select 
                  value={unitValue}
                  onChange={(e) => setUnitValue(e.target.value)}
                  className="bg-[#F8F9FB] dark:bg-white/5 border-none rounded-xl py-3 px-3 text-xs font-black uppercase outline-none cursor-pointer dark:text-white"
                >
                  {UNITS.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>

              <select 
                value={selectedCategoryId}
                onChange={(e) => setSelectedCategoryId(e.target.value)}
                className="w-full bg-[#F8F9FB] dark:bg-white/5 border-none rounded-2xl py-3.5 px-4 text-xs font-black uppercase tracking-wider outline-none cursor-pointer dark:text-white"
              >
                {AISLES.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
              </select>

              <button 
                type="submit"
                disabled={!inputValue.trim()}
                className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-2xl font-black text-xs shadow-lg shadow-blue-600/20 active:scale-95 transition-all flex items-center justify-center gap-2 disabled:opacity-50"
              >
                <Plus size={18} strokeWidth={3} />
                {editingItem ? 'СОХРАНИТЬ' : 'ДОБАВИТЬ'}
              </button>
            </form>
          </div>

          <div className="space-y-2 pt-4 border-t border-black/5 dark:border-white/5">
            <button 
              onClick={clearCompleted}
              className="w-full flex items-center gap-3 px-4 py-3 rounded-2xl text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-all font-bold text-sm"
            >
              <Trash2 size={18} />
              Очистить купленное
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 p-8 lg:p-16 overflow-y-auto no-scrollbar">
        <div className="max-w-6xl mx-auto space-y-12">

          {/* Header Stats & Share */}
          <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
            <div className="animate-in fade-in slide-in-from-left-4 duration-500">
              <div className="flex items-center gap-4 mb-2">
                <h2 className="text-4xl font-black tracking-tight leading-none">Прогресс {progress}%</h2>
                <button 
                  onClick={handleTelegramClick}
                  disabled={items.length === 0}
                  className="flex items-center gap-2 bg-[#229ED9] hover:bg-[#229ED9]/90 text-white px-4 py-2 rounded-xl text-xs font-black shadow-lg shadow-[#229ED9]/20 transition-all active:scale-95 disabled:opacity-50 disabled:shadow-none"
                >
                  <Send size={14} fill="currentColor" />
                  В TELEGRAM
                </button>
              </div>
              <p className="text-gray-500 dark:text-gray-400 font-bold flex items-center gap-2">
                <Check size={18} className="text-green-500" />
                Осталось купить: {activeItems.length}
              </p>
            </div>

            <div className="flex bg-white dark:bg-[#161618] p-2 rounded-2xl shadow-sm border border-black/5 dark:border-white/5">
              <div className="px-6 py-2 border-r border-black/5 dark:border-white/5 text-center">
                <p className="text-[10px] font-black text-gray-400 uppercase mb-1">Всего</p>
                <p className="text-xl font-black">{items.length}</p>
              </div>
              <div className="px-6 py-2 text-center">
                <p className="text-[10px] font-black text-blue-500 uppercase mb-1">Куплено</p>
                <p className="text-xl font-black text-blue-500">{completedItems.length}</p>
              </div>
            </div>
          </div>

          {/* Grid Layout - Active Items */}
          <div className="grid grid-cols-1 xl:grid-cols-2 gap-x-12 gap-y-10 items-start">
            {Object.keys(groupedActiveItems).length > 0 ? (
              Object.entries(groupedActiveItems).map(([category, catItems]) => (
                <div key={category} className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-500 break-inside-avoid">
                  <div className="flex items-center justify-between px-2">
                    <div className="flex items-center gap-3">
                      <div className="w-1.5 h-6 bg-blue-500 rounded-full"></div>
                      <h3 className="text-xs font-black text-gray-400 dark:text-gray-400 uppercase tracking-widest">
                        {category}
                      </h3>
                    </div>
                    <span className="text-[10px] font-black bg-white dark:bg-white/5 px-2 py-0.5 rounded-lg border border-black/5 dark:border-white/5">{catItems.length} поз.</span>
                  </div>

                  <div className="bg-white dark:bg-[#161618] rounded-[36px] shadow-[0_10px_50px_-15px_rgba(0,0,0,0.04)] dark:shadow-none border border-black/5 dark:border-white/5 overflow-hidden">
                    {catItems.map((item, idx) => (
                        <div 
                        key={item.id}
                        onClick={() => handleEditClick(item)}
                        className={`flex items-center gap-5 p-6 transition-all group hover:bg-gray-50/50 dark:hover:bg-white/[0.02] cursor-pointer ${idx !== catItems.length - 1 ? 'border-b border-black/[0.03] dark:border-white/[0.03]' : ''}`}
                        >
                        <button 
                            onClick={(e) => { e.stopPropagation(); toggleComplete(item); }}
                            className={`transition-all active:scale-75 text-gray-200 dark:text-gray-700 hover:text-blue-500`}
                        >
                            <Circle size={36} strokeWidth={1} />
                        </button>

                        <div className="flex-1 flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                            <div className="flex items-center gap-2">
                                <span className={`text-lg font-bold transition-all text-gray-800 dark:text-gray-200`}>
                                    {item.title}
                                </span>
                            </div>

                            <div className={`flex items-center gap-1.5 px-3 py-1 rounded-xl text-xs font-black self-start sm:self-auto transition-colors bg-blue-50 dark:bg-blue-500/10 text-blue-600 dark:text-blue-400`}>
                                <span>{item.amount}</span>
                                <span>{item.unit}</span>
                            </div>
                        </div>

                        <button 
                            onClick={(e) => handleDeleteItem(e, item.id)}
                            className="opacity-0 group-hover:opacity-100 p-2.5 text-gray-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 rounded-xl transition-all"
                        >
                            <Trash2 size={20} />
                        </button>
                        </div>
                    ))}
                  </div>
                </div>
              ))
            ) : (
                items.length === 0 && (
                    <div className="col-span-full flex flex-col items-center justify-center py-32 text-center">
                        <div className="w-24 h-24 bg-white dark:bg-[#161618] rounded-[40px] flex items-center justify-center shadow-2xl mb-8 border border-black/5 dark:border-white/5">
                        <ShoppingBag size={48} strokeWidth={1} className="text-blue-500 opacity-50" />
                        </div>
                        <p className="text-2xl font-black italic opacity-20">Список покупок пуст</p>
                        <p className="text-sm font-bold text-gray-400 mt-2">Добавьте нужные продукты слева</p>
                    </div>
                )
            )}
          </div>

          {/* Completed Items Section */}
          {completedItems.length > 0 && (
              <div className="pt-10 border-t border-black/5 dark:border-white/5">
                  <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-6 px-2">Куплено ({completedItems.length})</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 opacity-60">
                      {completedItems.map(item => (
                          <div key={item.id} className="bg-white dark:bg-[#161618] p-4 rounded-2xl flex items-center gap-3 border border-black/5 dark:border-white/5">
                              <button onClick={() => toggleComplete(item)} className="text-green-500">
                                  <CheckCircle2 size={24} />
                              </button>
                              <span className="text-sm font-bold text-gray-400 line-through flex-1">{item.title}</span>
                              <button onClick={(e) => handleDeleteItem(e, item.id)} className="text-gray-300 hover:text-red-500"><Trash2 size={16}/></button>
                          </div>
                      ))}
                  </div>
              </div>
          )}

        </div>
      </main>
    </div>
  );
};

export default ShoppingListDesktop;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Plus, Trash2, Check, Share, X, ScanLine, ShoppingBag, Loader2, Play, Edit2, ChevronLeft, Mic, BrainCircuit, ArrowRight } from 'lucide-react';
import { ShoppingItem, AppSettings, FamilyMember } from '../types';
import { useAuth } from '../contexts/AuthContext';
import { addItem, updateItem, deleteItem, addItemsBatch } from '../utils/db';
import { searchOnlineDatabase } from '../utils/barcodeLookup';
import { detectProductCategory } from '../utils/categorizer';
import { GoogleGenAI } from "@google/genai";
import ShoppingListDesktop from './ShoppingListDesktop';
import { toast } from 'sonner';

interface ShoppingListProps {
  items: ShoppingItem[];
  setItems: React.Dispatch<React.SetStateAction<ShoppingItem[]>>;
  settings: AppSettings;
  members: FamilyMember[];
  onCompletePurchase?: () => void;
  onMoveToPantry: (item: ShoppingItem) => Promise<void>;
  onSendToTelegram: (items: ShoppingItem[]) => Promise<boolean>;
}

const AISLES = [
    { id: 'produce', label: 'Овощи/Фрукты', icon: '🥦' },
    { id: 'dairy', label: 'Молочка', icon: '🥛' },
    { id: 'meat', label: 'Мясо/Рыба', icon: '🥩' },
    { id: 'bakery', label: 'Хлеб', icon: '🍞' },
    { id: 'grocery', label: 'Бакалея', icon: '🍝' },
    { id: 'drinks', label: 'Напитки', icon: '🧃' },
    { id: 'sweets', label: 'Сладости', icon: '🍫' },
    { id: 'frozen', label: 'Заморозка', icon: '🧊' },
    { id: 'household', label: 'Быт. химия', icon: '🧼' },
    { id: 'beauty', label: 'Красота', icon: '💄' },
    { id: 'pets', label: 'Животные', icon: '🐱' },
    { id: 'pharmacy', label: 'Аптека', icon: '💊' },
    { id: 'electronics', label: 'Электроника', icon: '🔌' },
    { id: 'clothes', label: 'Одежда', icon: '👕' },
    { id: 'other', label: 'Разное', icon: '📦' },
];

const UNITS = ['шт', 'кг', 'уп', 'л'] as const;

const ShoppingListMobile: React.FC<ShoppingListProps> = ({ 
  items, setItems, settings, members, onMoveToPantry, onSendToTelegram 
}) => {
  const [isAddModalOpen, setIsAddModalOpen] = useState(false);

  // Form State
  const [editingItem, setEditingItem] = useState<ShoppingItem | null>(null);
  const [newItemTitle, setNewItemTitle] = useState('');
  const [newItemAmount, setNewItemAmount] = useState('');
  const [newItemUnit, setNewItemUnit] = useState<typeof UNITS[number]>('шт');
  const [selectedAisle, setSelectedAisle] = useState('other');

  const [isScanning, setIsScanning] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [isProcessingAI, setIsProcessingAI] = useState(false);
  const [showAllCategories, setShowAllCategories] = useState(false);
  const [shopMode, setShopMode] = useState(false);

  const { familyId, user } = useAuth();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const titleInputRef = useRef<HTMLInputElement>(null);
  const recognitionRef = useRef<any>(null);

  const apiKey = settings.geminiApiKey || process.env.API_KEY;

  // Computed properties for categories in modal
  const sortedAisles = AISLES;
  const visibleAisles = showAllCategories ? sortedAisles : sortedAisles.slice(0, 12);

  // Wake Lock for Shop Mode
  useEffect(() => {
    let wakeLock: any = null;
    const requestWakeLock = async () => {
      if ('wakeLock' in navigator && shopMode) {
        try { 
            wakeLock = await (navigator as any).wakeLock.request('screen'); 
        } catch (err) {
            console.warn('Wake Lock error:', err);
        }
      }
    };

    if (shopMode) requestWakeLock();
    return () => { if (wakeLock) wakeLock.release(); };
  }, [shopMode]);

  // Auto-categorization effect for manual input
  useEffect(() => {
      if (newItemTitle.trim() && !editingItem) {
          const detected = detectProductCategory(newItemTitle);
          if (detected !== 'other') {
              setSelectedAisle(detected);
          }
      }
  }, [newItemTitle, editingItem]);

  // Group items by category (Aisle)
  const groupedItems = useMemo(() => {
      const groups: Record<string, ShoppingItem[]> = {};
      AISLES.forEach(a => groups[a.id] = []);

      items.forEach(item => {
          const cat = item.category || 'other';
          if (!groups[cat]) groups[cat] = [];
          groups[cat].push(item);
      });

      return groups;
  }, [items]);

  const activeCount = items.filter(i => !i.completed).length;

  const handleOpenAdd = () => {
      setEditingItem(null);
      setNewItemTitle('');
      setNewItemAmount('');
      setNewItemUnit('шт');
      setSelectedAisle('other');
      setIsAddModalOpen(true);
      setTimeout(() => titleInputRef.current?.focus(), 100);
  };

  const handleOpenEdit = (item: ShoppingItem) => {
      setEditingItem(item);
      setNewItemTitle(item.title);
      setNewItemAmount(item.amount || '');
      setNewItemUnit(item.unit as any || 'шт');
      setSelectedAisle(item.category || 'other');
      setIsAddModalOpen(true);
  };

  const handleSaveItem = async () => {
      if (!newItemTitle.trim()) return;
      const cleanTitle = newItemTitle.trim();

      if (editingItem) {
          // Update Existing
          const updatedItem: ShoppingItem = {
              ...editingItem,
              title: cleanTitle,
              amount: newItemAmount,
              unit: newItemUnit,
              category: selectedAisle,
          };

          setItems(prev => prev.map(i => i.id === editingItem.id ? updatedItem : i));
          if (familyId) await updateItem(familyId, 'shopping', editingItem.id, updatedItem);

          setIsAddModalOpen(false);
          setEditingItem(null);
      } else {
          // Check for duplicate (active or completed)
          const existingItem = items.find(i => i.title.toLowerCase() === cleanTitle.toLowerCase());

          if (existingItem) {
              // Merge
              const currentAmount = parseFloat(existingItem.amount || '0') || 0;
              const addedAmount = parseFloat(newItemAmount) || 1; // Default to 1 if user didn't specify amount but re-added item
              const newAmount = currentAmount + addedAmount;

              const updatedItem: ShoppingItem = {
                  ...existingItem,
                  amount: String(newAmount),
                  unit: newItemUnit, // Use new unit if different
                  completed: false, // Reactivate
                  category: selectedAisle !== 'other' ? selectedAisle : existingItem.category
              };

              setItems(prev => prev.map(i => i.id === existingItem.id ? updatedItem : i));
              if (familyId) await updateItem(familyId, 'shopping', existingItem.id, updatedItem);

              toast.success(`Количество увеличено: ${cleanTitle}`);
          } else {
              // Create New
              const newItem: ShoppingItem = {
                  id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
                  title: cleanTitle,
                  amount: newItemAmount,
                  unit: newItemUnit,
                  category: selectedAisle,
                  completed: false,
                  memberId: user?.uid || 'user',
                  priority: 'medium'
              };

              setItems(prev => [...prev, newItem]);
              if (familyId) await addItem(familyId, 'shopping', newItem);
          }

          setNewItemTitle('');
          setNewItemAmount('');
          setNewItemUnit('шт');
          setSelectedAisle('other');

          // Keep modal open or focus for next item if creating multiple
          titleInputRef.current?.focus();
      }
  };

  const handleToggle = async (item: ShoppingItem) => {
      const updated = { ...item, completed: !item.completed };
      setItems(items.map(i => i.id === item.id ? updated : i));
      if (familyId) await updateItem(familyId, 'shopping', item.id, { completed: updated.completed });
  };

  const handleDelete = async (id: string) => {
      setItems(items.filter(i => i.id !== id));
      if (familyId) await deleteItem(familyId, 'shopping', id);
      if (editingItem?.id === id) setIsAddModalOpen(false);
  };

  const handleBarcodeScan = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setIsScanning(true);
      try {
          if ('BarcodeDetector' in window) {
              const BarcodeDetector = (window as any).BarcodeDetector;
              const detector = new BarcodeDetector({ formats: ['ean_13', 'ean_8'] });
              const bitmap = await createImageBitmap(file);
              const barcodes = await detector.detect(bitmap);

              if (barcodes.length > 0) {
                  const code = barcodes[0].rawValue;
                  const product = await searchOnlineDatabase(code);
                  if (product) {
                      setNewItemTitle(product.title);
                      setNewItemAmount(product.amount);
                      setNewItemUnit(product.unit);
                      setSelectedAisle(product.category);
                  } else {
                      alert('Товар не найден в базе, введите название вручную');
                  }
              } else {
                  alert('Штрихкод не распознан');
              }
          } else {
              alert('Ваш браузер не поддерживает сканирование штрихкодов');
          }
      } catch (err) {
          console.error(err);
          alert('Ошибка сканирования');
      } finally {
          setIsScanning(false);
          if (fileInputRef.current) fileInputRef.current.value = '';
      }
  };

  // AI Voice Processing
  const processVoiceInputWithGemini = async (text: string) => {
      if (!apiKey) {
          alert('API Key не настроен в настройках приложения');
          return;
      }

      setIsProcessingAI(true);
      try {
          const ai = new GoogleGenAI({ apiKey });
          const prompt = `
            Analyze the following shopping list request in Russian: "${text}".
            Return a pure JSON array of objects. 
            Each object must have:
            - "title": string (product name in Russian, capitalized)
            - "amount": string (quantity number, default "1" if not specified)
            - "unit": string (one of: "шт", "кг", "уп", "л". Detect based on context, e.g., milk -> л, potatoes -> кг, eggs -> шт. Default to "шт")
            - "category": string (one of: "produce", "dairy", "meat", "bakery", "grocery", "drinks", "sweets", "frozen", "household", "beauty", "pets", "pharmacy", "electronics", "clothes", "other")

            Example input: "купи два молока хлеб и десяток яиц"
            Example output: [{"title": "Молоко", "amount": "2", "unit": "л", "category": "dairy"}, {"title": "Хлеб", "amount": "1", "unit": "шт", "category": "bakery"}, {"title": "Яйца", "amount": "10", "unit": "шт", "category": "dairy"}]
          `;

          const response = await ai.models.generateContent({
              model: "gemini-3-flash-preview",
              contents: prompt,
              config: { responseMimeType: "application/json" }
          });

          const jsonString = response.text || "[]";
          const parsedItems = JSON.parse(jsonString);

          if (Array.isArray(parsedItems) && parsedItems.length > 0) {
              const newItems: ShoppingItem[] = parsedItems.map((p: any) => ({
                  id: Date.now().toString() + Math.random().toString(36).substr(2, 5),
                  title: p.title,
                  amount: p.amount,
                  unit: p.unit,
                  category: p.category,
                  completed: false,
                  memberId: user?.uid || 'user',
                  priority: 'medium'
              }));

              // Batch add (Note: currently doesn't check duplicates for voice batch, simple append)
              // Ideally, this should also loop through handleSaveItem logic for merge, but batch is more efficient.
              setItems(prev => [...prev, ...newItems]);
              if (familyId) {
                  await addItemsBatch(familyId, 'shopping', newItems);
              }
          }

      } catch (err) {
          console.error("Gemini Error:", err);
          alert("Не удалось распознать товары. Попробуйте еще раз.");
      } finally {
          setIsProcessingAI(false);
      }
  };

  const startListening = () => {
      const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (!SR) { alert("Голосовой ввод не поддерживается"); return; }

      if (isListening) {
          recognitionRef.current?.stop();
          setIsListening(false);
          return;
      }

      const r = new SR();
      recognitionRef.current = r;
      r.lang = 'ru-RU';
      r.interimResults = false;

      r.onstart = () => setIsListening(true);
      r.onend = () => { if(!isProcessingAI) setIsListening(false); };

      r.onresult = (e: any) => {
          const text = e.results[0][0].transcript;
          if (text) {
              setIsListening(false);
              processVoiceInputWithGemini(text);
          }
      };

      r.onerror = (e: any) => {
          console.error(e);
          setIsListening(false);
      };

      r.start();
  };

  // Shop Mode Overlay
  if (shopMode) {
      return (
        <div className="fixed inset-0 z-[2000] bg-[#F2F2F7] dark:bg-black flex flex-col overflow-hidden">
            {/* Shop Mode Header */}
            <div className="px-6 py-4 bg-white dark:bg-[#1C1C1E] border-b border-gray-100 dark:border-white/5 flex items-center justify-between shrink-0">
                <button 
                    onClick={() => setShopMode(false)}
                    className="flex items-center gap-2 text-blue-500 font-bold text-sm active:opacity-70"
                >
                    <ChevronLeft size={20} />
                    Назад
                </button>
                <h3 className="font-black text-lg text-[#1C1C1E] dark:text-white uppercase tracking-widest">В магазине</h3>
                <div className="w-8" />
            </div>

            {/* Shop Mode Content */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
                {activeCount === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-center opacity-40">
                        <Check size={64} className="text-green-500 mb-4" />
                        <p className="text-lg font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest">Все куплено!</p>
                    </div>
                ) : (
                    AISLES.map(aisle => {
                        const aisleItems = groupedItems[aisle.id] || [];
                        const activeItems = aisleItems.filter(i => !i.completed);
                        if (activeItems.length === 0) return null;

                        return (
                            <div key={aisle.id} className="bg-white dark:bg-[#1C1C1E] p-5 rounded-[2.5rem] shadow-sm border border-gray-100 dark:border-white/5">
                                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4 pl-2 flex items-center gap-2">
                                    <span>{aisle.icon}</span> {aisle.label}
                                </h3>
                                <div className="space-y-3">
                                    <AnimatePresence>
                                        {activeItems.map(item => (
                                            <motion.div 
                                                key={item.id}
                                                layout
                                                initial={{ opacity: 0, scale: 0.95 }}
                                                animate={{ opacity: 1, scale: 1 }}
                                                exit={{ opacity: 0, scale: 0.95 }}
                                                transition={{ duration: 0.2 }}
                                                className="flex items-center justify-between p-4 bg-blue-50 dark:bg-blue-900/10 rounded-2xl active:scale-[0.98] transition-transform cursor-pointer border border-blue-100 dark:border-white/5"
                                                onClick={() => handleToggle(item)}
                                            >
                                                <div className="flex items-center gap-4 overflow-hidden flex-1">
                                                    <div className="w-8 h-8 rounded-full border-2 border-blue-500 flex items-center justify-center shrink-0">
                                                    </div>
                                                    <div className="min-w-0">
                                                        <span className="text-lg font-bold text-[#1C1C1E] dark:text-white truncate block leading-tight">{item.title}</span>
                                                        {(item.amount || item.unit) && (
                                                            <span className="text-sm font-bold text-gray-500 dark:text-gray-400">
                                                                {item.amount} {item.unit}
                                                            </span>
                                                        )}
                                                    </div>
                                                </div>
                                            </motion.div>
                                        ))}
                                    </AnimatePresence>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
        </div>
      );
  }

  // Standard Mobile Mode
  return (
    <div className="space-y-4 h-full flex flex-col relative">
        {/* Loading Overlay for AI */}
        <AnimatePresence>
            {(isListening || isProcessingAI) && (
                <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="absolute inset-0 z-50 bg-white/80 dark:bg-black/80 backdrop-blur-sm flex flex-col items-center justify-center rounded-[2.5rem]">
                    <div className="bg-white dark:bg-[#2C2C2E] p-8 rounded-[3rem] shadow-2xl flex flex-col items-center gap-4 border dark:border-white/10">
                        {isListening ? (
                            <div className="relative">
                                <div className="absolute inset-0 bg-red-500/30 rounded-full animate-ping blur-md" />
                                <Mic size={48} className="text-red-500 relative z-10" />
                            </div>
                        ) : (
                            <BrainCircuit size={48} className="text-purple-500 animate-pulse" />
                        )}
                        <span className="font-black text-lg text-[#1C1C1E] dark:text-white">
                            {isListening ? 'Слушаю...' : 'Анализирую список...'}
                        </span>
                    </div>
                </motion.div>
            )}
        </AnimatePresence>

        {/* Header Actions */}
        <div className="flex gap-2 shrink-0 items-stretch">
            <button 
                onClick={handleOpenAdd}
                className="flex-[2] bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] shadow-sm flex items-center justify-center gap-2 text-[#1C1C1E] dark:text-white font-black uppercase text-xs tracking-widest active:scale-95 transition-transform border border-transparent dark:border-white/5"
            >
                <Plus size={18} strokeWidth={3} /> Добавить
            </button>

            <button 
                onClick={startListening}
                className={`flex-1 p-4 rounded-[2rem] shadow-sm flex items-center justify-center transition-all bg-white dark:bg-[#1C1C1E] border dark:border-white/5 active:scale-95 ${isListening ? 'text-red-500 bg-red-50 dark:bg-red-900/20' : 'text-blue-500'}`}
            >
                <Mic size={20} />
            </button>

            <button 
                onClick={() => setShopMode(true)}
                className="p-4 rounded-[2rem] shadow-sm flex items-center justify-center gap-2 font-black uppercase text-xs tracking-widest transition-all bg-blue-500 text-white shadow-blue-500/20 active:scale-95"
            >
                <Play size={18} fill="currentColor" />
            </button>

            <button 
                onClick={() => onSendToTelegram(items.filter(i => !i.completed))}
                disabled={activeCount === 0}
                className="bg-[#1C1C1E] dark:bg-white text-white dark:text-black p-4 rounded-[2rem] shadow-lg active:scale-95 transition-transform disabled:opacity-50 disabled:shadow-none"
            >
                <Share size={20} />
            </button>
        </div>

        {/* Lists Container */}
        <div className="flex-1 overflow-y-auto no-scrollbar space-y-4 pb-20">
            {activeCount === 0 && items.length === 0 && (
                <div className="flex flex-col items-center justify-center py-12 text-center opacity-40">
                    <ShoppingBag size={48} className="mb-4 text-gray-300 dark:text-gray-600" />
                    <p className="text-sm font-bold text-gray-400 dark:text-gray-500 uppercase tracking-widest">Список пуст</p>
                </div>
            )}

            {AISLES.map(aisle => {
                const aisleItems = groupedItems[aisle.id] || [];
                const activeItems = aisleItems.filter(i => !i.completed);
                if (activeItems.length === 0) return null;

                return (
                    <div key={aisle.id} className="bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] shadow-sm border border-gray-100 dark:border-white/5">
                        <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 pl-2 flex items-center gap-2">
                            <span>{aisle.icon}</span> {aisle.label}
                        </h3>
                        <div className="space-y-2">
                            <AnimatePresence>
                                {activeItems.map(item => (
                                    <motion.div 
                                        key={item.id}
                                        layout
                                        initial={{ opacity: 0, scale: 0.95 }}
                                        animate={{ opacity: 1, scale: 1 }}
                                        exit={{ opacity: 0, scale: 0.95 }}
                                        transition={{ duration: 0.2 }}
                                        onClick={() => handleOpenEdit(item)}
                                        className="flex items-center justify-between p-3 bg-gray-50 dark:bg-[#2C2C2E] rounded-2xl group cursor-pointer active:scale-[0.99] transition-transform"
                                    >
                                        <div className="flex items-center gap-3 overflow-hidden flex-1">
                                            <button 
                                                onClick={(e) => { e.stopPropagation(); handleToggle(item); }}
                                                className="w-6 h-6 rounded-full border-2 border-gray-300 dark:border-gray-600 flex items-center justify-center shrink-0 hover:border-green-500 hover:text-green-500 transition-colors"
                                            >
                                                {item.completed && <Check size={14} />}
                                            </button>
                                            <div className="min-w-0">
                                                <span className="text-sm font-bold text-[#1C1C1E] dark:text-white truncate block">{item.title}</span>
                                                {(item.amount || item.unit) && (
                                                    <span className="text-[10px] font-bold text-gray-400">
                                                        {item.amount} {item.unit}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                            <div className="p-2 text-gray-300"><Edit2 size={14}/></div>
                                        </div>
                                    </motion.div>
                                ))}
                            </AnimatePresence>
                        </div>
                    </div>
                );
            })}

            {/* Completed Items Section */}
            {items.some(i => i.completed) && (
                <div className="pt-4 border-t border-gray-200 dark:border-white/10 mt-4">
                    <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-3 pl-2">Куплено</h3>
                    <div className="space-y-2 opacity-60">
                        {items.filter(i => i.completed).map(item => (
                            <div key={item.id} className="flex items-center justify-between p-3 bg-gray-100 dark:bg-[#2C2C2E] rounded-2xl">
                                <div className="flex items-center gap-3 overflow-hidden flex-1">
                                    <button onClick={() => handleToggle(item)} className="w-6 h-6 rounded-full bg-green-500 text-white flex items-center justify-center shrink-0">
                                        <Check size={14} />
                                    </button>
                                    <span className="text-sm font-bold text-gray-500 dark:text-gray-400 line-through decoration-gray-400">{item.title}</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <button onClick={() => onMoveToPantry(item)} className="p-1.5 bg-blue-100 dark:bg-blue-900/30 text-blue-500 rounded-lg" title="В кладовку"><ArrowRight size={14}/></button>
                                    <button onClick={() => handleDelete(item.id)} className="p-1.5 text-gray-400 hover:text-red-500"><Trash2 size={14}/></button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}
        </div>

        {/* Add/Edit Item Modal */}
        <AnimatePresence>
            {isAddModalOpen && (
                <div className="fixed inset-0 z-[1200] flex items-end md:items-center justify-center p-0 md:p-4">
                    <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={() => setIsAddModalOpen(false)} className="absolute inset-0 bg-black/40 backdrop-blur-md" />
                    <motion.div 
                        initial={{y:'100%'}} animate={{y:0}} exit={{y:'100%'}}
                        className="relative bg-[#F2F2F7] dark:bg-black w-full max-w-lg md:rounded-[3rem] rounded-t-[3rem] shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
                        onClick={e => e.stopPropagation()}
                    >
                        <div className="bg-white dark:bg-[#1C1C1E] p-6 flex justify-between items-center border-b border-gray-100 dark:border-white/5">
                            <h3 className="text-xl font-black text-[#1C1C1E] dark:text-white">
                                {editingItem ? 'Редактировать' : 'Добавить покупку'}
                            </h3>
                            <button onClick={() => setIsAddModalOpen(false)} className="w-10 h-10 bg-gray-100 dark:bg-[#2C2C2E] rounded-full flex items-center justify-center text-gray-500 dark:text-gray-300"><X size={20}/></button>
                        </div>

                        <div className="p-6 space-y-6 overflow-y-auto no-scrollbar">
                            <div className="flex flex-col gap-4">
                                <div className="relative">
                                    <input 
                                        ref={titleInputRef}
                                        type="text" 
                                        placeholder="Что купить?" 
                                        value={newItemTitle} 
                                        onChange={e => setNewItemTitle(e.target.value)} 
                                        onKeyDown={e => e.key === 'Enter' && handleSaveItem()}
                                        className="w-full bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] font-bold text-lg outline-none text-[#1C1C1E] dark:text-white pr-14 shadow-sm"
                                    />
                                    <div className="absolute right-2 top-2 bottom-2 flex gap-2">
                                        <button 
                                            onClick={() => fileInputRef.current?.click()}
                                            className="aspect-square h-full flex items-center justify-center bg-gray-100 dark:bg-[#2C2C2E] rounded-full text-gray-500 hover:text-blue-500 transition-colors"
                                        >
                                            {isScanning ? <Loader2 size={20} className="animate-spin"/> : <ScanLine size={20}/>}
                                        </button>
                                    </div>
                                    <input type="file" accept="image/*" ref={fileInputRef} className="hidden" onChange={handleBarcodeScan} />
                                </div>

                                {/* Width 25% for Amount, rest for Units */}
                                <div className="flex gap-3 h-16">
                                    <input 
                                        type="text" 
                                        inputMode="decimal"
                                        placeholder="К-во" 
                                        value={newItemAmount} 
                                        onChange={e => setNewItemAmount(e.target.value)} 
                                        onKeyDown={e => e.key === 'Enter' && handleSaveItem()}
                                        className="w-28 bg-white dark:bg-[#1C1C1E] rounded-[2rem] font-bold text-2xl outline-none text-center text-[#1C1C1E] dark:text-white shadow-sm h-full"
                                    />
                                    {/* Units Block - Flex Row */}
                                    <div className="flex-1 bg-white dark:bg-[#1C1C1E] p-1.5 rounded-[2rem] shadow-sm flex items-center justify-between gap-1 h-full">
                                        {UNITS.map(u => (
                                            <button 
                                                key={u}
                                                onClick={() => setNewItemUnit(u)}
                                                className={`flex-1 h-full rounded-[1.5rem] text-[10px] font-black uppercase transition-all flex items-center justify-center ${newItemUnit === u ? 'bg-[#F2F2F7] dark:bg-[#2C2C2E] text-black dark:text-white shadow-sm' : 'text-gray-400 hover:text-gray-600'}`}
                                            >
                                                {u}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>

                            <div className="bg-white dark:bg-[#1C1C1E] p-4 rounded-[2rem] shadow-sm">
                                <div className="flex justify-between items-center mb-2 px-1">
                                    <span className="text-[10px] font-black text-gray-400 uppercase block">Категория</span>
                                    {sortedAisles.length > 12 && !showAllCategories && (
                                        <button 
                                            onClick={() => setShowAllCategories(true)} 
                                            className="text-[10px] font-bold text-blue-500 uppercase tracking-widest bg-blue-50 dark:bg-blue-900/30 px-2 py-1 rounded-lg hover:bg-blue-100 transition-colors"
                                        >
                                            Показать все
                                        </button>
                                    )}
                                </div>
                                <div className="grid grid-cols-4 gap-2">
                                    {visibleAisles.map(aisle => (
                                        <button 
                                            key={aisle.id} 
                                            onClick={() => setSelectedAisle(aisle.id)} 
                                            className={`flex flex-col items-center justify-center p-2 rounded-2xl transition-all border ${selectedAisle === aisle.id ? 'bg-blue-50 dark:bg-blue-900/30 border-blue-200 dark:border-blue-800 shadow-sm' : 'border-transparent hover:bg-gray-50 dark:hover:bg-[#2C2C2E]'}`}
                                        >
                                            <span className="text-xl mb-1">{aisle.icon}</span>
                                            <span className={`text-[9px] font-bold text-center leading-none w-full truncate ${selectedAisle === aisle.id ? 'text-blue-700 dark:text-blue-300' : 'text-gray-500 dark:text-gray-400'}`}>{aisle.label}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>
                        </div>

                        <div className="p-6 bg-white dark:bg-[#1C1C1E] border-t border-gray-100 dark:border-white/5 flex flex-col gap-3">
                            <button 
                                onClick={handleSaveItem}
                                disabled={!newItemTitle.trim()}
                                className="w-full bg-blue-500 text-white font-black py-5 rounded-[2rem] uppercase text-xs flex items-center justify-center gap-2 active:scale-95 shadow-xl transition-all disabled:opacity-50 disabled:shadow-none"
                            >
                                <Plus size={18} strokeWidth={3}/> 
                                {editingItem ? 'Сохранить изменения' : 'Добавить'}
                            </button>

                            {editingItem && (
                                <button 
                                    onClick={() => handleDelete(editingItem.id)}
                                    className="w-full bg-red-50 dark:bg-red-900/20 text-red-500 font-black py-4 rounded-[2rem] uppercase text-xs flex items-center justify-center gap-2 active:scale-95 transition-all"
                                >
                                    <Trash2 size={16} /> Удалить
                                </button>
                            )}
                        </div>
                    </motion.div>
                </div>
            )}
        </AnimatePresence>
    </div>
  );
};

const ShoppingList: React.FC<ShoppingListProps> = (props) => {
  const [isDesktop, setIsDesktop] = useState(false);

  useEffect(() => {
    const checkDesktop = () => setIsDesktop(window.innerWidth >= 768);
    checkDesktop();
    window.addEventListener('resize', checkDesktop);
    return () => window.removeEventListener('resize', checkDesktop);
  }, []);

  if (isDesktop) {
      return <ShoppingListDesktop {...props} />;
  }

  return <ShoppingListMobile {...props} />;
};

export default ShoppingList;

