// Генератор реалистичных зарплат (разные суммы каждый месяц)
const generateSalaryData = (): Transaction[] => {
  const transactions: Transaction[] = [];
  const baseSalary = 82000;
  const baseAdvance = 38000;
  const currentYear = new Date().getFullYear();

  [currentYear, currentYear + 1].forEach(year => {
    for (let month = 0; month < 12; month++) {
      // Псевдо-рандом на основе месяца и года для стабильности демо-данных
      const seed = (year * 12) + month;
      const variation = (seed * 167) % 3500; // Колебания +- 3.5к
      const quarterlyBonus = (month + 1) % 3 === 0 ? 12000 + (seed % 5000) : 0;
      const yearEndBonus = month === 11 ? 45000 : 0; 

      const salaryAmount = baseSalary + variation + quarterlyBonus + yearEndBonus;

      let salaryNote = 'Зарплата';
      if (yearEndBonus > 0) salaryNote = 'Зарплата + Годовая премия 🎄';
      else if (quarterlyBonus > 0) salaryNote = 'Зарплата + Квартальная премия 💰';

      // Основная часть (10-го числа)
      transactions.push({
        id: `gen_${year}_sal_${month}`,
        amount: salaryAmount,
        type: 'income',
        category: 'salary',
        memberId: 'm1',
        note: salaryNote,
        date: new Date(year, month, 10, 10, 0, 0).toISOString()
      });

      // Аванс (25-го числа)
      const advanceVariation = (seed * 71) % 1000;
      transactions.push({
        id: `gen_${year}_adv_${month}`,
        amount: baseAdvance + advanceVariation,
        type: 'income',
        category: 'salary',
        memberId: 'm1',
        note: 'Аванс 💸',
        date: new Date(year, month, 25, 10, 0, 0).toISOString()
      });
    }
  });
  return transactions;
};

