// Helper to generate full salary data with realistic variations for 2 years
const generateSalaryData = (): Transaction[] => {
  const transactions: Transaction[] = [];
  const baseSalary = 82000;
  const baseAdvance = 38000;
  const startYear = new Date().getFullYear() - 1; // Start from last year for history

  [startYear, startYear + 1, startYear + 2].forEach(year => {
    for (let month = 0; month < 12; month++) {
      // Seed based variation
      const seed = (year * 12) + month;
      const variation = (seed * 233) % 4000; // Fluctuation +/-
      const quarterlyBonus = (month + 1) % 3 === 0 ? 15000 + (seed % 7000) : 0;
      const yearEndBonus = month === 11 ? 55000 : 0; 
      const overtime = (seed % 5 === 0) ? 4200 : 0;

      const salaryAmount = baseSalary + variation + quarterlyBonus + yearEndBonus + overtime;

      let salaryNote = 'Зарплата';
      if (yearEndBonus > 0) salaryNote = 'Зарплата + Годовая премия 🎄';
      else if (quarterlyBonus > 0) salaryNote = 'Зарплата + Квартальная премия 💰';
      else if (overtime > 0) salaryNote = 'Зарплата + Сверхурочные ⚡️';

      // Salary (10th)
      transactions.push({
        id: `gen_${year}_sal_${month}`,
        amount: salaryAmount,
        type: 'income',
        category: 'salary',
        memberId: 'm1',
        note: salaryNote,
        date: new Date(year, month, 10, 10, 0, 0).toISOString()
      });

      // Advance (25th)
      const advanceVariation = (seed * 89) % 1200;
      transactions.push({
        id: `gen_${year}_adv_${month}`,
        amount: baseAdvance + advanceVariation,
        type: 'income',
        category: 'salary',
        memberId: 'm1',
        note: 'Аванс 💸',
        date: new Date(year, month, 25, 10, 0, 0).toISOString()
      });
    }
  });
  return transactions;
};

