                                            {event.description && (
                                                <div className="flex items-start gap-3 text-sm font-medium text-gray-500 dark:text-gray-400 leading-relaxed bg-[#F2F2F7]/50 dark:bg-white/5 p-4 rounded-2xl border border-black/[0.02] dark:border-white/[0.02]">
                                                    {event.description}
