// Улучшенный генератор зарплат для двоих участников
const generateSalaryData = (): Transaction[] => {
  const transactions: Transaction[] = [];
  const startYear = new Date().getFullYear() - 1;

  const roles = [
    { id: 'm1', name: 'Папа', baseSal: 95000, baseAdv: 45000, salDay: 10, advDay: 25, bonusMult: 1.2 },
    { id: 'm2', name: 'Мама', baseSal: 72000, baseAdv: 32000, salDay: 5, advDay: 20, bonusMult: 0.8 }
  ];

  [startYear, startYear + 1, startYear + 2].forEach(year => {
    for (let month = 0; month < 12; month++) {
      roles.forEach(role => {
        const seed = (year * 12) + month + (role.id === 'm1' ? 0 : 50);

        // 1. Вариативность базы (премии, переработки)
        const variation = (seed * 197) % 5000; 
        const efficiencyBonus = (seed % 7 === 0) ? 8000 : 0;

        // 2. Квартальные премии (разные для каждого)
        const isQuarterEnd = (month + 1) % 3 === 0;
        const quarterlyBonus = isQuarterEnd ? (15000 * role.bonusMult) + (seed % 4000) : 0;

        // 3. Годовая премия (13-я зарплата)
        const yearEndBonus = (month === 11) ? (role.baseSal * 0.5) : 0;

        const totalSalary = role.baseSal + variation + efficiencyBonus + quarterlyBonus + yearEndBonus;

        let note = `Зарплата (${role.name})`;
        if (yearEndBonus > 0) note += ' + 13-я 🎄';
        else if (quarterlyBonus > 0) note += ' + Квартальный бонус 💰';
        else if (efficiencyBonus > 0) note += ' + Премия 🚀';

        // Основная часть
        transactions.push({
          id: `sal_${role.id}_${year}_${month}`,
          amount: Math.round(totalSalary),
          type: 'income',
          category: 'salary',
          memberId: role.id,
          note: note,
          date: new Date(year, month, role.salDay, 10, 0, 0).toISOString()
        });

        // Аванс
        const advVariation = (seed * 131) % 2000;
        transactions.push({
          id: `adv_${role.id}_${year}_${month}`,
          amount: Math.round(role.baseAdv + advVariation),
          type: 'income',
          category: 'salary',
          memberId: role.id,
          note: `Аванс (${role.name}) 💸`,
          date: new Date(year, month, role.advDay, 10, 0, 0).toISOString()
        });
      });
    }
  });
  return transactions;
};

